import { createClient } from '@/lib/supabase/server';
import { redirect } from 'next/navigation';

export async function POST(request: Request) {
    const supabase = await createClient();

    // 1. Check if a user session exists before trying to sign out
    const { data: { user } } = await supabase.auth.getUser();

    if (user) {
        await supabase.auth.signOut();
    }

    // 2. Redirect back to the login page
    redirect('/login');
}

'use client';
import { processPayroll } from './actions';
import { Send } from 'lucide-react';

export default function AdvanceForm({ profiles }: { profiles: any[] }) {
    return (
        <div className="bg-white border border-slate-200 p-4 rounded-xl">
            <p className="text-sm font-medium text-slate-900 mb-3">Record an advance</p>
            <form action={processPayroll} className="grid grid-cols-[minmax(0,1fr)_96px_40px] gap-2">
                <select aria-label="Employee for advance" name="employeeId" required className="min-w-0 bg-slate-50 border border-slate-200 rounded-xl text-sm font-medium px-3 py-2 focus:ring-1 ring-indigo-500 outline-none flex-1">
                    <option value="">Employee</option>
                    {profiles.map(p => <option key={p.id} value={p.id}>{p.full_name}</option>)}
                </select>
                <input aria-label="Advance amount in rupees" type="number" name="netPay" placeholder="Amount" required className="w-24 min-w-0 bg-slate-50 border border-slate-200 rounded-xl text-sm font-medium py-2 px-3 focus:ring-1 ring-indigo-500 outline-none" />
                <input type="hidden" name="type" value="advance" />
                <button aria-label="Record advance" className="bg-slate-900 text-white p-2 rounded-xl hover:bg-indigo-500 transition-colors">
                    <Send size={14} />
                </button>
            </form>
        </div>
    );
}

'use client';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { FileText, History as HistoryIcon } from 'lucide-react';
import { useEffect, useState } from 'react';

export default function PayrollHistory({ history }: { history: any[] }) {
    // State to handle hydration
    const [mounted, setMounted] = useState(false);

    useEffect(() => {
        setMounted(true);
    }, []);

    const downloadPDF = (rec: any) => {
        const generateFailsafeOrSuccess = (imgElement: HTMLImageElement | null) => {
            const doc = new jsPDF();
            const dateStr = new Date(rec.month_year).toLocaleString('en-IN', { month: 'long', year: 'numeric' });

            if (imgElement) {
                doc.addImage(imgElement, 'PNG', 95, 15, 20, 20); // Center standard 20x20
            }

            doc.setFontSize(22);
            doc.setFont("times", "bold");
            doc.text("THE MAKEUP STORE", 105, imgElement ? 45 : 25, { align: "center" });

            doc.setFontSize(10);
            doc.setFont("helvetica", "normal");
            doc.setTextColor(100);
            doc.text("Official Payslip & Settlement Record", 105, imgElement ? 51 : 31, { align: "center" });

            // Settlement Tracker
            const thisMonthHistory = history.filter(h => h.employee_id === rec.employee_id && new Date(h.month_year).getMonth() === new Date(rec.month_year).getMonth());
            const totalPaidThisMonth = thisMonthHistory.reduce((sum, h) => sum + h.net_pay, 0);

            // Values
            const grossPay = Math.round(rec.gross_pay || 0);
            const netPay = Math.round(rec.net_pay || 0);
            const settlementLeft = Math.max(0, grossPay - totalPaidThisMonth);

            autoTable(doc, {
                startY: imgElement ? 65 : 45,
                margin: { left: 30, right: 30 }, // Constrict width heavily to center the table structurally
                head: [['Description', 'Amount (INR)']],
                body: [
                    ['Employee Name', rec.profiles?.full_name || 'N/A'],
                    ['Pay Period', dateStr],
                    ['Settlement Type', rec.type?.toUpperCase() || 'SALARY'],
                    ['Gross Base Earnings', grossPay.toLocaleString('en-IN')],
                    ['Overtime Compensation', Math.round(rec.overtime_pay).toLocaleString('en-IN')],
                    ['Bonus Allocation', Math.round(rec.bonus_pay).toLocaleString('en-IN')],
                    ['Deductions', `- ${Math.round(rec.deductions).toLocaleString('en-IN')}`],
                    ['NET SETTLEMENT', netPay.toLocaleString('en-IN')],
                    ['OUTSTANDING BALANCE', settlementLeft > 0 ? settlementLeft.toLocaleString('en-IN') : 'FULLY SETTLED'],
                ],
                theme: 'grid',
                headStyles: { fillColor: [15, 23, 42] },
                styles: { fontSize: 10, cellPadding: 8 },
                columnStyles: {
                    0: { fontStyle: 'bold', textColor: [30, 41, 59] },
                    1: { halign: 'right', textColor: [71, 85, 105], fontStyle: 'bold' }
                },
                didParseCell: function (data) {
                    if (data.row.index === 7 || data.row.index === 8) {
                        data.cell.styles.fontStyle = 'bold';
                        data.cell.styles.textColor = [15, 23, 42];
                    }
                }
            });

            // Footer Security Clause
            doc.setFontSize(8);
            doc.setTextColor(150);
            doc.text("This is a computer-generated document. No signature is required.", 105, 280, { align: "center" });

            doc.save(`Payslip_${(rec.profiles?.full_name || '').replace(/ /g, '_')}_${dateStr.replace(/ /g, '_')}.pdf`);
        };

        // Try dynamically loading the store icon from public folder
        const img = new Image();
        img.src = '/icon-512x512.png';
        img.onload = () => generateFailsafeOrSuccess(img);
        img.onerror = () => generateFailsafeOrSuccess(null);
    };

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-medium flex items-center gap-3">
                <HistoryIcon /> Transaction history
            </h2>
            <div className="bg-white rounded-xl border border-slate-100 overflow-x-auto">
                <table className="w-full min-w-[640px] text-left text-sm">
                    <thead className="bg-slate-50 text-sm font-medium text-slate-500">
                        <tr>
                            <th className="px-8 py-4">Date</th>
                            <th className="px-6 py-4">Personnel</th>
                            <th className="px-6 py-4">Type</th>
                            <th className="px-6 py-4 text-center">Amount (₹)</th>
                            <th className="px-8 py-4 text-right">Action</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                        {history.map((rec) => (
                            <tr key={rec.id} className="hover:bg-slate-50/50 transition-colors">
                                <td className="px-8 py-4 font-medium text-slate-500">
                                    {/* Only render date on client to avoid mismatch */}
                                    {mounted ? new Date(rec.created_at).toLocaleDateString('en-IN') : '---'}
                                </td>
                                <td className="px-6 py-4 font-medium">{rec.profiles?.full_name}</td>
                                <td className="px-6 py-4 text-sm font-medium tracking-normal text-slate-500">
                                    {rec.type}
                                </td>
                                <td className="px-6 py-4 text-center font-medium text-slate-900">
                                    ₹{rec.net_pay.toLocaleString('en-IN')}
                                </td>
                                <td className="px-8 py-4 text-right">
                                    <button
                                        aria-label={`Download payslip for ${rec.profiles?.full_name || "staff member"}`} onClick={() => downloadPDF(rec)}
                                        className="p-2 hover:bg-slate-900 hover:text-white rounded-xl transition-colors"
                                    >
                                        <FileText size={18} />
                                    </button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
}

'use client';
import { useState } from 'react';
import { processPayroll } from './actions';
import { IndianRupee, Zap, Calculator } from 'lucide-react';

export default function PayrollTable({ initialData, history }: { initialData: any[], history: any[] }) {
    const [adjustments, setAdjustments] = useState<Record<string, any>>(
        Object.fromEntries(initialData.map(d => [d.employee_id, { overtime: 0, bonus: 0, deduct: 0, overrideBase: null }]))
    );

    const updateAdjust = (id: string, field: string, val: string) => {
        setAdjustments(prev => ({
            ...prev,
            [id]: { ...prev[id], [field]: val === '' && field === 'overrideBase' ? null : (parseFloat(val) || 0) }
        }));
    };

    const handleAutoOT = (id: string, otHours: number, rate: number) => {
        if (otHours > 0) {
            const otPay = Math.round(otHours * (rate * 1.5));
            updateAdjust(id, 'overtime', String(otPay));
        }
    };

    return (
        <div className="bg-white border border-slate-100 rounded-xl overflow-x-auto">
            <table className="w-full min-w-[800px] text-left">
                <thead className="bg-slate-50 border-b border-slate-100 text-sm font-medium text-slate-500">
                    <tr>
                        <th className="px-8 py-6">Personnel / Details</th>
                        <th className="px-4 py-6 text-center">Gross Pay (₹)</th>
                        <th className="px-4 py-6 text-center">OT (₹)</th>
                        <th className="px-4 py-6 text-center">Bonus (₹)</th>
                        <th className="px-4 py-6 text-center">Deduct (₹)</th>
                        <th className="px-8 py-6 text-right text-indigo-600">Balance Due</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                    {initialData.map((row) => {
                        const id = row.employee_id;
                        const rate = row.profile?.hourly_rate || 0;
                        const totalHours = row.total_hours || 0;
                        const defaultTotalEarnings = Math.round(totalHours * rate);

                        const adj = adjustments[id] || { overtime: 0, bonus: 0, deduct: 0, overrideBase: null };
                        const activeBaseEarnings = adj.overrideBase !== null ? (parseFloat(adj.overrideBase) || 0) : defaultTotalEarnings;

                        // Calculate already paid (Advances/Partial Salary)
                        const currentMonthNum = new Date().getMonth();
                        const alreadyPaid = Array.isArray(history)
                            ? history
                                .filter(h => h.employee_id === id && new Date(h.month_year).getMonth() === currentMonthNum)
                                .reduce((sum, rec) => sum + rec.net_pay, 0)
                            : 0;

                        // Ensure balance due cannot drop strictly below 0 structurally if advance is higher
                        const balanceDue = Math.max(0, activeBaseEarnings - alreadyPaid);

                        // Final settlement is base due + bonuses - deductions
                        const finalNet = Math.round(balanceDue + (adj.overtime || 0) + (adj.bonus || 0) - (adj.deduct || 0));

                        return (
                            <tr key={id} className="hover:bg-slate-50/30 transition-colors group">
                                <td className="px-8 py-6">
                                    <p className="font-medium text-slate-900 leading-none">{row.full_name}</p>
                                    <div className="flex flex-col gap-1 mt-2">
                                        <p className="text-sm font-medium text-slate-500">Expected: {totalHours} hrs × ₹{rate}/hr = ₹{defaultTotalEarnings.toLocaleString('en-IN')}</p>
                                        <p className="text-sm font-medium text-emerald-500 flex items-center gap-1">
                                            {alreadyPaid > 0 ? `Paid Advance: ₹${alreadyPaid.toLocaleString('en-IN')}` : 'No Advance Drawn'}
                                        </p>
                                    </div>
                                </td>
                                <td className="px-4 py-6">
                                    <div className="flex flex-col items-center gap-1">
                                        <input type="number"
                                            value={adj.overrideBase !== null ? adj.overrideBase : defaultTotalEarnings}
                                            placeholder="Base"
                                            className="w-24 bg-indigo-50/50 p-2 rounded-xl text-center text-xs font-medium outline-none focus:bg-indigo-100"
                                            onChange={(e) => updateAdjust(id, 'overrideBase', e.target.value)}
                                        />
                                        <span className="text-xs font-medium text-indigo-400">Review Gross</span>
                                    </div>
                                </td>
                                <td className="px-4 py-6">
                                    <div className="flex flex-col items-center gap-1">
                                        <input type="number" value={adj.overtime || ''} placeholder="0" className="w-20 bg-orange-50 p-2 rounded-xl text-center text-xs font-medium outline-none focus:bg-orange-100" onChange={(e) => updateAdjust(id, 'overtime', e.target.value)} />
                                        <button type="button" onClick={() => handleAutoOT(id, row.total_ot || 0, rate)} className="text-xs font-medium text-orange-500 transition-colors outline-none">Auto OT ({row.total_ot || 0}h)</button>
                                    </div>
                                </td>
                                <td className="px-4 py-6">
                                    <input type="number" value={adj.bonus || ''} placeholder="0" className="w-20 bg-emerald-50 p-2 rounded-xl text-center text-xs font-medium outline-none focus:bg-emerald-100" onChange={(e) => updateAdjust(id, 'bonus', e.target.value)} />
                                </td>
                                <td className="px-4 py-6">
                                    <input type="number" value={adj.deduct || ''} placeholder="0" className="w-20 bg-rose-50 p-2 rounded-xl text-center text-xs font-medium outline-none focus:bg-rose-100" onChange={(e) => updateAdjust(id, 'deduct', e.target.value)} />
                                </td>
                                <td className="px-8 py-6 text-right">
                                    <div className="flex flex-col items-end gap-2">
                                        <span className={`text-xl font-medium  ${finalNet < 0 ? 'text-rose-500' : 'text-slate-900'}`}>
                                            ₹{finalNet.toLocaleString('en-IN')}
                                        </span>
                                        <form action={processPayroll}>
                                            <input type="hidden" name="employeeId" value={id} />
                                            <input type="hidden" name="baseHours" value={totalHours} />
                                            <input type="hidden" name="grossPay" value={activeBaseEarnings} />
                                            <input type="hidden" name="overtime" value={adj.overtime} />
                                            <input type="hidden" name="bonus" value={adj.bonus} />
                                            <input type="hidden" name="deductions" value={adj.deduct} />
                                            <input type="hidden" name="netPay" value={finalNet} />
                                            <input type="hidden" name="type" value="salary" />

                                            <button
                                                disabled={finalNet <= 0 && balanceDue <= 0 && adj.bonus === 0}
                                                className="bg-slate-900 text-white text-xs font-medium px-4 py-2 rounded-lg hover:bg-indigo-600 transition-colors disabled:bg-slate-100 disabled:text-slate-500 disabled:shadow-none"
                                            >
                                                Settle Earnings
                                            </button>
                                        </form>
                                    </div>
                                </td>
                            </tr>
                        );
                    })}
                </tbody>
            </table>
        </div>
    );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import {
    Calendar, User, Clock, Loader2, FileDown, TrendingUp, AlertCircle
} from 'lucide-react';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';

export default function ConsolidatedOutputReport() {
    const supabase = createClient();
    const [employees, setEmployees] = useState<any[]>([]);
    const [selectedEmployee, setSelectedEmployee] = useState<string>('');
    const [selectedMonth, setSelectedMonth] = useState<string>(new Date().toISOString().slice(0, 7)); // 'YYYY-MM'

    const [reportData, setReportData] = useState<any[]>([]);
    const [summary, setSummary] = useState<any>(null);
    const [loading, setLoading] = useState(false);

    // Fetch initial employee list
    useEffect(() => {
        async function loadEmployees() {
            const { data } = await supabase.from('profiles').select('id, full_name, username').order('full_name');
            if (data) {
                setEmployees(data);
                if (data.length > 0) setSelectedEmployee(data[0].id);
            }
        }
        loadEmployees();
    }, [supabase]);

    const formatTimeOnly = (isoString: string) => {
        if (!isoString) return '—';
        return new Date(isoString).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });
    };

    const formatShiftTimeOnly = (isoString: string) => {
        if (!isoString) return '—';
        return new Date(isoString).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', timeZone: 'UTC' });
    };

    const formatDuration = (hoursDecimal: number) => {
        if (hoursDecimal <= 0) return '—';
        const h = Math.floor(hoursDecimal);
        const m = Math.round((hoursDecimal - h) * 60);
        if (h === 0) return `${m}m`;
        return `${h}h ${m}m`;
    };

    const fetchReport = useCallback(async () => {
        if (!selectedEmployee || !selectedMonth) return;
        setLoading(true);

        const year = parseInt(selectedMonth.split('-')[0]);
        const month = parseInt(selectedMonth.split('-')[1]) - 1; // 0-indexed month
        const daysInMonth = new Date(year, month + 1, 0).getDate();

        const monthStart = `${selectedMonth}-01T00:00:00Z`;
        const monthEnd = `${selectedMonth}-${String(daysInMonth).padStart(2, '0')}T23:59:59Z`;

        const [shiftsRes, attRes] = await Promise.all([
            // Fetch Shifts
            supabase.from('shifts')
                .select('*')
                .eq('employee_id', selectedEmployee)
                .gte('start_time', monthStart)
                .lte('start_time', monthEnd),
            // Fetch Attendance
            supabase.from('attendance')
                .select('*')
                .eq('employee_id', selectedEmployee)
                .gte('check_in', monthStart)
                .lte('check_in', monthEnd)
        ]);

        const shifts = shiftsRes.data || [];
        const attendance = attRes.data || [];

        let totalWorkedHours = 0;
        let totalOvertimeHours = 0;
        let totalEarlyInHours = 0;
        let totalLateInHours = 0;
        let presentDays = 0;

        const dailyData = Array.from({ length: daysInMonth }, (_, i) => {
            const dayNum = i + 1;
            const dateStr = `${selectedMonth}-${String(dayNum).padStart(2, '0')}`;

            // Find Shift
            const shift = shifts.find(s => s.start_time.startsWith(dateStr));

            // Find Attendance (Try matching by shift_id first, fallback to date match via check_in)
            const att = attendance.find(a =>
                (shift && a.shift_id === shift.id) || a.check_in.startsWith(dateStr)
            );

            let workedHours = 0;
            let earlyInHours = 0;
            let lateInHours = 0;
            let overtimeHours = 0;

            if (att && att.check_in) {
                presentDays++;
                const checkInTime = new Date(att.check_in).getTime();
                const checkOutTime = att.check_out ? new Date(att.check_out).getTime() : new Date().getTime(); // ongoing if no checkout

                // Calculate worked hours (either actual or ongoing)
                workedHours = (checkOutTime - checkInTime) / (1000 * 60 * 60);
                if (workedHours > 0) {
                    totalWorkedHours += workedHours;
                }

                if (shift) {
                    const shiftStartMs = (() => {
                        const d = new Date(dateStr + 'T00:00:00'); // start with local day at midnight
                        const sD = new Date(shift.start_time);
                        d.setHours(sD.getUTCHours(), sD.getUTCMinutes(), 0, 0); // Inject literal UI time into it
                        return d.getTime();
                    })();

                    const shiftEndMs = (() => {
                        const d = new Date(dateStr + 'T00:00:00');
                        const sD = new Date(shift.end_time || '');
                        d.setHours(sD.getUTCHours(), sD.getUTCMinutes(), 0, 0);
                        return d.getTime();
                    })();

                    // Calculate Early In
                    if (checkInTime < shiftStartMs) {
                        earlyInHours = (shiftStartMs - checkInTime) / (1000 * 60 * 60);
                        if(earlyInHours > 0) totalEarlyInHours += earlyInHours;
                    }

                    // Calculate Late In
                    if (checkInTime > shiftStartMs) {
                        lateInHours = (checkInTime - shiftStartMs) / (1000 * 60 * 60);
                        if(lateInHours > 0) totalLateInHours += lateInHours;
                    }

                    // Calculate Overtime (Late Out)
                    if (att.check_out && checkOutTime > shiftEndMs) {
                        overtimeHours = (checkOutTime - shiftEndMs) / (1000 * 60 * 60);
                        if(overtimeHours > 0) totalOvertimeHours += overtimeHours;
                    }
                }
            }

            return {
                date: dateStr,
                displayDate: new Date(dateStr + 'T12:00:00').toLocaleDateString('en-US', { weekday: 'short', day: 'numeric', month: 'short' }),
                shift: shift ? `${formatShiftTimeOnly(shift.start_time)} - ${formatShiftTimeOnly(shift.end_time || '')}` : 'Off',
                shift_label: shift?.shift_label || null,
                checkIn: att ? formatTimeOnly(att.check_in) : '—',
                checkOut: att?.check_out ? formatTimeOnly(att.check_out) : (att ? 'Active' : '—'),
                workedText: workedHours > 0 ? formatDuration(workedHours) : (att && !att.check_out ? 'Ongoing' : '—'),
                earlyIn: earlyInHours > 0 ? formatDuration(earlyInHours) : '—',
                lateIn: lateInHours > 0 ? formatDuration(lateInHours) : '—',
                overtime: overtimeHours > 0 ? formatDuration(overtimeHours) : '—'
            };
        });

        setReportData(dailyData);
        setSummary({
            totalWorked: formatDuration(totalWorkedHours),
            totalEarlyIn: formatDuration(totalEarlyInHours),
            totalLateIn: formatDuration(totalLateInHours),
            totalOvertime: formatDuration(totalOvertimeHours),
            presentDays,
            totalDays: daysInMonth
        });

        setLoading(false);
    }, [selectedEmployee, selectedMonth, supabase]);

    useEffect(() => {
        fetchReport();
    }, [fetchReport]);

    const exportToPDF = () => {
        const doc = new jsPDF();
        const empName = employees.find(e => e.id === selectedEmployee)?.full_name || 'Employee';
        const pageW = doc.internal.pageSize.getWidth();

        // Header
        doc.setFontSize(22);
        doc.setTextColor(15, 23, 42);
        doc.text('Consolidated Attendance Report', 14, 22);

        doc.setFontSize(10);
        doc.setTextColor(100, 116, 139);
        doc.text(`Employee: ${empName}     Month: ${selectedMonth}`, 14, 30);

        // Divider line
        doc.setDrawColor(226, 232, 240);
        doc.line(14, 35, pageW - 14, 35);

        // Summary Metrics Box
        const metrics = [
            { label: 'Total Worked', value: summary.totalWorked, color: [99, 102, 241] },
            { label: 'Early In', value: summary.totalEarlyIn, color: [16, 185, 129] },
            { label: 'Late In', value: summary.totalLateIn, color: [249, 115, 22] },
            { label: 'Overtime', value: summary.totalOvertime, color: [245, 158, 11] },
            { label: 'Present', value: `${summary.presentDays} / ${summary.totalDays}`, color: [59, 130, 246] },
        ];

        // Filled background for metrics
        doc.setFillColor(248, 250, 252);
        doc.roundedRect(14, 40, pageW - 28, 14, 2, 2, 'F');

        let mx = 20;
        const swatchW = 4;
        const gap = (pageW - 40) / metrics.length;
        metrics.forEach((m) => {
            doc.setFillColor(m.color[0], m.color[1], m.color[2]);
            doc.rect(mx, 44, swatchW, swatchW, 'F');
            doc.setFontSize(7);
            doc.setTextColor(100, 116, 139);
            doc.text(m.label, mx + 7, 47);
            doc.setFontSize(9);
            doc.setFont('helvetica', 'bold');
            doc.setTextColor(15, 23, 42);
            doc.text(m.value, mx + 7, 53);
            doc.setFont('helvetica', 'normal');
            mx += gap;
        });

        autoTable(doc, {
            startY: 62,
            headStyles: { fillColor: [15, 23, 42] }, // slate-900
            head: [['Date', 'Shift', 'Check In', 'Check Out', 'Early In', 'Late In', 'Overtime', 'Total Worked']],
            body: reportData.map(row => [
                row.displayDate,
                row.shift,
                row.checkIn,
                row.checkOut,
                row.earlyIn,
                row.lateIn,
                row.overtime,
                row.workedText
            ]),
        });

        doc.save(`${empName.replace(/\s+/g, '_')}_${selectedMonth}_Report.pdf`);
    };

    return (
        <div className="space-y-8">
            {/* Header & Controls */}
            <header className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                <div className="space-y-1">
                    <h1 className="text-3xl font-medium tracking-normal text-slate-900">Consolidated attendance</h1>
                    <p className="text-sm font-medium text-slate-500 tracking-normal">
                        Detailed monthly attendance metrics
                    </p>
                </div>

                <div className="flex flex-wrap items-center gap-4 bg-slate-50 p-2 rounded-xl border border-slate-100">
                    <div className="flex items-center gap-3 px-3 py-2 bg-white rounded-xl shadow-sm border border-slate-100">
                        <User size={16} className="text-slate-500" />
                        <select
                            value={selectedEmployee}
                            onChange={(e) => setSelectedEmployee(e.target.value)}
                            className="bg-transparent text-xs font-medium text-slate-700 outline-none cursor-pointer"
                        >
                            {employees.map(emp => (
                                <option key={emp.id} value={emp.id}>{emp.full_name}</option>
                            ))}
                        </select>
                    </div>

                    <div className="flex items-center gap-3 px-3 py-2 bg-white rounded-xl shadow-sm border border-slate-100">
                        <Calendar size={16} className="text-slate-500" />
                        <input
                            type="month"
                            value={selectedMonth}
                            onChange={(e) => setSelectedMonth(e.target.value)}
                            className="bg-transparent text-xs font-medium text-slate-700 outline-none cursor-pointer"
                        />
                    </div>
                </div>
            </header>

            {loading ? (
                <div className="py-32 flex flex-col items-center justify-center gap-4 ">
                    <Loader2 className="animate-spin text-slate-900" size={32} />
                    <p className="text-sm font-medium tracking-normal">Loading attendance report</p>
                </div>
            ) : (
                <>
                    <div className="space-y-8">

                        {/* Summary Cards */}
                        {summary && (
                            <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                                <SummaryCard label="Total Worked" value={summary.totalWorked} icon={<Clock size={20} />} color="indigo" />
                                <SummaryCard label="Total Early In" value={summary.totalEarlyIn} icon={<TrendingUp size={20} />} color="emerald" />
                                <SummaryCard label="Total Late In" value={summary.totalLateIn} icon={<Clock size={20} />} color="orange" />
                                <SummaryCard label="Total Overtime" value={summary.totalOvertime} icon={<AlertCircle size={20} />} color="amber" />
                                <SummaryCard label="Days Present" value={`${summary.presentDays} / ${summary.totalDays}`} icon={<Calendar size={20} />} color="blue" />
                            </div>
                        )}

                        {/* Data Table */}
                        <div className="bg-white border border-slate-100 rounded-xl shadow-sm overflow-hidden">
                            <div className="flex justify-between items-center p-6 border-b border-slate-100 bg-slate-50/50">
                                <h3 className="text-sm font-medium tracking-normal text-slate-800">Daily Breakdown</h3>
                                <button
                                    onClick={exportToPDF}
                                    className="flex items-center gap-2 px-4 py-2 bg-slate-900 text-white rounded-xl text-sm font-medium tracking-normal hover:bg-slate-800 transition-colors"
                                >
                                    <FileDown size={14} /> Export PDF
                                </button>
                            </div>
                            <div className="overflow-x-auto">
                                <table className="w-full text-left min-w-[800px]">
                                    <thead>
                                        <tr className="bg-slate-50 border-b border-slate-100">
                                            <th className="px-6 py-4 text-xs font-medium text-slate-500 tracking-normal">Date</th>
                                            <th className="px-6 py-4 text-xs font-medium text-slate-500 tracking-normal">Shift Schedule</th>
                                            <th className="px-6 py-4 text-xs font-medium text-slate-500 tracking-normal">Check In</th>
                                            <th className="px-6 py-4 text-xs font-medium text-slate-500 tracking-normal">Check Out</th>
                                            <th className="px-6 py-4 text-xs font-medium text-emerald-500 tracking-normal bg-emerald-50/30">Early In</th>
                                            <th className="px-6 py-4 text-xs font-medium text-orange-500 tracking-normal bg-orange-50/30">Late In</th>
                                            <th className="px-6 py-4 text-xs font-medium text-amber-500 tracking-normal bg-amber-50/30">Overtime</th>
                                            <th className="px-6 py-4 text-xs font-medium text-slate-900 tracking-normal bg-slate-100/50">Total Worked</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-50">
                                        {reportData.map((row, idx) => (
                                            <tr key={idx} className="hover:bg-slate-50 transition-colors">
                                                <td className="px-6 py-4 whitespace-nowrap">
                                                    <span className="text-xs font-medium text-slate-900">{row.displayDate}</span>
                                                </td>
                                                <td className="px-6 py-4 whitespace-nowrap">
                                                    <span className={`text-sm font-medium  ${row.shift === 'Off' ? 'text-rose-400' : 'text-slate-500'}`}>
                                                        {row.shift}
                                                        {row.shift_label && <span className="ml-1 ">({row.shift_label})</span>}
                                                    </span>
                                                </td>
                                                <td className="px-6 py-4 whitespace-nowrap text-xs font-medium text-slate-600">{row.checkIn}</td>
                                                <td className="px-6 py-4 whitespace-nowrap text-xs font-medium text-slate-600">
                                                    {row.checkOut === 'Active' ? <span className="text-emerald-500 font-medium">Active</span> : row.checkOut}
                                                </td>

                                                {/* Early In Column */}
                                                <td className="px-6 py-4 whitespace-nowrap bg-emerald-50/10">
                                                    <span className={`text-xs font-medium ${row.earlyIn !== '—' ? 'text-emerald-600' : 'text-slate-500'}`}>
                                                        {row.earlyIn}
                                                    </span>
                                                </td>

                                                {/* Late In Column */}
                                                <td className="px-6 py-4 whitespace-nowrap bg-orange-50/10">
                                                    <span className={`text-xs font-medium ${row.lateIn !== '—' ? 'text-orange-600' : 'text-slate-500'}`}>
                                                        {row.lateIn}
                                                    </span>
                                                </td>

                                                {/* Overtime Column */}
                                                <td className="px-6 py-4 whitespace-nowrap bg-amber-50/10">
                                                    <span className={`text-xs font-medium ${row.overtime !== '—' ? 'text-amber-600' : 'text-slate-500'}`}>
                                                        {row.overtime}
                                                    </span>
                                                </td>

                                                {/* Total Worked */}
                                                <td className="px-6 py-4 whitespace-nowrap bg-slate-50/30">
                                                    <span className="text-sm font-medium text-indigo-600 tracking-normal">
                                                        {row.workedText}
                                                    </span>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>
                </>
            )}
        </div>
    );
}

function SummaryCard({ label, value, icon, color }: any) {
    const colors: any = {
        indigo: 'bg-indigo-50 text-indigo-600 border-indigo-100',
        emerald: 'bg-emerald-50 text-emerald-600 border-emerald-100',
        amber: 'bg-amber-50 text-amber-600 border-amber-100',
        blue: 'bg-blue-50 text-blue-600 border-blue-100',
        orange: 'bg-orange-50 text-orange-600 border-orange-100',
    };

    return (
        <div className={`p-6 rounded-xl border ${colors[color]} flex flex-col items-start gap-4`}>
            <div className="p-3 bg-white/60 rounded-xl shadow-sm">
                {icon}
            </div>
            <div>
                <p className="text-xs font-medium tracking-normal  mb-1">{label}</p>
                <p className="text-2xl font-medium tracking-normal leading-none">{value}</p>
            </div>
        </div>
    );
}

'use client';

import { Fragment, useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { Calendar, Loader2, BarChart3, PieChart, TrendingUp, Grid3x3, Clock } from 'lucide-react';
import {
    BarChart, Bar, XAxis, YAxis, Tooltip, Legend, CartesianGrid,
    ResponsiveContainer, PieChart as RePieChart, Pie, Cell,
    LineChart, Line
} from 'recharts';

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

const PUNCTUALLY_GRACE_MINUTES = 5;

const COLORS = [
    '#8f596e', '#527a67', '#527791', '#a67c44', '#7d7591', '#657b85',
    '#9b6d5d', '#697d4c', '#7f6b77', '#547f7c', '#9a805f', '#777c64',
];

export default function AttendanceGraphs() {
    const supabase = createClient();
    const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7));
    const [loading, setLoading] = useState(false);

    const [employees, setEmployees] = useState<any[]>([]);
    const [monthlyTotals, setMonthlyTotals] = useState<any[]>([]);
    const [dailyTrend, setDailyTrend] = useState<any[]>([]);
    const [punctuality, setPunctuality] = useState<any[]>([]);
    const [donut, setDonut] = useState<any[]>([]);
    const [weeklyTrend, setWeeklyTrend] = useState<any[]>([]);
    const [heatmap, setHeatmap] = useState<any[]>([]);

    const fetchAllData = useCallback(async () => {
        setLoading(true);

        const [yearStr, monthStr] = selectedMonth.split('-');
        const year = parseInt(yearStr);
        const month = parseInt(monthStr);
        const daysInMonth = new Date(year, month, 0).getDate();
        const monthStart = `${selectedMonth}-01T00:00:00Z`;
        const monthEnd = `${selectedMonth}-${String(daysInMonth).padStart(2, '0')}T23:59:59Z`;

        const [profilesRes, shiftsRes, attRes] = await Promise.all([
            supabase.from('profiles').select('id, full_name').eq('role', 'employee').order('full_name'),
            supabase.from('shifts').select('*').gte('start_time', monthStart).lte('start_time', monthEnd),
            supabase.from('attendance').select('*').gte('check_in', monthStart).lte('check_in', monthEnd),
        ]);

        const allEmployees = profilesRes.data || [];
        const allShifts = shiftsRes.data || [];
        const allAttendance = attRes.data || [];
        setEmployees(allEmployees);

        const empDailyMap: Record<string, Record<string, any>> = {};
        for (const emp of allEmployees) {
            empDailyMap[emp.id] = {};
        }

        let presCount = 0, absCount = 0, offCount = 0;

        for (let d = 1; d <= daysInMonth; d++) {
            const dateStr = `${selectedMonth}-${String(d).padStart(2, '0')}`;

            for (const emp of allEmployees) {
                const shift = allShifts.find(
                    (s: any) => s.employee_id === emp.id && s.start_time.startsWith(dateStr)
                );

                if (!shift) {
                    offCount++;
                    empDailyMap[emp.id][dateStr] = { hours: 0, punctuality: 'off' };
                    continue;
                }

                const att = allAttendance.find(
                    (a: any) => (a.shift_id === shift.id) || (a.employee_id === emp.id && a.check_in.startsWith(dateStr))
                );

                if (!att || !att.check_in) {
                    absCount++;
                    empDailyMap[emp.id][dateStr] = { hours: 0, punctuality: 'absent' };
                    continue;
                }

                presCount++;

                const checkInTime = new Date(att.check_in).getTime();
                const checkOutTime = att.check_out ? new Date(att.check_out).getTime() : Date.now();
                const hours = Math.round(((checkOutTime - checkInTime) / (1000 * 60 * 60)) * 100) / 100;

                const shiftStartMs = (() => {
                    const d2 = new Date(dateStr + 'T00:00:00');
                    const sD = new Date(shift.start_time);
                    d2.setHours(sD.getUTCHours(), sD.getUTCMinutes(), 0, 0);
                    return d2.getTime();
                })();

                const diffMin = (checkInTime - shiftStartMs) / (1000 * 60);
                let punct = 'onTime';
                if (diffMin < -PUNCTUALLY_GRACE_MINUTES) punct = 'early';
                else if (diffMin > PUNCTUALLY_GRACE_MINUTES) punct = 'late';

                empDailyMap[emp.id][dateStr] = { hours: Math.max(hours, 0), punctuality: punct };
            }
        }

        // --- 1. Monthly Total Hours per Employee (simple bar) ---
        const totalsData = allEmployees.map((emp) => {
            let total = 0;
            for (let d = 1; d <= daysInMonth; d++) {
                const dateStr = `${selectedMonth}-${String(d).padStart(2, '0')}`;
                total += empDailyMap[emp.id][dateStr]?.hours || 0;
            }
            return { name: emp.full_name, hours: Math.round(total * 100) / 100 };
        });
        setMonthlyTotals(totalsData);

        // --- 2. Daily Hours Trend (lines per employee) ---
        const trendData: any[] = [];
        for (let d = 1; d <= daysInMonth; d++) {
            const dateStr = `${selectedMonth}-${String(d).padStart(2, '0')}`;
            const row: any = { day: `${d}` };
            for (const emp of allEmployees) {
                row[emp.id] = empDailyMap[emp.id][dateStr]?.hours || 0;
            }
            trendData.push(row);
        }
        setDailyTrend(trendData);

        // --- 3. Punctuality per Employee ---
        const punctData = allEmployees.map((emp) => {
            let early = 0, onTime = 0, late = 0;
            for (let d = 1; d <= daysInMonth; d++) {
                const dateStr = `${selectedMonth}-${String(d).padStart(2, '0')}`;
                const p = empDailyMap[emp.id][dateStr]?.punctuality;
                if (p === 'early') early++;
                else if (p === 'onTime') onTime++;
                else if (p === 'late') late++;
            }
            return { name: emp.full_name, Early: early, 'On Time': onTime, Late: late };
        });
        setPunctuality(punctData);

        // --- 4. Donut ---
        setDonut([
            { name: 'Present', value: presCount, color: 'var(--store-positive)' },
            { name: 'Absent', value: absCount, color: 'var(--store-negative)' },
            { name: 'Off', value: offCount, color: 'var(--store-border)' },
        ].filter(d => d.value > 0));

        // --- 5. Weekly Trend ---
        const weeklyEmpMap: Record<string, Record<number, number>> = {};
        for (const emp of allEmployees) weeklyEmpMap[emp.id] = {};
        for (let d = 1; d <= daysInMonth; d++) {
            const dateStr = `${selectedMonth}-${String(d).padStart(2, '0')}`;
            const wk = Math.ceil(d / 7);
            for (const emp of allEmployees) {
                const hrs = empDailyMap[emp.id][dateStr]?.hours || 0;
                weeklyEmpMap[emp.id][wk] = (weeklyEmpMap[emp.id][wk] || 0) + hrs;
            }
        }
        const weekKeys = [...new Set(Object.values(weeklyEmpMap).flatMap(w => Object.keys(w)))].sort((a, b) => parseInt(a) - parseInt(b));
        const weeklyData = weekKeys.map((wk) => {
            const row: any = { week: `W${wk}` };
            for (const emp of allEmployees) {
                row[emp.id] = Math.round((weeklyEmpMap[emp.id][parseInt(wk)] || 0) * 100) / 100;
            }
            return row;
        });
        setWeeklyTrend(weeklyData);

        // --- 6. Heatmap ---
        const heatRows = allEmployees.map((emp) => {
            const cells: any[] = [];
            for (let d = 1; d <= daysInMonth; d++) {
                const dateStr = `${selectedMonth}-${String(d).padStart(2, '0')}`;
                cells.push({ day: d, hours: empDailyMap[emp.id][dateStr]?.hours ?? 0 });
            }
            return { id: emp.id, name: emp.full_name, cells };
        });
        setHeatmap(heatRows);

        setLoading(false);
    }, [selectedMonth, supabase]);

    useEffect(() => {
        fetchAllData();
    }, [fetchAllData]);

    const empKeys = employees.map(e => e.id);
    const allHourVals = dailyTrend.flatMap(d => empKeys.map(k => d[k] || 0));
    const maxHours = Math.max(...allHourVals, 1);

    const heatIntensity = (hours: number) => {
        if (hours === 0) return 'bg-slate-100 text-slate-500';
        const r = Math.min(hours / (maxHours || 1), 1);
        if (r < 0.25) return 'bg-indigo-200 text-slate-700';
        if (r < 0.5) return 'bg-indigo-400 text-white';
        if (r < 0.75) return 'bg-indigo-600 text-white';
        return 'bg-indigo-800 text-white';
    };

    return (
        <div className="space-y-8">
            <header className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                <div className="space-y-1">
                    <h1 className="text-3xl font-medium tracking-normal text-slate-900">Attendance graphs</h1>
                    <p className="text-sm font-medium text-slate-500 tracking-normal">
                        Hours, punctuality, and attendance by employee
                    </p>
                </div>
                <div className="flex items-center gap-3 px-3 py-2 bg-white rounded-xl shadow-sm border border-slate-100">
                    <Calendar size={16} className="text-slate-500" />
                    <input
                        type="month"
                        value={selectedMonth}
                        onChange={(e) => setSelectedMonth(e.target.value)}
                        className="bg-transparent text-xs font-medium text-slate-700 outline-none cursor-pointer"
                    />
                </div>
            </header>

            {loading ? (
                <div className="py-32 flex flex-col items-center justify-center gap-4 ">
                    <Loader2 className="animate-spin text-slate-900" size={32} />
                    <p className="text-sm font-medium tracking-normal">Loading attendance reports</p>
                </div>
            ) : (
                <div className="space-y-6">

                    {/* 1. Monthly Totals — Simple horizontal bar, one per employee */}
                    <GraphCard icon={<BarChart3 size={18} />} title="Total Hours — This Month" subtitle="Compare hours worked by employee">
                        <ResponsiveContainer width="100%" height={Math.max(200, employees.length * 40)}>
                            <BarChart data={monthlyTotals} layout="vertical" barCategoryGap={6}>
                                <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" horizontal={false} />
                                <XAxis type="number" tick={{ fontSize: 12, fill: '#94a3b8' }} tickFormatter={v => `${v}h`} />
                                <YAxis type="category" dataKey="name" tick={{ fontSize: 12, fill: '#1e293b' }} width={140} />
                                <Tooltip
                                    formatter={(value: any) => [`${Number(value).toFixed(1)}h`, 'Total Hours']}
                                    contentStyle={{ borderRadius: 12, border: '1px solid #e2e8f0', fontSize: 12 }}
                                />
                                <Bar dataKey="hours" radius={[0, 6, 6, 0]}>
                                    {monthlyTotals.map((_, idx) => (
                                        <Cell key={idx} fill="var(--store-accent)" />
                                    ))}
                                </Bar>
                            </BarChart>
                        </ResponsiveContainer>
                    </GraphCard>

                    {/* 2. Daily Trend — Line chart, one line per employee */}
                    <GraphCard icon={<TrendingUp size={18} />} title="Daily Hours Trend" subtitle="Hours per day — follow each employee&apos;s line across the month">
                        <ResponsiveContainer width="100%" height={320}>
                            <LineChart data={dailyTrend}>
                                <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
                                <XAxis dataKey="day" tick={{ fontSize: 12, fill: '#94a3b8' }} interval={3} />
                                <YAxis tick={{ fontSize: 12, fill: '#94a3b8' }} tickFormatter={v => `${v}h`} />
                                <Tooltip
                                    contentStyle={{ borderRadius: 12, border: '1px solid #e2e8f0', fontSize: 12 }}
                                />
                                <Legend
                                    wrapperStyle={{ fontSize: 12 }}
                                    formatter={(value: string) => employees.find(e => e.id === value)?.full_name || value}
                                />
                                {empKeys.map((key, idx) => (
                                    <Line
                                        key={key}
                                        type="monotone"
                                        dataKey={key}
                                        name={employees.find(e => e.id === key)?.full_name}
                                        stroke={COLORS[idx % COLORS.length]}
                                        strokeWidth={2}
                                        dot={false}
                                        activeDot={{ r: 4 }}
                                    />
                                ))}
                            </LineChart>
                        </ResponsiveContainer>
                    </GraphCard>

                    {/* 3. Punctuality per Employee */}
                    <GraphCard icon={<Clock size={18} />} title="Punctuality per Employee" subtitle="How many days each person was Early / On Time / Late">
                        <ResponsiveContainer width="100%" height={Math.max(200, employees.length * 36)}>
                            <BarChart data={punctuality} layout="vertical" barCategoryGap={6}>
                                <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" horizontal={false} />
                                <XAxis type="number" tick={{ fontSize: 12, fill: '#94a3b8' }} />
                                <YAxis type="category" dataKey="name" tick={{ fontSize: 12, fill: '#1e293b' }} width={140} />
                                <Tooltip contentStyle={{ borderRadius: 12, border: '1px solid #e2e8f0', fontSize: 12 }} />
                                <Legend wrapperStyle={{ fontSize: 12 }} />
                                <Bar dataKey="Early" fill="var(--store-positive)" radius={[0, 0, 0, 0]} />
                                <Bar dataKey="On Time" fill="var(--store-accent)" />
                                <Bar dataKey="Late" fill="var(--store-warning)" radius={[0, 4, 4, 0]} />
                            </BarChart>
                        </ResponsiveContainer>
                    </GraphCard>

                    {/* 4. Weekly Trend + Donut */}
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                        <GraphCard icon={<TrendingUp size={18} />} title="Weekly Trend" subtitle="Total hours per week, per employee">
                            <ResponsiveContainer width="100%" height={280}>
                                <LineChart data={weeklyTrend}>
                                    <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
                                    <XAxis dataKey="week" tick={{ fontSize: 12, fill: '#94a3b8' }} />
                                    <YAxis tick={{ fontSize: 12, fill: '#94a3b8' }} tickFormatter={v => `${v}h`} />
                                    <Tooltip contentStyle={{ borderRadius: 12, border: '1px solid #e2e8f0', fontSize: 12 }} />
                                    <Legend
                                        wrapperStyle={{ fontSize: 12 }}
                                        formatter={(value: string) => employees.find(e => e.id === value)?.full_name || value}
                                    />
                                    {empKeys.map((key, idx) => (
                                        <Line
                                            key={key}
                                            type="monotone"
                                            dataKey={key}
                                            name={employees.find(e => e.id === key)?.full_name}
                                            stroke={COLORS[idx % COLORS.length]}
                                            strokeWidth={2}
                                            dot={{ r: 3 }}
                                            activeDot={{ r: 5 }}
                                        />
                                    ))}
                                </LineChart>
                            </ResponsiveContainer>
                        </GraphCard>

                        <GraphCard icon={<PieChart size={18} />} title="Attendance Breakdown" subtitle="Present vs Absent vs Off (all employees combined)">
                            <ResponsiveContainer width="100%" height={280}>
                                <RePieChart>
                                    <Pie
                                        data={donut}
                                        cx="50%" cy="50%"
                                        innerRadius={65} outerRadius={105}
                                        paddingAngle={4}
                                        dataKey="value"
                                    >
                                        {donut.map((entry, idx) => (
                                            <Cell key={idx} fill={entry.color} />
                                        ))}
                                    </Pie>
                                    <Tooltip formatter={(value, name) => [value ?? 0, name]} contentStyle={{ borderRadius: 12, border: '1px solid #e2e8f0', fontSize: 12 }} />
                                    <Legend
                                        wrapperStyle={{ fontSize: 12 }}
                                        formatter={(value: string) => {
                                            const entry = donut.find(d => d.name === value);
                                            const total = donut.reduce((s: number, d: any) => s + d.value, 0);
                                            const pct = entry ? ((entry.value / total) * 100).toFixed(1) : '0';
                                            return `${value} (${pct}%)`;
                                        }}
                                    />
                                </RePieChart>
                            </ResponsiveContainer>
                        </GraphCard>
                    </div>

                    {/* 5. Hours Heatmap */}
                    <GraphCard icon={<Grid3x3 size={18} />} title="Hours Heatmap" subtitle="Rows = employees, Columns = days — darker cell = more hours worked">
                        <div className="admin-hours-heatmap overflow-x-auto p-2">
                            <div className="inline-grid gap-1" style={{
                                gridTemplateColumns: `130px repeat(${dailyTrend.length}, 36px)`,
                            }}>
                                <div className="text-xs font-medium text-slate-500 tracking-normal pb-1 flex items-end" />
                                {dailyTrend.map((d, ci) => (
                                    <div key={ci} className="text-xs font-medium text-slate-500 tracking-normal text-center pb-1">
                                        {d.day}
                                    </div>
                                ))}
                                {heatmap.map((row) => (
                                    <Fragment key={row.id}>
                                        <div className="text-sm font-medium text-slate-600 truncate pr-2 flex items-center">
                                            {row.name}
                                        </div>
                                        {row.cells.map((cell: any, ci: number) => (
                                            <div
                                                key={ci}
                                                className={`aspect-square rounded flex items-center justify-center text-xs font-medium ${heatIntensity(cell.hours)}`}
                                                title={`${row.name} — Day ${cell.day}: ${cell.hours.toFixed(1)}h`}
                                            >
                                                {cell.hours > 0 ? cell.hours.toFixed(1) : ''}
                                            </div>
                                        ))}
                                    </Fragment>
                                ))}
                            </div>
                            <div className="flex items-center gap-2 mt-3 text-xs font-medium text-slate-500 tracking-normal">
                                <span>0h</span>
                                <div className="w-4 h-4 rounded bg-slate-100" />
                                <div className="w-4 h-4 rounded bg-indigo-200" />
                                <div className="w-4 h-4 rounded bg-indigo-400" />
                                <div className="w-4 h-4 rounded bg-indigo-600" />
                                <div className="w-4 h-4 rounded bg-indigo-800" />
                                <span>{maxHours.toFixed(1)}h</span>
                            </div>
                        </div>
                    </GraphCard>

