export default async function EmployeeTestersPage() {
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) redirect('/login')

  const { data: profile } = await supabase
    .from('profiles')
    .select('role')
    .eq('id', user.id)
    .single()

  const role = profile?.role || 'employee'

  const { data, count } = await supabase
    .from('testers')
    .select(`
      *,
      profiles:created_by(full_name),
      tester_logs(*, profiles:created_by(full_name))
    `, { count: 'exact' })
    .order('expiry_date', { ascending: true })
    .range(0, 19)

  return (
    <div className="space-y-6">
      <TesterList
        initialData={(data || []) as any}
        total={count || 0}
        page={1}
        totalPages={Math.ceil((count || 0) / 20)}
        basePath="/employee/store-operations/testers"
        canCreate={can(role, 'testers.create')}
      />
    </div>
  )
}

'use server'
import { getAdminClient } from '@/lib/admin-client'

export async function createNewUser(formData: FormData) {
    try {
        const adminClient = await getAdminClient();

        const email = formData.get('email') as string
        const password = formData.get('password') as string
        const fullName = formData.get('fullName') as string
        const username = formData.get('username') as string
        const role = formData.get('role') as string
        const storeId = formData.get('storeId') as string

        // 1. Create user in Supabase Auth
        const { data: authUser, error: authError } = await adminClient.auth.admin.createUser({
            email,
            password,
            email_confirm: true,
        })

        if (authError) return { error: authError.message }

        // 2. Update the public.profiles table
        const { error: profileError } = await adminClient
            .from('profiles')
            .update({
                full_name: fullName,
                username: username.toLowerCase(),
                role: role,
                store_id: storeId,
                email: email
            })
            .eq('id', authUser.user.id)

        if (profileError) {
            await adminClient.auth.admin.deleteUser(authUser.user.id);
            return { error: profileError.message }
        }

        return { success: true }
    } catch (err: any) {
        return { error: err.message };
    }
}

'use server';
import { revalidatePath } from 'next/cache';
import { getAdminClient } from '@/lib/admin-client';

export async function approveOverrideRequest(requestId: string) {
    try {
        const adminClient = await getAdminClient();

        // Fetch the swap request with shift info
        const { data: request, error: reqError } = await adminClient
            .from('swap_requests')
            .select('*, shifts(*)')
            .eq('id', requestId)
            .single();

        if (reqError || !request) throw new Error("Request not found");

        if (!request.message?.includes('OVERRIDE REQUEST')) {
            throw new Error("Not an override request");
        }

        let targetDate = null;
        if (request.shifts?.start_time) {
            targetDate = request.shifts.start_time.split('T')[0];
        } else {
            const dateMatch = request.message.match(/(\d{4}-\d{2}-\d{2})/);
            if (dateMatch) targetDate = dateMatch[0];
        }
        if (!targetDate) throw new Error("Could not determine date for override");

        const { data: attendance, error: attError } = await adminClient
            .from('attendance')
            .select('*')
            .eq('employee_id', request.requestor_id)
            .gte('check_in', `${targetDate}T00:00:00`)
            .lt('check_in', `${targetDate}T23:59:59`)
            .maybeSingle();

        if (attError) throw attError;
        if (!attendance) throw new Error("No attendance record found for that day");
        if (!attendance.check_out) throw new Error("Employee has not clocked out yet");

        const { error: updateError } = await adminClient
            .from('attendance')
            .update({ check_out: null })
            .eq('id', attendance.id);

        if (updateError) throw updateError;

        const { error: statusError } = await adminClient
            .from('swap_requests')
            .update({ status: 'approved' })
            .eq('id', requestId);

        if (statusError) throw statusError;

        revalidatePath('/admin');
        return { success: true };
    } catch (err: any) {
        console.error("Override approval error:", err);
        return { success: false, error: err.message };
    }
}

'use server'

import { createClient } from '@/lib/supabase/server';

export async function createTemplate(data: {
  name: string
  type: 'opening' | 'closing'
  items: string[]
}) {
  const supabase = await createClient();
  const { data: { user }, error: authError } = await supabase.auth.getUser();
  if (authError || !user) return { error: 'Unauthorized' };

  const { data: profile } = await supabase
    .from('profiles')
    .select('role')
    .eq('id', user.id)
    .single();

  if (!profile || (profile.role !== 'admin' && profile.role !== 'manager')) {
    return { error: 'Forbidden' };
  }

  const { data: template, error } = await supabase
    .from('checklist_templates')
    .insert({
      name: data.name,
      type: data.type,
      created_by: user.id,
    })
    .select()
    .single();

  if (error) return { error: error.message };

  if (data.items.length > 0) {
    const { error: itemError } = await supabase
      .from('daily_checklist_items')
      .insert(
        data.items.map((label, i) => ({
          daily_checklist_id: template.id,
          label,
          sort_order: i,
          created_by: user.id,
        }))
      );

    if (itemError) return { error: itemError.message };
  }

  return { success: true, data: template };
}

export async function updateTemplate(
  id: string,
  data: { name?: string; type?: 'opening' | 'closing'; items?: string[]; is_active?: boolean }
) {
  const supabase = await createClient();
  const { data: { user }, error: authError } = await supabase.auth.getUser();
  if (authError || !user) return { error: 'Unauthorized' };

  const { data: profile } = await supabase
    .from('profiles')
    .select('role')
    .eq('id', user.id)
    .single();

  if (!profile || (profile.role !== 'admin' && profile.role !== 'manager')) {
    return { error: 'Forbidden' };
  }

  if (data.name || data.type !== undefined || data.is_active !== undefined) {
    const { error } = await supabase
      .from('checklist_templates')
      .update({
        ...(data.name && { name: data.name }),
        ...(data.type !== undefined && { type: data.type }),
        ...(data.is_active !== undefined && { is_active: data.is_active }),
      })
      .eq('id', id);

    if (error) return { error: error.message };
  }

  if (data.items) {
    const { error: deleteError } = await supabase
      .from('daily_checklist_items')
      .delete()
      .eq('daily_checklist_id', id);

    if (deleteError) return { error: deleteError.message };

    const { error: insertError } = await supabase
      .from('daily_checklist_items')
      .insert(
        data.items.map((label, i) => ({
          daily_checklist_id: id,
          label,
          sort_order: i,
          created_by: user.id,
        }))
      );

    if (insertError) return { error: insertError.message };
  }

  return { success: true };
