'use client';
import { useEffect, useState } from 'react';
import { Download, X } from 'lucide-react';

export default function InstallPWA() {
    const [supportsPWA, setSupportsPWA] = useState(false);
    const [promptInstall, setPromptInstall] = useState<any>(null);
    const [isVisible, setIsVisible] = useState(true);

    useEffect(() => {
        const handler = (e: any) => {
            e.preventDefault();
            setSupportsPWA(true);
            setPromptInstall(e);
        };

        window.addEventListener("beforeinstallprompt", handler);

        // Don't show if already in standalone mode
        if (window.matchMedia('(display-mode: standalone)').matches) {
            setSupportsPWA(false);
        }

        return () => window.removeEventListener("beforeinstallprompt", handler);
    }, []);

    const handleInstall = async () => {
        if (!promptInstall) return;
        promptInstall.prompt();
        const { outcome } = await promptInstall.userChoice;
        if (outcome === "accepted") setSupportsPWA(false);
    };

    if (!supportsPWA || !isVisible) return null;

    return (
        <div className="fixed bottom-6 left-4 right-4 md:bottom-12 md:left-auto md:right-12 md:w-80 z-[100] animate-in slide-in-from-bottom-5 duration-700">
            <div className="bg-black text-white p-5 rounded-[2rem] shadow-2xl flex flex-col gap-4 border border-white/10">
                <div className="flex items-start justify-between">
                    <div className="flex gap-3">
                        <div className="bg-white/10 p-2 rounded-xl h-fit">
                            <Download size={18} className="text-emerald-400" />
                        </div>
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-[0.2em] mb-1">Mobile App Available</p>
                            <p className="text-[11px] text-neutral-400 leading-relaxed font-medium">
                                Install the portal for faster access and offline logs.
                            </p>
                        </div>
                    </div>
                    <button onClick={() => setIsVisible(false)} className="opacity-40 hover:opacity-100 transition-opacity">
                        <X size={16} />
                    </button>
                </div>

                <button
                    onClick={handleInstall}
                    className="w-full bg-white text-black py-3 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] active:scale-[0.98] transition-all"
                >
                    Install Now
                </button>
            </div>
        </div>
    );
}

'use client';
import { useState, useEffect } from 'react';
import { createClient } from '@/lib/supabase/client';
import BulkScheduler from './BulkScheduler';
import PresetManager from './PresetManager';
import {
    RotateCcw, Check, X, Clock, User, AlertCircle, Calendar, Filter, Activity, Palmtree, ShieldAlert
} from 'lucide-react';

export default function AdminDashboard({ employees, liveAttendance, adminId }: any) {
    const supabase = createClient();

    // --- Navigation State ---
    const [activeTab, setActiveTab] = useState<'live' | 'schedule' | 'leaves' | 'alerts'>('live');
    const [showHistory, setShowHistory] = useState(false);

    // --- Data States ---
    const [overrides, setOverrides] = useState<any[]>([]);
    const [leaves, setLeaves] = useState<any[]>([]);
    const [leaveHistory, setLeaveHistory] = useState<any[]>([]);
    const [loading, setLoading] = useState(false);

    // --- History Filters ---
    const [histFilterEmployee, setHistFilterEmployee] = useState('');
    const [histFilterStart, setHistFilterStart] = useState('');
    const [histFilterEnd, setHistFilterEnd] = useState('');

    // --- Data Fetching ---
    useEffect(() => {
        if (activeTab === 'leaves') {
            if (showHistory) fetchLeaveHistory();
            else fetchLeaves();
        } else if (activeTab === 'alerts') {
            fetchOverrides();
        }

        // Realtime sync for all admin data
        const channel = supabase.channel('admin_realtime')
            .on('postgres_changes', { event: '*', schema: 'public', table: 'leave_requests' }, () => {
                fetchLeaves();
                if (showHistory) fetchLeaveHistory();
            })
            .on('postgres_changes', { event: '*', schema: 'public', table: 'swap_requests' }, fetchOverrides)
            .subscribe();

        return () => { supabase.removeChannel(channel); };
    }, [activeTab, showHistory, histFilterEmployee, histFilterStart, histFilterEnd]);

    const fetchLeaves = async () => {
        setLoading(true);
        const { data } = await supabase
            .from('leave_requests')
            .select('*, profiles:employee_id(full_name)')
            .eq('status', 'pending')
            .order('created_at', { ascending: true });
        setLeaves(data || []);
        setLoading(false);
    };

    const fetchLeaveHistory = async () => {
        setLoading(true);
        // neq('status', 'pending') ensures we ONLY see Approved or Rejected
        let query = supabase
            .from('leave_requests')
            .select('*, profiles:employee_id(full_name)')
            .neq('status', 'pending');

        if (histFilterEmployee) query = query.eq('employee_id', histFilterEmployee);
        if (histFilterStart) query = query.gte('start_date', histFilterStart);
        if (histFilterEnd) query = query.lte('end_date', histFilterEnd);

        const { data } = await query.order('start_date', { ascending: false });
        setLeaveHistory(data || []);
        setLoading(false);
    };

    const fetchOverrides = async () => {
        const { data } = await supabase
            .from('swap_requests')
            .select('*, profiles:requestor_id(full_name)')
            .ilike('message', 'OVERRIDE REQUEST%')
            .eq('status', 'pending');
        setOverrides(data || []);
    };

    // --- Handlers ---
    const handleLeaveAction = async (leaveId: string, newStatus: 'approved' | 'declined') => {
        const { error } = await supabase
            .from('leave_requests')
            .update({ status: newStatus, approved_by: adminId })
            .eq('id', leaveId);

        if (!error) {
            // Re-fetch both to ensure UI reflects the DB change immediately
            await fetchLeaves();
            if (showHistory) await fetchLeaveHistory();
        }
    };

    const handleApproveOverride = async (request: any) => {
        const now = new Date();
        const today = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
        await supabase.from('attendance').delete().eq('employee_id', request.requestor_id).gte('check_in', `${today}T00:00:00Z`);
        await supabase.from('swap_requests').update({ status: 'approved' }).eq('id', request.id);
        fetchOverrides();
    };

    return (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 w-full items-start p-4 lg:p-8">

            {/* 🖥️ SIDEBAR NAVIGATION */}
            <aside className="lg:col-span-3 space-y-4 lg:sticky lg:top-4">
                <nav className="bg-white border border-slate-200 p-2 rounded-xl shadow-sm flex lg:flex-col gap-1">
                    {[
                        { id: 'live', label: 'Live Status', icon: <Activity size={18} /> },
                        { id: 'schedule', label: 'Shift Planner', icon: <Calendar size={18} /> },
                        { id: 'leaves', label: 'Leave Requests', icon: <Palmtree size={18} />, count: leaves.length },
                        { id: 'alerts', label: 'Overrides', icon: <ShieldAlert size={18} />, count: overrides.length }
                    ].map((tab) => (
                        <button
                            key={tab.id}
                            onClick={() => { setActiveTab(tab.id as any); setShowHistory(false); }}
                            className={`flex items-center justify-between px-4 py-3 rounded-xl text-sm font-medium  tracking-normal transition-colors ${activeTab === tab.id ? 'bg-slate-900 text-white ' : 'text-slate-500 hover:bg-slate-50'
                                }`}
                        >
                            <div className="flex items-center gap-3">
                                <span>{tab.icon}</span>
                                <span>{tab.label}</span>
                            </div>
                            {tab.count ? (
                                <span className="bg-rose-500 text-white text-xs px-2 py-0.5 rounded-full">
