'use client';
import { useState, useEffect, useMemo } from 'react';
import { createClient } from '@/lib/supabase/client';
import { Loader2, ChevronLeft, ChevronRight, Search, Calendar, UserCheck, UserX } from 'lucide-react';

export default function FreeMonthlyRoaster() {
    const supabase = createClient();
    const [viewDate, setViewDate] = useState(new Date());
    const [employees, setEmployees] = useState<any[]>([]);
    const [shifts, setShifts] = useState<any[]>([]);
    const [leaves, setLeaves] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    // Helper: Formats a date to YYYY-MM-DD based on local values (No UTC shift)
    const formatToLocalDate = (date: Date) => {
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        return `${year}-${month}-${day}`;
    };

    // Helper: Formats specific year/month/day to YYYY-MM-DD
    const getLocalISOString = (year: number, month: number, day: number) => {
        const m = String(month + 1).padStart(2, '0');
        const d = String(day).padStart(2, '0');
        return `${year}-${m}-${d}`;
    };

    const [searchDate, setSearchDate] = useState(formatToLocalDate(new Date()));

    const daysInMonth = useMemo(() => {
        const year = viewDate.getFullYear();
        const month = viewDate.getMonth();
        const days = new Date(year, month + 1, 0).getDate();
        return Array.from({ length: days }, (_, i) => i + 1);
    }, [viewDate]);

    const fetchRoaster = async () => {
        setLoading(true);
        // 1. Fetch Month Level Data with Timezone-Aware Bounds (+05:30)
        const firstDay = `${viewDate.getFullYear()}-${String(viewDate.getMonth() + 1).padStart(2, '0')}-01T00:00:00+05:30`;
        const lastDay = `${viewDate.getFullYear()}-${String(viewDate.getMonth() + 1).padStart(2, '0')}-${String(daysInMonth.length).padStart(2, '0')}T23:59:59+05:30`;

        const [empRes, shiftRes, leaveRes] = await Promise.all([
            supabase.from('profiles').select('id, full_name').eq('role', 'employee'),
            supabase.from('shifts').select('*').gte('start_time', firstDay).lte('start_time', lastDay),
            supabase.from('leave_requests').select('*').eq('status', 'approved').gte('start_date', firstDay.split('T')[0]).lte('end_date', lastDay.split('T')[0])
        ]);

        setEmployees(empRes.data || []);
        setShifts(shiftRes.data || []);
        setLeaves(leaveRes.data || []);
        setLoading(false);
    };

    useEffect(() => { fetchRoaster(); }, [viewDate]);

    const getStatus = (empId: string, dateStr: string) => {
        // 1. Check Approved Leaves first (Highest Priority)
        const onLeave = leaves.find(l => {
            return l.employee_id === empId &&
                dateStr >= l.start_date &&
                dateStr <= l.end_date;
        });

        if (onLeave) {
            return {
                type: 'LEAVE',
                label: 'LV',
                color: 'bg-rose-100 text-rose-600 border-rose-200'
            };
        }

        // 2. Check Shifts (Only if NOT on leave)
        const shift = shifts.find(s => {
            // Compare the first 10 characters (YYYY-MM-DD)
            const shiftDate = s.start_time.substring(0, 10);
            return s.employee_id === empId && shiftDate === dateStr;
        });

        if (shift) {
            const label = shift.shift_label?.toLowerCase() || '';
            const isSales = label.includes('sales');
            const isDay = label.includes('day');
            const isMorning = label.includes('morning');

            if (isSales) return {
                type: 'SHIFT',
                label: 'SS',
                color: 'bg-indigo-100 text-indigo-700 border-indigo-200'
            };

            if (isDay) return {
                type: 'SHIFT',
                label: 'D',
                color: 'bg-emerald-100 text-emerald-700 border-emerald-200'
            };

            return {
                type: 'SHIFT',
                label: isMorning ? 'M' : 'E',
                color: isMorning ? 'bg-amber-100 text-amber-700 border-amber-200' : 'bg-blue-100 text-blue-700 border-blue-200',
            };
        }

        // 3. Default to Off Day (Red per your request)
        return {
            type: 'OFF',
            label: 'OFF',
            color: 'bg-red-50 text-red-500 border-red-100 '
        };
    };

    const daySummary = useMemo(() => {
        const working: any[] = [];
        const off: any[] = [];

        employees.forEach(emp => {
            const status = getStatus(emp.id, searchDate);
            if (status.type === 'SHIFT') working.push({ name: emp.full_name, label: status.label });
            else off.push({ name: emp.full_name, type: status.type });
        });

        return { working, off };
    }, [searchDate, employees, shifts, leaves]);

    if (loading) return (
        <div className="h-96 flex flex-col items-center justify-center ">
            <Loader2 className="animate-spin mb-4" />
            <p className="text-sm font-medium tracking-normal">Syncing Roaster...</p>
        </div>
    );

    return (
        <div className="space-y-6 max-w-[1600px] mx-auto">
            {/* Quick Day Search Section */}
            <div className="bg-slate-900 rounded-xl p-8 text-white">
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                    <div className="space-y-1">
                        <h3 className="text-xl font-medium tracking-normal flex items-center gap-2">
                            <Search size={20} className="text-blue-400" /> Daily Quick Lookup
                        </h3>
                        <p className="text-sm font-medium text-slate-500 tracking-normal">Identify coverage gaps instantly</p>
                    </div>
                    <div className="relative">
                        <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500" size={16} />
                        <input
                            type="date"
                            value={searchDate}
                            onChange={(e) => setSearchDate(e.target.value)}
                            className="bg-slate-800 border-none rounded-xl pl-12 pr-6 py-4 text-sm font-medium tracking-normal text-white outline-none focus:ring-2 ring-blue-500 transition-colors"
                        />
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-8">
                    {/* Working Card */}
                    <div className="bg-slate-800/50 rounded-xl p-6 border border-slate-700">
                        <div className="flex items-center gap-2 mb-4 text-emerald-400">
                            <UserCheck size={16} />
                            <span className="text-sm font-medium tracking-normal">Working Today ({daySummary.working.length})</span>
                        </div>
                        <div className="flex flex-wrap gap-2">
                            {daySummary.working.length > 0 ? daySummary.working.map((emp, i) => (
                                <span key={i} className="bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 px-3 py-1.5 rounded-xl text-sm font-medium">
                                    {emp.name} <span className=" ml-1">({emp.label})</span>
                                </span>
                            )) : <span className="text-sm text-slate-500">No shifts assigned</span>}
                        </div>
                    </div>

                    {/* Off/Leave Card */}
                    <div className="bg-slate-800/50 rounded-xl p-6 border border-slate-700">
                        <div className="flex items-center gap-2 mb-4 text-rose-400">
                            <UserX size={16} />
                            <span className="text-sm font-medium tracking-normal">Off / Leave ({daySummary.off.length})</span>
                        </div>
                        <div className="flex flex-wrap gap-2">
                            {daySummary.off.map((emp, i) => (
                                <span key={i} className={`px-3 py-1.5 rounded-xl text-sm font-medium border ${emp.type === 'LEAVE' ? 'bg-rose-500/10 text-rose-400 border-rose-500/20' : 'bg-red-500/10 text-red-400 border-red-500/20'}`}>
                                    {emp.name} <span className="text-xs  ml-1">[{emp.type}]</span>
                                </span>
                            ))}
                        </div>
                    </div>
                </div>
            </div>

            {/* Monthly Roaster Grid */}
            <div className="bg-white rounded-xl border border-slate-100 overflow-hidden">
                <div className="p-8 flex items-center justify-between border-b border-slate-50">
                    <h2 className="text-2xl font-medium text-slate-900 tracking-normal">
                        {viewDate.toLocaleString('default', { month: 'long', year: 'numeric' })}
                    </h2>
                    <div className="flex gap-2">
                        <NavBtn onClick={() => setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() - 1, 1))} icon={<ChevronLeft size={18} />} />
                        <NavBtn onClick={() => setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() + 1, 1))} icon={<ChevronRight size={18} />} />
                    </div>
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full border-collapse">
                        <thead>
                            <tr className="bg-slate-50/50">
                                <th className="sticky left-0 z-20 bg-white p-4 text-sm font-medium text-slate-500 tracking-normal text-left border-b border-slate-100 min-w-[160px]">Personnel</th>
                                {daysInMonth.map(day => (
                                    <th key={day} className="p-2 text-sm font-medium text-slate-500 border-b border-slate-100 min-w-[50px] text-center">
                                        {day}
                                        <div className="text-xs font-medium ">
                                            {new Date(viewDate.getFullYear(), viewDate.getMonth(), day).toLocaleDateString('en-US', { weekday: 'short' })}
                                        </div>
                                    </th>
                                ))}
                            </tr>
                        </thead>
                        <tbody>
                            {employees.map(emp => (
                                <tr key={emp.id} className="hover:bg-slate-50/30 transition-colors">
                                    <td className="sticky left-0 z-20 bg-white p-4 border-b border-slate-50 text-sm font-medium text-slate-800 tracking-normal">
                                        {emp.full_name}
                                    </td>
                                    {daysInMonth.map(day => {
                                        const dateStr = getLocalISOString(viewDate.getFullYear(), viewDate.getMonth(), day);
                                        const status = getStatus(emp.id, dateStr);
                                        return (
                                            <td key={day} className="p-1 border-b border-slate-50">
                                                <div className={`h-10 w-full rounded-xl border flex items-center justify-center text-xs font-medium transition-colors ${status.color}`}>
                                                    {status.label}
                                                </div>
                                            </td>
                                        );
                                    })}
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}

