'use client';
import { useState, useEffect } from 'react';
import { createClient } from '@/lib/supabase/client';
import { Check, X, Clock, RotateCcw, User } from 'lucide-react';

export default function LeaveManagementWrapper({ adminId, employees }: any) {
    const supabase = createClient();
    const [showHistory, setShowHistory] = useState(false);
    const [leaves, setLeaves] = useState<any[]>([]);
    const [leaveHistory, setLeaveHistory] = useState<any[]>([]);
    const [loading, setLoading] = useState(false);
    const [selectedEmployee, setSelectedEmployee] = useState('');

    useEffect(() => {
        if (showHistory) fetchLeaveHistory();
        else fetchLeaves();
    }, [showHistory, selectedEmployee]);

    const fetchLeaves = async () => {
        setLoading(true);
        // REMOVED created_at and fixed join syntax
        const { data, error } = await supabase
            .from('leave_requests')
            .select(`
                *,
                profiles:employee_id (
                    full_name
                )
            `)
            .eq('status', 'pending')
            .order('start_date', { ascending: true }); // Ordering by start_date instead

        if (error) {
            console.error("Fetch Error:", error.message);
        }
        setLeaves(data || []);
        setLoading(false);
    };

    const fetchLeaveHistory = async () => {
        setLoading(true);
        let query = supabase
            .from('leave_requests')
            .select(`
                *,
                profiles:employee_id (
                    full_name
                )
            `)
            .neq('status', 'pending');

        if (selectedEmployee) {
            query = query.eq('employee_id', selectedEmployee);
        }

        // Ordering history by the date they are actually taking off
        const { data, error } = await query.order('start_date', { ascending: false });

        if (error) console.error("History Error:", error.message);
        setLeaveHistory(data || []);
        setLoading(false);
    };

    const handleAction = async (id: string, status: 'approved' | 'declined') => {
        const { error } = await supabase
            .from('leave_requests')
            .update({
                status,
                approved_by: adminId
            })
            .eq('id', id);

        if (!error) {
            showHistory ? fetchLeaveHistory() : fetchLeaves();
        }
    };

    return (
        <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden p-8">
            <div className="flex gap-8 border-b border-slate-100 mb-8">
                <button
                    onClick={() => setShowHistory(false)}
                    className={`pb-4 text-sm font-medium  tracking-normal transition-colors ${!showHistory ? 'text-slate-900 border-b-2 border-slate-900' : 'text-slate-500'}`}
                >
                    Pending Queue ({leaves.length})
                </button>
                <button
                    onClick={() => setShowHistory(true)}
                    className={`pb-4 text-sm font-medium  tracking-normal transition-colors ${showHistory ? 'text-slate-900 border-b-2 border-slate-900' : 'text-slate-500'}`}
                >
                    Archive
                </button>
            </div>

            {showHistory ? (
                <div className="space-y-6">
                    <div className="flex items-center gap-3 bg-slate-900 p-4 rounded-xl">
                        <div className="relative flex-1">
                            <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500" size={16} />
                            <select
                                value={selectedEmployee}
                                onChange={(e) => setSelectedEmployee(e.target.value)}
                                className="w-full bg-slate-800 border-none rounded-xl pl-12 pr-4 py-3 text-sm font-medium text-white outline-none appearance-none"
                            >
                                <option value="">All Personnel</option>
                                {employees?.map((emp: any) => (
                                    <option key={emp.id} value={emp.id}>{emp.full_name}</option>
                                ))}
                            </select>
                        </div>
                        <button onClick={() => setSelectedEmployee('')} className="bg-slate-800 text-slate-500 p-3.5 rounded-xl hover:text-white transition-colors">
                            <RotateCcw size={18} />
                        </button>
                    </div>

                    <div className="space-y-3">
                        {loading ? (
                            <div className="py-20 text-center text-sm font-medium text-slate-500">Updating...</div>
                        ) : leaveHistory.map(item => (
                            <div key={item.id} className="p-5 border border-slate-100 rounded-xl flex items-center justify-between bg-slate-50/30">
                                <div className="flex items-center gap-4">
                                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${item.status === 'approved' ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                                        {item.status === 'approved' ? <Check size={18} /> : <X size={18} />}
                                    </div>
                                    <div>
                                        <p className="text-xs font-medium text-slate-900 tracking-normal">{item.profiles?.full_name || 'Staff'}</p>
                                        <p className="text-sm text-slate-500 font-medium">{item.start_date} — {item.end_date}</p>
                                    </div>
                                </div>
                                <span className={`text-xs font-medium  px-3 py-1 rounded-full border ${item.status === 'approved' ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>{item.status}</span>
                            </div>
                        ))}
                    </div>
                </div>
            ) : (
                <div className="space-y-4">
                    {leaves.length > 0 ? leaves.map(l => (
                        <div key={l.id} className="p-6 border border-slate-100 rounded-xl flex flex-col md:flex-row items-center justify-between gap-6 bg-white shadow-sm border-l-4 border-l-blue-500">
                            <div className="flex items-center gap-4">
                                <div className="w-12 h-12 bg-slate-900 text-white rounded-xl flex items-center justify-center font-medium">
                                    {l.profiles?.full_name?.[0] || '?'}
                                </div>
                                <div>
                                    <p className="text-sm font-medium text-slate-900">{l.profiles?.full_name}</p>
                                    <p className="text-sm text-slate-500 font-medium">{l.start_date} — {l.end_date}</p>
                                </div>
                            </div>
                            <div className="flex-1 text-slate-500 text-sm px-6 border-l border-slate-100 line-clamp-2">
                                "{l.reason || 'No reason'}"
                            </div>
                            <div className="flex gap-2 w-full md:w-auto">
                                <button onClick={() => handleAction(l.id, 'approved')} className="flex-1 bg-slate-900 text-white px-6 py-4 rounded-xl text-sm font-medium tracking-normal flex items-center justify-center gap-2 hover:bg-emerald-600 transition-colors"><Check size={14} /> Approve</button>
                                <button onClick={() => handleAction(l.id, 'declined')} className="flex-1 bg-white border border-slate-200 text-rose-500 px-6 py-4 rounded-xl text-sm font-medium tracking-normal flex items-center justify-center gap-2 hover:bg-rose-50 transition-colors"><X size={14} /> Reject</button>
                            </div>
                        </div>
                    )) : (
                        <div className="py-24 text-center border border-dashed border-slate-100 rounded-xl">
                            <p className="text-sm font-medium text-slate-500 tracking-normal">No pending requests</p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
}

'use client';
import { createClient } from '@/lib/supabase/client';
import { useEffect, useState } from 'react';
import { AlertCircle, CheckCircle2 } from 'lucide-react';

interface OverridesListProps {
    adminId: string;
}

export default function OverridesList({ adminId }: OverridesListProps) {
    const supabase = createClient();
    const [overrides, setOverrides] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    const fetchOverrides = async () => {
        const { data } = await supabase
            .from('swap_requests')
            .select('*, profiles:requestor_id(full_name)')
            .ilike('message', 'OVERRIDE REQUEST%')
            .eq('status', 'pending');
        setOverrides(data || []);
        setLoading(false);
    };

    useEffect(() => {
        fetchOverrides();

        const channel = supabase.channel('override-sync')
            .on('postgres_changes', {
                event: '*',
                schema: 'public',
                table: 'swap_requests'
            }, fetchOverrides)
            .subscribe();

        return () => { supabase.removeChannel(channel); };
    }, []);

    const handleApprove = async (request: any) => {
        const now = new Date();
        const today = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;

        // 1. Remove the accidental check-out to allow shift continuation
        await supabase.from('attendance')
            .update({ check_out: null, is_auto_checkout: false })
            .eq('employee_id', request.requestor_id)
            .gte('check_in', `${today}T00:00:00Z`);

        // 2. Mark request as approved
        await supabase.from('swap_requests')
            .update({ status: 'approved' })
            .eq('id', request.id);

        fetchOverrides();
    };

    if (loading) return <div className="p-8 text-slate-500 font-medium">Checking system logs...</div>;

    if (overrides.length === 0) {
        return (
            <div className="py-24 text-center">
                <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-4">
                    <CheckCircle2 className="text-slate-200" size={32} />
                </div>
                <p className="text-sm font-medium text-slate-500 tracking-normal">All Systems Clear</p>
            </div>
        );
    }

    return (
        <div className="space-y-4">
            {overrides.map(req => (
                <div key={req.id} className="bg-rose-50/40 p-6 rounded-xl border border-rose-100 flex flex-col md:flex-row items-center justify-between gap-6 transition-colors">
                    <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-rose-500 text-white rounded-xl flex items-center justify-center">
                            <AlertCircle size={24} />
                        </div>
                        <div>
                            <p className="text-sm font-medium text-slate-900">{req.profiles?.full_name}</p>
                            <p className="text-xs text-rose-600 font-medium mt-0.5">{req.message}</p>
                        </div>
                    </div>

                    <button
                        onClick={() => handleApprove(req)}
                        className="w-full md:w-auto bg-slate-900 text-white px-8 py-4 rounded-xl text-sm font-medium tracking-normal hover:bg-slate-800 transition-colors"
                    >
                        Approve Re-Entry
                    </button>
                </div>
            ))}
        </div>
    );
}

'use client';
import { useState, useEffect } from 'react';
import { createClient } from '@/lib/supabase/client';

export default function PresetManager() {
    const supabase = createClient();
    const [presets, setPresets] = useState<any[]>([]);
    const [label, setLabel] = useState('');
    const [start, setStart] = useState('10:00');
    const [end, setEnd] = useState('18:00');
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        fetchPresets();
    }, []);

    const fetchPresets = async () => {
        const { data } = await supabase.from('shift_presets').select('*').order('created_at', { ascending: true });
        setPresets(data || []);
    };

    const handleAdd = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!label) return;
        setLoading(true);

        const { error } = await supabase.from('shift_presets').insert([
            { label, start_time: start, end_time: end }
        ]);

        if (error) alert(error.message);
        else {
            setLabel('');
            fetchPresets();
        }
        setLoading(false);
    };

    const handleDelete = async (id: string) => {
        const { error } = await supabase.from('shift_presets').delete().eq('id', id);
        if (error) alert(error.message);
        else fetchPresets();
    };

    return (
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
            {/* Header */}
            <div className="px-4 py-3 border-b border-slate-100 bg-slate-50/50">
                <h3 className="text-sm font-medium tracking-normal text-slate-500">Shift Library</h3>
            </div>

            <div className="p-4">
                {/* Compact Form */}
                <form onSubmit={handleAdd} className="space-y-3 mb-6">
                    <div className="space-y-1">
                        <label className="text-xs font-medium text-slate-500 ml-1">Preset Label</label>
                        <input
                            type="text"
                            placeholder="e.g. Morning Shift"
                            value={label}
                            onChange={(e) => setLabel(e.target.value)}
                            className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs font-medium outline-none focus:border-slate-900 transition-colors"
                        />
                    </div>

                    <div className="grid grid-cols-2 gap-2">
                        <div className="space-y-1">
                            <label className="text-xs font-medium text-slate-500 ml-1">Start</label>
                            <input
                                type="time"
                                value={start}
                                onChange={(e) => setStart(e.target.value)}
                                className="w-full px-2 py-2 bg-white border border-slate-200 rounded-lg text-xs font-medium outline-none"
                            />
                        </div>
                        <div className="space-y-1">
                            <label className="text-xs font-medium text-slate-500 ml-1">End</label>
                            <input
                                type="time"
                                value={end}
                                onChange={(e) => setEnd(e.target.value)}
                                className="w-full px-2 py-2 bg-white border border-slate-200 rounded-lg text-xs font-medium outline-none"
                            />
                        </div>
                    </div>

                    <button
                        disabled={loading || !label}
                        className="w-full bg-slate-900 text-white text-sm font-medium py-2.5 rounded-lg hover:bg-slate-800 transition-colors disabled:opacity-20"
                    >
                        {loading ? 'Saving...' : 'Add to Library'}
                    </button>
                </form>

                {/* Compact List */}
                <div className="space-y-2">
                    <label className="text-xs font-medium text-slate-500 ml-1">Active Presets</label>
                    <div className="grid grid-cols-1 gap-2">
                        {presets.length === 0 && (
                            <p className="text-sm text-slate-500 py-2 text-center border border-dashed border-slate-100 rounded-lg">No presets defined</p>
                        )}
                        {presets.map((p) => (
                            <div
                                key={p.id}
                                className="group flex items-center justify-between p-2 bg-slate-50 border border-slate-100 rounded-lg hover:border-slate-300 transition-colors"
                            >
                                <div className="flex flex-col">
                                    <span className="text-sm font-medium text-slate-900 leading-tight">{p.label}</span>
                                    <span className="text-xs font-medium text-slate-500">{p.start_time.slice(0, 5)} — {p.end_time.slice(0, 5)}</span>
                                </div>
                                <button
                                    onClick={() => handleDelete(p.id)}
                                    className="p-1.5 text-slate-500 hover:text-red-500 hover:bg-red-50 rounded-md transition-colors opacity-0 group-hover:opacity-100"
                                >
                                    <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" />
                                    </svg>
                                </button>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';
import { useState, useEffect, useMemo } from 'react';
import { createClient } from '@/lib/supabase/client';
import { motion, type PanInfo } from 'framer-motion';
import {
    Calendar as CalendarIcon, Loader2, ArrowRight,
    AlertCircle, ArrowUpRight, ArrowDownRight,
    UserCheck, Activity, ChevronLeft, ChevronRight
} from 'lucide-react';

export default function ActivityLogView({ userId }: { userId: string }) {
    const supabase = createClient();
    const [logs, setLogs] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const now = new Date();
    const [searchDate, setSearchDate] = useState(`${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`);

    useEffect(() => { fetchLogs(); }, [userId, searchDate]);

    const fetchLogs = async () => {
        setLoading(true);
        let query = supabase
            .from('attendance')
            .select(`*, shifts(shift_label, start_time, end_time)`)
            .eq('employee_id', userId)
            .order('check_in', { ascending: false });

        if (searchDate) {
            query = query.gte('check_in', `${searchDate}T00:00:00Z`)
                .lte('check_in', `${searchDate}T23:59:59Z`);
        }

        const { data, error } = await query;
        if (!error) setLogs(data || []);
        setLoading(false);
    };

    // --- NAVIGATION LOGIC ---
    const navigateDate = (days: number) => {
        const current = new Date(searchDate);
        current.setDate(current.getDate() + days);
        const year = current.getFullYear();
        const month = String(current.getMonth() + 1).padStart(2, '0');
        const day = String(current.getDate()).padStart(2, '0');
        setSearchDate(`${year}-${month}-${day}`);
    };

    const handleDragEnd = (_event: MouseEvent | TouchEvent | PointerEvent, info: PanInfo) => {
        const swipeThreshold = 50;
        if (info.offset.x > swipeThreshold) {
            navigateDate(-1);
        } else if (info.offset.x < -swipeThreshold) {
            navigateDate(1);
        }
    };

    // --- HELPERS ---
    const getScheduledTime = (attendanceIn: string, shiftScheduled: string | null) => {
        if (!shiftScheduled) return null;
        const actualLogDate = new Date(attendanceIn);
        const dbShiftDate = new Date(shiftScheduled);
        const combined = new Date(actualLogDate);
        combined.setHours(dbShiftDate.getUTCHours(), dbShiftDate.getUTCMinutes(), 0, 0);
        return combined;
    };

    const formatDuration = (totalMinutes: number) => {
        const absMins = Math.abs(totalMinutes);
        const h = Math.floor(absMins / 60);
        const m = absMins % 60;
        return h > 0 ? `${h}h ${m}m` : `${m}m`;
    };

    const formatTimeDisplay = (dateString: string | null, useUTC = false) => {
        if (!dateString) return '--:--';
        const d = new Date(dateString);
        return d.toLocaleTimeString('en-US', {
            hour: '2-digit', minute: '2-digit', hour12: true,
            ...(useUTC && { timeZone: 'UTC' })
        });
    };

    const dayStats = useMemo(() => {
        const totals = { lateIn: 0, earlyIn: 0, earlyOut: 0, lateOut: 0, totalWork: 0 };
        logs.forEach(log => {
            const actualIn = new Date(log.check_in);
            const actualOut = log.check_out ? new Date(log.check_out) : null;
            const schedStart = getScheduledTime(log.check_in, log.shifts?.start_time);
            const schedEnd = getScheduledTime(log.check_in, log.shifts?.end_time);

            if (schedStart) {
                const diff = Math.floor((actualIn.getTime() - schedStart.getTime()) / 60000);
                if (diff > 0) totals.lateIn += diff;
                else totals.earlyIn += Math.abs(diff);
            }
            if (schedEnd && actualOut) {
                const diff = Math.floor((actualOut.getTime() - schedEnd.getTime()) / 60000);
                if (diff < 0) totals.earlyOut += Math.abs(diff);
                else totals.lateOut += diff;
            }
            if (actualOut) {
                const workMins = Math.floor((actualOut.getTime() - actualIn.getTime()) / 60000);
                totals.totalWork += workMins;
            }
        });
        return totals;
    }, [logs]);

    return (
        <motion.div
            drag="x"
            dragConstraints={{ left: 0, right: 0 }}
            onDragEnd={handleDragEnd}
            className="space-y-6"
        >
            <header className="mb-8">
                <div className="flex items-center justify-between mb-4">
                    <div>
                        <p className="text-sm font-medium text-slate-500 tracking-normal mb-1">Attendance history</p>
                        <h1 className="text-3xl font-medium text-slate-900">My attendance</h1>
                    </div>
                    <div className="relative group">
                        <input
                            aria-label="Attendance date" type="date"
                            value={searchDate}
                            onChange={(e) => setSearchDate(e.target.value)}
                            className="opacity-0 absolute inset-0 w-full h-full cursor-pointer z-10"
                        />
                        <div className="bg-black p-3 rounded-xl text-white transition-colors">
                            <CalendarIcon size={20} />
                        </div>
                    </div>
                </div>

                <div className="flex items-center gap-3 bg-white p-2 rounded-xl border border-slate-100 shadow-sm">
                    <button aria-label="Previous day" onClick={() => navigateDate(-1)} className="p-2 hover:bg-slate-50 rounded-xl transition-colors">
                        <ChevronLeft size={16} className="text-slate-900" />
                    </button>
                    <div className="flex-1 text-center text-sm font-medium tracking-normal text-slate-900">
                        {new Date(searchDate).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })}
                    </div>
                    <button aria-label="Next day" onClick={() => navigateDate(1)} className="p-2 hover:bg-slate-50 rounded-xl transition-colors">
                        <ChevronRight size={16} className="text-slate-900" />
                    </button>
                </div>
            </header>

            {/* DASHBOARD */}
            <>
                <div
                    key={searchDate}
                    className="space-y-3 mb-8"
                >
                    {/* TOTAL WORKING HOURS CARD */}
                    <div className="bg-white border border-slate-200 p-6 rounded-xl text-slate-900">
                        <div className="relative z-10">
                            <p className="text-sm font-medium tracking-normal mb-1">Total work hours</p>
                            <h3 className="text-3xl font-medium tracking-normal">
                                {formatDuration(dayStats.totalWork)}
                            </h3>
                        </div>
                    </div>

                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                        <StatCard label="Late arrival" value={formatDuration(dayStats.lateIn)} icon={<AlertCircle size={14} />} color="text-amber-600" bg="bg-amber-50" />
                        <StatCard label="Early arrival" value={formatDuration(dayStats.earlyIn)} icon={<UserCheck size={14} />} color="text-emerald-600" bg="bg-emerald-50" />
                        <StatCard label="Early departure" value={formatDuration(dayStats.earlyOut)} icon={<ArrowDownRight size={14} />} color="text-rose-600" bg="bg-rose-50" />
                        <StatCard label="Overtime" value={formatDuration(dayStats.lateOut)} icon={<ArrowUpRight size={14} />} color="text-blue-600" bg="bg-blue-50" />
                    </div>
                </div>
            </>

            {/* LOGS LIST */}
            <div className="space-y-4">
                {loading ? (
                    <div className="flex justify-center py-20"><Loader2 className="animate-spin" size={30} /></div>
                ) : logs.length > 0 ? (
                    logs.map((log) => {
                        const actualIn = new Date(log.check_in);
                        const actualOut = log.check_out ? new Date(log.check_out) : null;
                        const schedStart = getScheduledTime(log.check_in, log.shifts?.start_time);
                        const schedEnd = getScheduledTime(log.check_in, log.shifts?.end_time);

                        const diffIn = schedStart ? Math.floor((actualIn.getTime() - schedStart.getTime()) / 60000) : 0;
                        const diffOut = (schedEnd && actualOut) ? Math.floor((actualOut.getTime() - schedEnd.getTime()) / 60000) : 0;

                        // Session Work Calculation
                        const sessionMins = actualOut
                            ? Math.floor((actualOut.getTime() - actualIn.getTime()) / 60000)
                            : 0;

                        return (
                            <div
                                key={log.id}
                                className="bg-white border border-slate-100 p-6 rounded-xl shadow-sm"
                            >
                                <div className="flex flex-wrap items-start justify-between gap-3 mb-5">
                                    <div className="flex items-center gap-3 min-w-0">
                                        <div className="w-12 h-14 bg-black rounded-xl flex flex-col items-center justify-center text-white">
                                            <span className="text-xs font-medium">{actualIn.toLocaleDateString('en-US', { month: 'short' })}</span>
                                            <span className="text-sm font-medium mt-1">{actualIn.getDate()}</span>
                                        </div>
                                        <div>
                                            <p className="text-sm font-medium text-slate-900 tracking-normal leading-none">{log.shifts?.shift_label || 'Shift'}</p>
                                            <p className="text-xs font-medium text-slate-500 mt-2">
                                                Sched: {formatTimeDisplay(log.shifts?.start_time, true)} - {formatTimeDisplay(log.shifts?.end_time, true)}
                                            </p>
                                        </div>
                                    </div>

                                    <div className="flex flex-col items-end gap-1">
                                        {diffIn > 0 ? <Badge text={`Late ${formatDuration(diffIn)}`} color="amber" /> : <Badge text={`Early ${formatDuration(diffIn)}`} color="emerald" />}
                                        {actualOut && (diffOut < 0 ? <Badge text={`Early ${formatDuration(diffOut)}`} color="rose" /> : <Badge text={`OT ${formatDuration(diffOut)}`} color="blue" />)}
                                    </div>
                                </div>

                                <div className="flex items-center justify-between bg-slate-50/80 rounded-xl p-4 border border-slate-100 relative">
                                    <div className="space-y-1">
                                        <p className="text-xs font-medium text-slate-500 tracking-normal">In</p>
                                        <p className="text-xs font-medium text-slate-900">{formatTimeDisplay(log.check_in)}</p>
                                    </div>

                                    {/* Duration above Arrow */}
                                    <div className="flex flex-col items-center justify-center">
                                        <span className="text-xs font-medium text-indigo-600 mb-0.5">
                                            {log.check_out ? formatDuration(sessionMins) : 'Active'}
                                        </span>
                                        <ArrowRight size={14} className="text-slate-500" />
                                    </div>

                                    <div className="text-right space-y-1">
                                        <p className="text-xs font-medium text-slate-500 tracking-normal">Out</p>
                                        <p className={`text-xs font-medium ${log.check_out ? 'text-slate-900' : 'text-emerald-500 '}`}>
                                            {log.check_out ? formatTimeDisplay(log.check_out) : 'On Duty'}
                                        </p>
                                    </div>
                                </div>
                            </div>
                        );
                    })
                ) : (
                    <div className="text-center py-20 bg-white rounded-xl border border-dashed border-slate-200">
                        <Activity size={32} className="mx-auto text-slate-200 mb-2" />
                        <p className="text-sm font-medium text-slate-500 tracking-normal">No attendance records for this day</p>
                    </div>
                )}
            </div>
        </motion.div>
    );
}

function StatCard({ label, value, icon, color, bg }: any) {
    return (
        <div className={`${bg} p-4 rounded-xl border border-black/5 shadow-sm`}>
            <div className={`flex items-center gap-2 ${color} mb-1`}>
                {icon}
                <span className="text-xs font-medium tracking-normal">{label}</span>
            </div>
            <p className="text-lg font-medium text-slate-900">{value}</p>
        </div>
    );
}

function Badge({ text, color }: { text: string, color: 'amber' | 'emerald' | 'rose' | 'blue' }) {
    const colors = {
        amber: 'text-amber-600 bg-amber-50 border-amber-100',
        emerald: 'text-emerald-600 bg-emerald-50 border-emerald-100',
        rose: 'text-rose-600 bg-rose-50 border-rose-100',
        blue: 'text-blue-600 bg-blue-50 border-blue-100'
    };
    return <span className={`text-xs font-medium  px-2 py-0.5 rounded-md border ${colors[color]}`}>{text}</span>;
}

'use client';
import { useState, useEffect } from 'react';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { FileDown, CalendarDays } from 'lucide-react';

export default function EmployeePayslipsClient({ history }: { history: any[] }) {
    const [mounted, setMounted] = useState(false);

    useEffect(() => {
        setMounted(true);
    }, []);

    const downloadPDF = (rec: any) => {
        const generateFailsafeOrSuccess = (imgElement: HTMLImageElement | null) => {
            const doc = new jsPDF();
            const dateStr = new Date(rec.month_year).toLocaleString('en-IN', { month: 'long', year: 'numeric' });

            if (imgElement) {
                doc.addImage(imgElement, 'PNG', 95, 15, 20, 20); // Center standard 20x20
            }

            doc.setFontSize(22);
            doc.setFont("times", "bold");
            doc.text("THE MAKEUP STORE", 105, imgElement ? 45 : 25, { align: "center" });

            doc.setFontSize(10);
            doc.setFont("helvetica", "normal");
            doc.setTextColor(100);
            doc.text("Official Payslip & Settlement Record", 105, imgElement ? 51 : 31, { align: "center" });

            // Settlement Tracker
            const thisMonthHistory = history.filter(h => h.employee_id === rec.employee_id && new Date(h.month_year).getMonth() === new Date(rec.month_year).getMonth());
            const totalPaidThisMonth = thisMonthHistory.reduce((sum, h) => sum + h.net_pay, 0);

            const grossPay = Math.round(rec.gross_pay || 0);
            const netPay = Math.round(rec.net_pay || 0);
            const settlementLeft = Math.max(0, grossPay - totalPaidThisMonth);

            autoTable(doc, {
                startY: imgElement ? 65 : 45,
                margin: { left: 30, right: 30 }, // Constrict width heavily to center the table structurally
                head: [['Description', 'Amount (INR)']],
                body: [
                    ['Employee Name', rec.profiles?.full_name || 'N/A'],
                    ['Pay Period', dateStr],
                    ['Settlement Type', rec.type?.toUpperCase() || 'SALARY'],
                    ['Gross Base Earnings', grossPay.toLocaleString('en-IN')],
                    ['Overtime Compensation', Math.round(rec.overtime_pay).toLocaleString('en-IN')],
                    ['Bonus Allocation', Math.round(rec.bonus_pay).toLocaleString('en-IN')],
                    ['Deductions', `- ${Math.round(rec.deductions).toLocaleString('en-IN')}`],
                    ['NET SETTLEMENT', netPay.toLocaleString('en-IN')],
                    ['OUTSTANDING BALANCE', settlementLeft > 0 ? settlementLeft.toLocaleString('en-IN') : 'FULLY SETTLED'],
                ],
                theme: 'grid',
                headStyles: { fillColor: [15, 23, 42] },
                styles: { fontSize: 10, cellPadding: 8 },
                columnStyles: {
                    0: { fontStyle: 'bold', textColor: [30, 41, 59] },
                    1: { halign: 'right', textColor: [71, 85, 105], fontStyle: 'bold' }
                },
                didParseCell: function (data) {
                    if (data.row.index === 7 || data.row.index === 8) {
                        data.cell.styles.fontStyle = 'bold';
                        data.cell.styles.textColor = [15, 23, 42];
                    }
                }
            });

            // Footer Security Clause
            doc.setFontSize(8);
            doc.setTextColor(150);
            doc.text("This is a computer-generated document. No signature is required.", 105, 280, { align: "center" });

            doc.save(`Payslip_${(rec.profiles?.full_name || '').replace(/ /g, '_')}_${dateStr.replace(/ /g, '_')}.pdf`);
        };

        const img = new Image();
        img.src = '/icon-512x512.png';
        img.onload = () => generateFailsafeOrSuccess(img);
        img.onerror = () => generateFailsafeOrSuccess(null);
    };

    if (history.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center p-12 bg-white rounded-xl border border-black/5 mt-4 text-center">
                <CalendarDays size={32} className="text-black/20 mb-4" />
                <p className="text-sm font-medium text-slate-800 tracking-normal">No payslips yet</p>
                <p className="text-sm font-medium text-slate-500 mt-2">Your payslips will appear here once they are generated.</p>
            </div>
        );
    }

    return (
        <div className="grid grid-cols-1 gap-4">
            {history.map((rec) => (
                <div key={rec.id} className="bg-white p-6 rounded-xl border border-black/5 flex items-center justify-between gap-4">
                    <div>
                        <p className="text-lg font-medium text-slate-900 tracking-normal">
                            {mounted ? new Date(rec.month_year).toLocaleString('en-IN', { month: 'long', year: 'numeric' }) : '---'}
                        </p>
                        <div className="flex items-center gap-2 mt-2">
                            <span className="text-xs font-medium tracking-normal bg-indigo-50 text-indigo-500 px-2 py-1 rounded-[4px]">
                                {rec.type}
                            </span>
                            <span className="text-xs font-medium text-slate-500">
                                ₹{Math.round(rec.net_pay).toLocaleString('en-IN')}
                            </span>
                        </div>
                    </div>
                    <button
                        aria-label={`Download payslip for ${mounted ? new Date(rec.month_year).toLocaleString("en-IN", { month: "long", year: "numeric" }) : "pay period"}`} onClick={() => downloadPDF(rec)}
                        className="w-12 h-12 flex items-center justify-center bg-slate-900 text-white rounded-xl hover:bg-slate-800 transition-colors"
                    >
                        <FileDown size={18} />
                    </button>
                </div>
            ))}
        </div>
    );
}

'use client';
import { useState, useEffect } from 'react';
import { createClient } from '@/lib/supabase/client';
import { Clock, Send, Loader2, X, Plus, Trash2, ArrowRight } from 'lucide-react';
import WorkspaceDialog from '@/components/WorkspaceDialog';
import { createLeaveRequestAction } from '@/app/actions/requests';

export default function LeaveRequestView({ userId }: { userId: string }) {
    const supabase = createClient();
    const [showForm, setShowForm] = useState(false);
    const [history, setHistory] = useState<any[]>([]);
    const [stats, setStats] = useState({ approved: 0, pending: 0 });
    const [loading, setLoading] = useState(false);

    // Form State
