'use client';
import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import {
    Inbox, ArrowDownLeft, ArrowUpRight,
    Check, X, Clock, Loader2, MessageSquare, RefreshCcw, ShieldCheck
} from 'lucide-react';

export default function SwapInbox({ userId }: { userId: string }) {
    const supabase = createClient();
    const [requests, setRequests] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    const fetchRequests = useCallback(async () => {
        setLoading(true);

        const { data, error } = await supabase
            .from('swap_requests')
            .select(`
                *,
                requestor:profiles!requestor_id(full_name),
                receiver:profiles!receiver_id(full_name),
                shift:shifts(*)
            `)
            .eq('requestor_id', userId)
            .order('created_at', { ascending: false });

        if (!error) setRequests(data || []);
        setLoading(false);
    }, [userId, supabase]);

    useEffect(() => {
        fetchRequests();
    }, [fetchRequests]);

    const handleAction = async (request: any, newStatus: 'approved' | 'declined') => {
        if (newStatus === 'declined') {
            await supabase.from('swap_requests').update({ status: 'declined' }).eq('id', request.id);
            fetchRequests();
            return;
        }

        const d = new Date(request.shift?.start_time);
        const shiftDate = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

        // Find the user's corresponding shift on that day to interchange
        const { data: userShift, error: findError } = await supabase
            .from('shifts')
            .select('id')
            .eq('employee_id', userId)
            .filter('start_time', 'gte', `${shiftDate}T00:00:00Z`)
            .filter('start_time', 'lte', `${shiftDate}T23:59:59Z`)
            .maybeSingle();

        if (findError || !userShift) {
            alert("Shift mismatch: You don't have a record on this day to interchange.");
            return;
        }

        // Atomic peer swap logic
        const { error: err1 } = await supabase.from('shifts').update({ employee_id: userId }).eq('id', request.shift_id);
        const { error: err2 } = await supabase.from('shifts').update({ employee_id: request.requestor_id }).eq('id', userShift.id);

        if (!err1 && !err2) {
            await supabase.from('swap_requests').update({ status: 'approved' }).eq('id', request.id);
            fetchRequests();
        } else {
            alert("Swap failed. Please try again.");
        }
    };

    return (
        <div className="space-y-6">
            <header className="space-y-2">
                <div className="flex items-center  gap-2 mb-1">
                    <div className="w-2 h-2 rounded-full bg-slate-900" />
                    <span className="text-sm font-medium tracking-normal text-slate-500">Shift requests</span>
                </div>
                <h1 className="text-3xl font-medium text-slate-900">Inbox</h1>
            </header>

            <div className="space-y-4">
                {loading ? (
                    <div className="flex justify-center py-20"><Loader2 className="animate-spin" /></div>
                ) : requests.length > 0 ? (
                    <>
                        {requests.map((req) => {
                            const isSelfInterchange = req.requestor_id === req.receiver_id;

                            return (
                                <div
                                    key={req.id}
                                    className="bg-white border border-slate-100 p-6 rounded-xl shadow-sm"
                                >
                                    <div className="flex justify-between items-start mb-6">
                                        <div className="flex items-center gap-4">
                                            <div className={`w-12 h-12 rounded-xl flex items-center justify-center
                                                ${isSelfInterchange ? 'bg-indigo-50 text-indigo-500' : 'bg-slate-50 text-slate-500'}`}>
                                                {isSelfInterchange ? <ShieldCheck size={20} /> : <ArrowUpRight size={20} />}
                                            </div>
                                            <div>
                                                <p className="text-xs font-medium text-slate-500 tracking-normal leading-none mb-1">
                                                    {isSelfInterchange ? 'Awaiting admin review' : 'Sent to colleague'}
                                                </p>
                                                <p className="text-sm font-medium text-slate-900">
                                                    {isSelfInterchange ? 'Shift change request' : req.receiver?.full_name}
                                                </p>
                                            </div>
                                        </div>
                                        <StatusBadge status={req.status} />
                                    </div>

                                    <div className="bg-slate-50 rounded-xl p-5 mb-6 space-y-3">
                                        <div className="flex items-center gap-2">
                                            <Clock size={14} className="text-slate-500" />
                                            <span className="text-sm font-medium text-slate-600 tracking-normal">
                                                {new Date(req.shift?.start_time).toLocaleDateString('en-US', { day: 'numeric', month: 'short', year: 'numeric' })}
                                            </span>
                                        </div>
                                        {req.message && (
                                            <div className="flex items-start gap-2 pt-2 border-t border-slate-200/50">
                                                <MessageSquare size={14} className="text-slate-500 mt-0.5 shrink-0" />
                                                <div className="flex-1 space-y-2">
                                                    <p className="text-xs text-slate-500 leading-relaxed">"{req.message}"</p>
                                                    {req.note && (
                                                        <div className="bg-white border text-left border-gray-100 rounded-lg p-2.5">
                                                            <p className="text-xs font-medium text-slate-500 tracking-normal mb-1">Reason</p>
                                                            <p className="text-sm font-medium text-slate-600">"{req.note}"</p>
                                                        </div>
                                                    )}
                                                </div>
                                            </div>
                                        )}
                                    </div>

                                </div>
                            );
                        })}
                    </>
                ) : (
                    <div className="text-center py-12 rounded-xl border border-slate-200 bg-white">
                        <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-4 text-slate-200">
                            <Inbox size={24} />
                        </div>
                        <p className="text-sm font-medium text-slate-500 tracking-normal">No shift requests yet</p>
                    </div>
                )}
            </div>
        </div>
    );
}

function StatusBadge({ status }: { status: string }) {
    const s = status.toLowerCase();
    const styles: any = {
        pending: 'bg-amber-50 text-amber-600 border-amber-100',
        approved: 'bg-emerald-50 text-emerald-600 border-emerald-100',
        declined: 'bg-rose-50 text-rose-600 border-rose-100',
    };
    return (
        <span className={`px-3 py-1.5 rounded-full text-xs font-medium  tracking-normal border ${styles[s] || styles.pending}`}>
            {s}
        </span>
    );
}

'use client'

import { useState, useRef } from 'react'
import { Upload, X, Loader2, ImageIcon } from 'lucide-react'

interface ImageUploadProps {
  images: string[]
  onChange: (urls: string[]) => void
  maxImages?: number
  uploadAction: (formData: FormData) => Promise<{ success?: boolean; url?: string; error?: string }>
}

export default function ImageUpload({ images, onChange, maxImages = 5, uploadAction }: ImageUploadProps) {
  const [uploading, setUploading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files
    if (!files || files.length === 0) return

    setError(null)
    setUploading(true)

    try {
      for (const file of Array.from(files)) {
        if (images.length >= maxImages) break
        if (file.size > 5 * 1024 * 1024) {
          setError('Image too large (max 5MB)')
          continue
        }

        const formData = new FormData()
        formData.append('file', file)

        const result = await uploadAction(formData)
        if (result.success && result.url) {
          onChange([...images, result.url])
        } else {
          setError(result.error || 'Upload failed')
        }
      }
    } finally {
      setUploading(false)
      if (inputRef.current) inputRef.current.value = ''
    }
  }

  const removeImage = (index: number) => {
    const newImages = images.filter((_, i) => i !== index)
    onChange(newImages)
  }

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">
          Photos ({images.length}/{maxImages})
        </label>
        {images.length < maxImages && (
          <button
            type="button"
            onClick={() => inputRef.current?.click()}
            disabled={uploading}
            className="flex items-center gap-2 px-4 py-2 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all disabled:opacity-50"
          >
            {uploading ? <Loader2 size={14} className="animate-spin" /> : <Upload size={14} />}
            {uploading ? 'Uploading...' : 'Upload'}
          </button>
        )}
      </div>

      <input
        ref={inputRef}
        type="file"
        accept="image/*"
        multiple
        onChange={handleUpload}
        className="hidden"
      />

      {error && (
        <p className="text-[10px] font-bold text-rose-500">{error}</p>
      )}

      {images.length === 0 ? (
        <div
          onClick={() => inputRef.current?.click()}
          className="border-2 border-dashed border-slate-200 rounded-2xl p-8 flex flex-col items-center justify-center gap-2 cursor-pointer hover:border-slate-300 transition-colors"
        >
          <ImageIcon size={24} className="text-slate-300" />
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Tap to add photos</p>
        </div>
      ) : (
        <div className="grid grid-cols-3 md:grid-cols-5 gap-2">
          {images.map((url, index) => (
            <div key={index} className="relative group aspect-square rounded-xl overflow-hidden bg-slate-100">
              <img
                src={url}
                alt={`Photo ${index + 1}`}
                className="w-full h-full object-cover"
              />
              <button
                type="button"
                onClick={() => removeImage(index)}
                className="absolute top-1 right-1 p-1 bg-black/60 rounded-full text-white opacity-0 group-hover:opacity-100 transition-opacity"
              >
                <X size={12} />
              </button>
            </div>
          ))}
          {images.length < maxImages && (
            <button
              type="button"
              onClick={() => inputRef.current?.click()}
              disabled={uploading}
              className="aspect-square rounded-xl border-2 border-dashed border-slate-200 flex items-center justify-center text-slate-300 hover:border-slate-400 hover:text-slate-500 transition-colors disabled:opacity-50"
            >
              <Upload size={16} />
            </button>
          )}
        </div>
      )}
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { Check, Camera, Loader2, ChevronLeft, ChevronRight, ClipboardCheck } from 'lucide-react'
import { toast } from 'sonner'
import { motion, AnimatePresence } from 'framer-motion'
import { submitAuditAnswer, completeAudit, uploadAuditImage } from '@/app/actions/store-ops/audits'
import type { AuditWithRelations } from '@/lib/store-ops/types'

interface AuditRunnerProps {
  audit: AuditWithRelations
}

export default function AuditRunner({ audit }: AuditRunnerProps) {
  const router = useRouter()
  const isCompleted = audit.status === 'completed'

  const [currentIndex, setCurrentIndex] = useState(0)
  const [answers, setAnswers] = useState<Record<string, { score: number; comment: string; photoUrl: string | null }>>(
    () => {
      const initial: Record<string, any> = {}
      for (const a of audit.audit_answers) {
        initial[a.question_id] = {
          score: a.score || 0,
          comment: a.comment || '',
          photoUrl: a.photo_url || null,
        }
      }
      return initial
    }
  )
  const [submitting, setSubmitting] = useState(false)
  const [uploadingPhoto, setUploadingPhoto] = useState<string | null>(null)

  const questions = audit.audit_answers.map(a => ({
    answerId: a.id,
    questionId: a.question_id,
    question: a.audit_questions?.question || '',
    maxScore: a.audit_questions?.max_score || 5,
  }))

  const currentQ = questions[currentIndex]
  const currentAnswer = currentQ ? answers[currentQ.questionId] : null
  const progress = questions.length > 0 ? ((currentIndex + 1) / questions.length) * 100 : 0
  const answeredCount = Object.values(answers).filter(a => a.score > 0).length
  const totalScore = Object.values(answers).reduce((sum, a) => sum + a.score, 0)
  const totalMax = questions.reduce((sum, q) => sum + q.maxScore, 0)

  const handleScoreChange = (questionId: string, score: number) => {
    setAnswers(prev => ({
      ...prev,
      [questionId]: { ...prev[questionId], score: Math.min(score, questions.find(q => q.questionId === questionId)?.maxScore || 5) },
    }))
  }

  const handleCommentChange = (questionId: string, comment: string) => {
    setAnswers(prev => ({
      ...prev,
      [questionId]: { ...prev[questionId], comment },
    }))
  }

  const handlePhotoUpload = async (questionId: string) => {
    const input = document.createElement('input')
    input.type = 'file'
    input.accept = 'image/*'
    input.onchange = async (e) => {
      const file = (e.target as HTMLInputElement).files?.[0]
      if (!file) return

      setUploadingPhoto(questionId)
      const formData = new FormData()
      formData.append('file', file)

      const result = await uploadAuditImage(formData)
      if (result.success && result.url) {
        setAnswers(prev => ({
          ...prev,
          [questionId]: { ...prev[questionId], photoUrl: result.url },
        }))
        toast.success('Photo uploaded')
      } else {
        toast.error(result.error || 'Upload failed')
      }
      setUploadingPhoto(null)
    }
    input.click()
  }

  const saveCurrentAnswer = async () => {
    if (!currentQ || !currentAnswer) return
    const result = await submitAuditAnswer(
      audit.id,
      currentQ.questionId,
      currentAnswer.score,
      currentAnswer.comment || undefined,
      currentAnswer.photoUrl || undefined
    )
    if (result.error) toast.error(result.error)
  }

  const goNext = async () => {
    await saveCurrentAnswer()
    if (currentIndex < questions.length - 1) {
      setCurrentIndex(i => i + 1)
    }
  }

  const goPrev = async () => {
    await saveCurrentAnswer()
    if (currentIndex > 0) {
      setCurrentIndex(i => i - 1)
    }
  }

  const handleComplete = async () => {
    for (const q of questions) {
      const ans = answers[q.questionId]
      if (ans) {
        await submitAuditAnswer(audit.id, q.questionId, ans.score, ans.comment || undefined, ans.photoUrl || undefined)
      }
    }

    setSubmitting(true)
    try {
      const result = await completeAudit(audit.id)
      if (result.error) {
        toast.error(result.error)
      } else {
        const pct = result.data && result.data.max_score && result.data.max_score > 0
          ? Math.round((result.data.final_score / result.data.max_score) * 100)
          : 0
        toast.success(`Audit completed! Score: ${pct}%`)
        router.refresh()
      }
    } finally {
      setSubmitting(false)
    }
  }

  if (isCompleted) {
    const pct = audit.final_score !== null && audit.max_score && audit.max_score > 0
      ? Math.round((audit.final_score / audit.max_score) * 100)
      : 0

    return (
      <div className="max-w-2xl mx-auto space-y-6">
        <div className="bg-white border border-slate-200 rounded-2xl p-8 text-center space-y-4">
          <div className="w-20 h-20 rounded-full bg-emerald-50 flex items-center justify-center mx-auto">
            <ClipboardCheck size={40} className="text-emerald-500" />
          </div>
          <h2 className="text-2xl font-black text-slate-900 uppercase">Audit Complete</h2>
          <div className="text-5xl font-black text-slate-900">{pct}%</div>
          <p className="text-sm font-bold text-slate-500">{audit.final_score} / {audit.max_score} points</p>

          <div className="max-w-xs mx-auto bg-slate-50 rounded-full h-3 overflow-hidden">
            <div
              className="h-full bg-emerald-500 rounded-full transition-all duration-1000"
              style={{ width: `${pct}%` }}
            />
          </div>

          <div className="grid grid-cols-2 gap-4 pt-4">
            <div className="bg-slate-50 rounded-xl p-4">
              <p className="text-[9px] font-bold text-slate-400 uppercase tracking-wider">Passing</p>
              <p className="text-2xl font-black text-emerald-600">{pct >= 70 ? 'Yes' : 'No'}</p>
            </div>
            <div className="bg-slate-50 rounded-xl p-4">
              <p className="text-[9px] font-bold text-slate-400 uppercase tracking-wider">Questions</p>
              <p className="text-2xl font-black text-slate-900">{questions.length}</p>
            </div>
          </div>
        </div>

        <div className="space-y-3">
          {audit.audit_answers.map((a) => {
            const qScore = a.score || 0
            const qMax = a.audit_questions?.max_score || 5
            return (
              <div key={a.id} className="bg-white border border-slate-200 rounded-2xl p-5">
                <div className="flex items-start justify-between gap-4">
                  <div className="flex-1 min-w-0">
                    <p className="text-xs font-black text-slate-900">{a.audit_questions?.question}</p>
                    {a.comment && <p className="text-[10px] font-bold text-slate-500 mt-1">{a.comment}</p>}
                  </div>
                  <div className="shrink-0 text-right">
                    <span className="text-lg font-black text-slate-900">{qScore}/{qMax}</span>
                  </div>
                </div>
                {a.photo_url && (
                  <img src={a.photo_url} alt="" className="mt-3 w-24 h-24 rounded-xl object-cover bg-slate-100" />
                )}
              </div>
            )
          })}
        </div>
      </div>
    )
  }

  return (
    <div className="max-w-2xl mx-auto space-y-6">
      <div className="bg-white border border-slate-200 rounded-2xl p-6">
        <div className="flex items-center justify-between mb-4">
          <div>
            <h2 className="text-lg font-black text-slate-900 uppercase">{audit.audit_templates?.name}</h2>
            <p className="text-[10px] font-bold text-slate-400 mt-1">
              Question {currentIndex + 1} of {questions.length}
            </p>
          </div>
          <div className="text-right">
            <span className="text-2xl font-black text-slate-900">{answeredCount}/{questions.length}</span>
            <p className="text-[8px] font-bold text-slate-400 uppercase tracking-wider">Answered</p>
          </div>
        </div>

        <div className="bg-slate-100 rounded-full h-2 overflow-hidden">
          <div className="h-full bg-slate-900 rounded-full transition-all duration-500" style={{ width: `${progress}%` }} />
        </div>

        <div className="flex gap-1 mt-3">
          {questions.map((q, i) => {
            const ans = answers[q.questionId]
            const isFilled = ans && ans.score > 0
            return (
              <button
                key={q.questionId}
                onClick={() => setCurrentIndex(i)}
                className={`h-1.5 flex-1 rounded-full transition-all ${
                  i === currentIndex ? 'bg-slate-900' : isFilled ? 'bg-emerald-400' : 'bg-slate-200'
                }`}
              />
            )
          })}
        </div>
      </div>

      <AnimatePresence mode="wait">
        {currentQ && currentAnswer && (
          <motion.div
            key={currentQ.questionId}
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
            transition={{ duration: 0.15 }}
            className="bg-white border border-slate-200 rounded-2xl p-6 space-y-6"
          >
            <div>
              <div className="flex items-center gap-2 mb-1">
                <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest">
                  Question {currentIndex + 1}
                </span>
                <span className="text-[8px] font-bold text-slate-300">—</span>
                <span className="text-[8px] font-bold text-slate-400">
                  Max score: {currentQ.maxScore}
                </span>
              </div>
              <h3 className="text-lg font-black text-slate-900">{currentQ.question}</h3>
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">
                Score (0-{currentQ.maxScore})
              </label>
              <div className="flex items-center gap-4">
                <input
                  type="range"
                  min="0"
                  max={currentQ.maxScore}
                  value={currentAnswer.score}
                  onChange={(e) => handleScoreChange(currentQ.questionId, parseInt(e.target.value))}
                  className="flex-1 accent-slate-900"
                />
                <span className="text-2xl font-black text-slate-900 w-12 text-right tabular-nums">
                  {currentAnswer.score}
                </span>
              </div>
              <div className="flex justify-between text-[8px] font-bold text-slate-400">
                <span>0</span>
                <span>{currentQ.maxScore}</span>
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Comment</label>
              <textarea
                value={currentAnswer.comment}
                onChange={(e) => handleCommentChange(currentQ.questionId, e.target.value)}
                placeholder="Add notes or observations..."
                rows={3}
                className="w-full px-4 py-3 rounded-xl border border-slate-200 text-sm font-bold text-slate-900 outline-none focus:ring-2 focus:ring-slate-900/20 transition-all resize-none"
              />
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Photo</label>
              {currentAnswer.photoUrl ? (
                <div className="relative w-28 aspect-square rounded-xl overflow-hidden bg-slate-100">
                  <img src={currentAnswer.photoUrl} alt="" className="w-full h-full object-cover" />
                  <button
                    type="button"
                    onClick={() => setAnswers(prev => ({
                      ...prev,
                      [currentQ.questionId]: { ...prev[currentQ.questionId], photoUrl: null },
                    }))}
                    className="absolute top-1 right-1 p-1 bg-black/60 rounded-full text-white text-[8px]"
                  >
                    ✕
                  </button>
                </div>
              ) : (
                <button
                  type="button"
                  onClick={() => handlePhotoUpload(currentQ.questionId)}
                  disabled={uploadingPhoto === currentQ.questionId}
                  className="flex items-center gap-2 px-4 py-3 border border-dashed border-slate-300 rounded-xl text-[10px] font-bold text-slate-500 hover:border-slate-400 hover:text-slate-700 transition-all disabled:opacity-50"
                >
                  {uploadingPhoto === currentQ.questionId ? (
                    <Loader2 size={14} className="animate-spin" />
                  ) : (
                    <Camera size={14} />
                  )}
                  {uploadingPhoto === currentQ.questionId ? 'Uploading...' : 'Take Photo'}
                </button>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="flex items-center justify-between gap-3">
        <button
          onClick={goPrev}
          disabled={currentIndex === 0}
          className="flex items-center gap-2 px-5 py-3 bg-white border border-slate-200 rounded-xl text-[10px] font-black uppercase tracking-widest text-slate-500 hover:bg-slate-50 disabled:opacity-30 transition-all"
        >
          <ChevronLeft size={14} /> Previous
        </button>

        {currentIndex < questions.length - 1 ? (
          <button
            onClick={goNext}
            className="flex items-center gap-2 px-5 py-3 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all"
          >
            Next <ChevronRight size={14} />
          </button>
        ) : (
          <button
            onClick={handleComplete}
            disabled={submitting}
            className="flex items-center gap-2 px-6 py-3 bg-emerald-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-emerald-700 transition-all disabled:opacity-50"
          >
            {submitting ? <Loader2 size={14} className="animate-spin" /> : <Check size={14} />}
            {submitting ? 'Completing...' : `Complete Audit (${totalScore}/${totalMax})`}
          </button>
        )}
      </div>
    </div>
  )
}

'use client'

import { useRouter } from 'next/navigation'
import { Plus, Pencil, Trash2, Check, X } from 'lucide-react'
import { toast } from 'sonner'
import { deleteTemplate } from '@/app/actions/store-ops/daily-checklist'

interface TemplateListProps {
  templates: {
    id: string
    name: string
    type: 'opening' | 'closing'
    is_active: boolean
    created_by: string
  }[]
}

export default function ChecklistTemplateList({ templates }: TemplateListProps) {
  const router = useRouter()

  const handleDelete = async (id: string, name: string) => {
    if (!confirm(`Delete "${name}" template?`)) return
    const result = await deleteTemplate(id)
    if (result.error) toast.error(result.error)
    else {
      toast.success('Template deleted')
      router.refresh()
    }
  }

  const opening = templates.filter(t => t.type === 'opening')
  const closing = templates.filter(t => t.type === 'closing')

  return (
    <div className="space-y-8">
      <div className="flex items-center justify-between">
        <h2 className="text-lg font-black text-slate-900 uppercase">Checklist Templates</h2>
        <button
          onClick={() => router.push('/admin/store-operations/daily-checklist/templates/new')}
          className="flex items-center gap-2 px-4 py-2.5 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all"
        >
          <Plus size={14} /> New Template
        </button>
      </div>

      {templates.length === 0 ? (
        <div className="py-16 text-center border-2 border-dashed border-slate-100 rounded-2xl">
          <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">
            No templates yet — create one to get started
          </p>
        </div>
      ) : (
        <>
          <TemplateGroup type="opening" label="Opening" templates={opening} onDelete={handleDelete} />
          <TemplateGroup type="closing" label="Closing" templates={closing} onDelete={handleDelete} />
        </>
      )}
    </div>
  )
}

function TemplateGroup({
  type, label, templates, onDelete
}: {
