'use client'

import { useState, useEffect, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { createClient } from '@/lib/supabase/client'
import { toast } from 'sonner'
import { Check, X, Camera, Loader2, ClipboardCheck, Play } from 'lucide-react'
import {
  startDailyChecklist, completeChecklistItem,
  completeDailyChecklist, uploadChecklistPhoto,
  getTodayChecklist, getTemplates
} from '@/app/actions/store-ops/daily-checklist'

interface Template {
  id: string
  name: string
  type: 'opening' | 'closing'
}

interface ChecklistItem {
  id: string
  label: string
  is_completed: boolean
  completed_by: string | null
  completed_at: string | null
  photo_url: string | null
  sort_order: number
  profiles?: { full_name: string | null }
}

interface Checklist {
  id: string
  template_id: string
  type: 'opening' | 'closing'
  date: string
  status: string
  completed_by: string | null
  completed_at: string | null
  photo_url: string | null
  notes: string | null
  daily_checklist_items: ChecklistItem[]
}

export default function DailyCheckListView({ initialType }: { initialType: 'opening' | 'closing' }) {
  const router = useRouter()
  const supabase = createClient()
  const [type, setType] = useState<'opening' | 'closing'>(initialType)
  const [checklist, setChecklist] = useState<Checklist | null>(null)
  const [templates, setTemplates] = useState<Template[]>([])
  const [loading, setLoading] = useState(true)
  const [completing, setCompleting] = useState(false)
  const [notes, setNotes] = useState('')

  const fetchChecklist = useCallback(async () => {
    setLoading(true)
    const data = await getTodayChecklist(type)
    if (data && !('error' in data)) {
      setChecklist(data as Checklist)
    } else {
      setChecklist(null)
    }
    setLoading(false)
  }, [type])

  const fetchTemplates = useCallback(async () => {
    const data = await getTemplates()
    setTemplates(data.filter((t: Template) => t.type === type && !checklist))
  }, [type, checklist])

  useEffect(() => {
    fetchChecklist()
  }, [fetchChecklist])

  useEffect(() => {
    if (!checklist) fetchTemplates()
  }, [checklist, fetchTemplates])

  useEffect(() => {
    if (!checklist) return
    const channel = supabase.channel(`checklist_${checklist.id}`)
      .on('postgres_changes',
        { event: '*', schema: 'public', table: 'daily_checklist_items', filter: `daily_checklist_id=eq.${checklist.id}` },
        () => { fetchChecklist() }
      )
      .subscribe()
    return () => { supabase.removeChannel(channel) }
  }, [checklist?.id, fetchChecklist, supabase])

  const handleStartChecklist = async (templateId: string) => {
    const result = await startDailyChecklist(templateId, type)
    if (result.error) {
      toast.error(result.error)
    }
    fetchChecklist()
  }

  const handleToggleItem = async (itemId: string) => {
    const result = await completeChecklistItem(itemId)
    if (result.error) toast.error(result.error)
    else {
      setChecklist(prev => {
        if (!prev) return prev
        return {
          ...prev,
          daily_checklist_items: prev.daily_checklist_items.map(item =>
            item.id === itemId
              ? { ...item, is_completed: result.completed ?? !item.is_completed }
              : item
          )
        }
      })
    }
  }

  const handleCompleteChecklist = async () => {
    if (!checklist) return
    setCompleting(true)
    const result = await completeDailyChecklist(checklist.id, undefined, notes || undefined)
    if (result.error) toast.error(result.error)
    else {
      toast.success(`${type === 'opening' ? 'Opening' : 'Closing'} checklist completed!`)
      fetchChecklist()
    }
    setCompleting(false)
  }

  const allDone = checklist?.daily_checklist_items?.every(i => i.is_completed) ?? false
  const doneCount = checklist?.daily_checklist_items?.filter(i => i.is_completed).length ?? 0
  const totalCount = checklist?.daily_checklist_items?.length ?? 0

  if (loading) {
    return (
      <div className="py-20 flex justify-center">
        <Loader2 size={24} className="animate-spin text-slate-300" />
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Type Toggle */}
      <div className="flex gap-2 bg-white border border-slate-200 rounded-2xl p-1.5 w-fit">
        {(['opening', 'closing'] as const).map(t => (
          <button
            key={t}
            onClick={() => setType(t)}
            className={`px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
              type === t ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:text-slate-700'
            }`}
          >
            {t}
          </button>
        ))}
      </div>

      {!checklist || checklist.status !== 'in_progress' ? (
        <div className="space-y-4">
          {checklist?.status === 'completed' && (
            <div className="bg-emerald-50 border border-emerald-200 rounded-2xl p-6 text-center">
              <Check size={32} className="mx-auto text-emerald-500 mb-2" />
              <h3 className="text-sm font-black text-emerald-700 uppercase">Today&apos;s {type} checklist completed</h3>
              <p className="text-[10px] font-bold text-emerald-500 mt-1">
                {checklist.completed_at ? new Date(checklist.completed_at).toLocaleTimeString() : ''}
              </p>
            </div>
          )}

          <h2 className="text-lg font-black text-slate-900 uppercase">Start {type} Checklist</h2>

          {templates.length === 0 ? (
            <div className="py-12 text-center border-2 border-dashed border-slate-100 rounded-2xl">
              <ClipboardCheck size={32} className="mx-auto text-slate-200" />
              <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest mt-3">
                No {type} templates available. Ask an admin to create one.
              </p>
            </div>
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              {templates.map(t => (
                <button
                  key={t.id}
                  onClick={() => handleStartChecklist(t.id)}
                  className="flex items-center justify-between p-5 bg-white border border-slate-200 rounded-2xl hover:border-slate-300 hover:shadow-sm transition-all active:scale-[0.98]"
                >
                  <span className="text-sm font-black text-slate-900 uppercase">{t.name}</span>
                  <Play size={16} className="text-slate-400" />
                </button>
              ))}
            </div>
          )}
        </div>
      ) : (
        <div className="space-y-6">
          {/* Progress */}
          <div className="bg-white border border-slate-200 rounded-2xl p-5">
            <div className="flex items-center justify-between mb-3">
              <h3 className="text-xs font-black text-slate-900 uppercase">{type} Checklist</h3>
              <span className="text-[10px] font-bold text-slate-400">
                {doneCount}/{totalCount}
              </span>
            </div>
            <div className="h-2 bg-slate-100 rounded-full overflow-hidden">
              <div
                className="h-full bg-slate-900 rounded-full transition-all duration-500"
                style={{ width: `${totalCount > 0 ? (doneCount / totalCount) * 100 : 0}%` }}
              />
            </div>
          </div>

          {/* Items */}
          <div className="space-y-2">
            {checklist.daily_checklist_items
              ?.sort((a, b) => a.sort_order - b.sort_order)
              .map(item => (
                <button
                  key={item.id}
                  onClick={() => handleToggleItem(item.id)}
                  className={`w-full flex items-center gap-4 p-4 rounded-2xl border text-left transition-all active:scale-[0.99] ${
                    item.is_completed
                      ? 'bg-emerald-50 border-emerald-200'
                      : 'bg-white border-slate-200 hover:border-slate-300'
                  }`}
                >
                  <div className={`w-6 h-6 rounded-lg border-2 flex items-center justify-center shrink-0 transition-all ${
                    item.is_completed
                      ? 'bg-emerald-500 border-emerald-500 text-white'
                      : 'border-slate-300'
                  }`}>
                    {item.is_completed && <Check size={14} />}
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className={`text-sm font-bold transition-all ${
                      item.is_completed ? 'text-emerald-600 line-through' : 'text-slate-900'
                    }`}>
                      {item.label}
                    </p>
                    {item.completed_at && (
                      <p className="text-[8px] font-bold text-emerald-400 mt-0.5">
                        {new Date(item.completed_at).toLocaleTimeString()}
                      </p>
                    )}
                  </div>
                </button>
              ))}
          </div>

          {/* Complete Button */}
          {allDone && checklist.status === 'in_progress' && (
            <div className="bg-white border border-slate-200 rounded-2xl p-6 space-y-4">
              <textarea
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                placeholder="Add any notes (optional)..."
                rows={2}
                className="w-full px-4 py-3 rounded-xl border border-slate-200 text-sm font-bold text-slate-900 outline-none focus:ring-2 focus:ring-slate-900/20 transition-all resize-none"
              />
              <button
                onClick={handleCompleteChecklist}
                disabled={completing}
                className="w-full py-4 bg-emerald-600 text-white rounded-2xl text-[11px] font-black uppercase tracking-widest hover:bg-emerald-700 transition-all disabled:opacity-50 flex items-center justify-center gap-2"
              >
                {completing ? <Loader2 size={16} className="animate-spin" /> : <Check size={16} />}
                {completing ? 'Completing...' : 'Complete Checklist'}
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { createClient } from '@/lib/supabase/client'
import { toast } from 'sonner'
import {
  ArrowLeft, Check, X, Archive, Trash2, Send,
  ImageIcon, Loader2, User, Calendar, Hash, Tag, DollarSign, Package
} from 'lucide-react'
import {
  approveDamageReport, rejectDamageReport, archiveDamageReport,
  deleteDamageReport, addDamageComment, deleteDamageImage
} from '@/app/actions/store-ops/damage-reports'
import type { DamageReportWithRelations } from '@/lib/store-ops/types'
import { canManageApprovals, canDelete } from '@/lib/store-ops/permissions'

interface DamageReportDetailProps {
  report: DamageReportWithRelations
  userRole: string | null
  basePath: string
}

const statusStyles: Record<string, { bg: string; text: string; label: string }> = {
  pending: { bg: 'bg-amber-50 border-amber-100', text: 'text-amber-600', label: 'Pending Review' },
  approved: { bg: 'bg-emerald-50 border-emerald-100', text: 'text-emerald-600', label: 'Approved' },
  rejected: { bg: 'bg-rose-50 border-rose-100', text: 'text-rose-600', label: 'Rejected' },
  archived: { bg: 'bg-slate-50 border-slate-200', text: 'text-slate-500', label: 'Archived' },
}

export default function DamageReportDetail({ report, userRole, basePath }: DamageReportDetailProps) {
  const router = useRouter()
  const supabase = createClient()

  const [currentReport, setCurrentReport] = useState(report)
  const [comment, setComment] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [selectedImage, setSelectedImage] = useState<string | null>(null)

  const style = statusStyles[currentReport.status] || statusStyles.pending
  const isManager = canManageApprovals(userRole as 'admin' | 'manager' | 'employee' | null)
  const isAdmin = canDelete(userRole as 'admin' | 'manager' | 'employee' | null)

  useEffect(() => {
    const channel = supabase.channel(`damage_report_${report.id}`)
      .on('postgres_changes',
        { event: '*', schema: 'public', table: 'damage_reports', filter: `id=eq.${report.id}` },
        (payload) => {
          if (payload.new) setCurrentReport(prev => ({ ...prev, ...payload.new as any }))
        }
      )
      .on('postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'damage_comments', filter: `damage_report_id=eq.${report.id}` },
        async () => {
          const { data } = await supabase
            .from('damage_comments')
            .select('*, profiles:created_by(full_name)')
            .eq('damage_report_id', report.id)
            .order('created_at', { ascending: true })
          if (data) {
            setCurrentReport(prev => ({ ...prev, damage_comments: data as any }))
          }
        }
      )
      .subscribe()

    return () => { supabase.removeChannel(channel) }
  }, [report.id, supabase])

  const handleApprove = async () => {
    const result = await approveDamageReport(currentReport.id)
    if (result.error) toast.error(result.error)
    else {
      toast.success('Damage report approved')
      setCurrentReport(prev => ({ ...prev, status: 'approved' }))
    }
  }

  const handleReject = async () => {
    const result = await rejectDamageReport(currentReport.id)
    if (result.error) toast.error(result.error)
    else {
      toast.success('Damage report rejected')
      setCurrentReport(prev => ({ ...prev, status: 'rejected' }))
    }
  }

  const handleArchive = async () => {
    const result = await archiveDamageReport(currentReport.id)
    if (result.error) toast.error(result.error)
    else {
      toast.success('Damage report archived')
      setCurrentReport(prev => ({ ...prev, status: 'archived' }))
    }
  }

  const handleDelete = async () => {
    if (!confirm('Delete this damage report permanently?')) return
    const result = await deleteDamageReport(currentReport.id)
    if (result.error) toast.error(result.error)
    else {
      toast.success('Damage report deleted')
      router.push(basePath)
    }
  }

  const handleAddComment = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!comment.trim()) return
    setSubmitting(true)
    const result = await addDamageComment(currentReport.id, comment.trim())
    if (result.error) {
      toast.error(result.error)
    } else {
      setComment('')
    }
    setSubmitting(false)
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button
            onClick={() => router.back()}
            className="p-2 rounded-xl bg-slate-100 text-slate-500 hover:bg-slate-200 transition-colors"
          >
            <ArrowLeft size={18} />
          </button>
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-black text-slate-900 uppercase tracking-tight">
                {currentReport.product_name}
              </h1>
              <span className={`px-2.5 py-1 rounded-full text-[8px] font-black uppercase tracking-wider border ${style.bg} ${style.text}`}>
                {style.label}
              </span>
            </div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
              #{currentReport.barcode}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {currentReport.status === 'pending' && isManager && (
            <>
              <button onClick={handleApprove} className="flex items-center gap-1.5 px-4 py-2.5 bg-emerald-600 text-white rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-emerald-700 transition-all">
                <Check size={13} /> Approve
              </button>
              <button onClick={handleReject} className="flex items-center gap-1.5 px-4 py-2.5 bg-rose-500 text-white rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-rose-600 transition-all">
                <X size={13} /> Reject
              </button>
            </>
          )}
          {isManager && currentReport.status !== 'archived' && (
            <button onClick={handleArchive} className="flex items-center gap-1.5 px-4 py-2.5 bg-white border border-slate-200 text-slate-500 rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-slate-50 transition-all">
              <Archive size={13} /> Archive
            </button>
          )}
          {isAdmin && (
            <button onClick={handleDelete} className="flex items-center gap-1.5 px-4 py-2.5 bg-white border border-rose-200 text-rose-500 rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-rose-50 transition-all">
              <Trash2 size={13} /> Delete
            </button>
          )}
        </div>
      </div>

      {/* Content Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Details */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white border border-slate-200 rounded-2xl p-6 space-y-5">
            <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Product Details</h2>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
              <DetailItem icon={Hash} label="Barcode" value={currentReport.barcode} />
              <DetailItem icon={Tag} label="Brand" value={currentReport.brand || '—'} />
              <DetailItem icon={Tag} label="Shade" value={currentReport.shade || '—'} />
              <DetailItem icon={Package} label="Batch" value={currentReport.batch || '—'} />
              <DetailItem icon={DollarSign} label="MRP" value={currentReport.mrp ? `₹${currentReport.mrp}` : '—'} />
              <DetailItem icon={Package} label="Quantity" value={currentReport.quantity.toString()} />
              <DetailItem icon={Tag} label="Damage Type" value={currentReport.damage_type} />
              <DetailItem icon={User} label="Reported By" value={currentReport.profiles?.full_name || 'Unknown'} />
              <DetailItem icon={Calendar} label="Date" value={new Date(currentReport.created_at).toLocaleDateString()} />
            </div>
            {currentReport.description && (
              <div className="pt-4 border-t border-slate-100">
                <h3 className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2">Description</h3>
                <p className="text-sm font-bold text-slate-700 leading-relaxed">{currentReport.description}</p>
              </div>
            )}
          </div>

          {/* Image Gallery */}
          <div className="bg-white border border-slate-200 rounded-2xl p-6">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                Photos ({currentReport.damage_images?.length || 0})
              </h2>
            </div>
            {currentReport.damage_images && currentReport.damage_images.length > 0 ? (
              <div className="grid grid-cols-3 md:grid-cols-4 gap-3">
                {currentReport.damage_images.map((img) => (
                  <div key={img.id} className="relative group">
                    <button
                      onClick={() => setSelectedImage(img.url)}
                      className="aspect-square rounded-xl overflow-hidden bg-slate-100 w-full"
                    >
                      <img src={img.url} alt="" className="w-full h-full object-cover hover:scale-105 transition-transform" />
                    </button>
                    {isAdmin && (
                      <button
                        onClick={async () => {
                          await deleteDamageImage(img.id)
                          toast.success('Image removed')
                        }}
                        className="absolute top-1 right-1 p-1 bg-black/50 rounded-full text-white opacity-0 group-hover:opacity-100 transition-opacity"
                      >
                        <Trash2 size={10} />
                      </button>
                    )}
                  </div>
                ))}
              </div>
            ) : (
              <div className="py-10 text-center border-2 border-dashed border-slate-100 rounded-xl">
                <ImageIcon size={28} className="mx-auto text-slate-200" />
                <p className="text-[9px] font-black text-slate-300 uppercase tracking-widest mt-2">No photos</p>
              </div>
            )}
          </div>

          {/* Comments */}
          <div className="bg-white border border-slate-200 rounded-2xl p-6">
            <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">
              Comments ({currentReport.damage_comments?.length || 0})
            </h2>

            <div className="space-y-4 mb-6 max-h-[400px] overflow-y-auto">
              {currentReport.damage_comments && currentReport.damage_comments.length > 0 ? (
                currentReport.damage_comments.map((c) => (
                  <div key={c.id} className="flex gap-3 p-3 bg-slate-50 rounded-xl">
                    <div className="w-8 h-8 rounded-full bg-slate-900 text-white flex items-center justify-center text-[8px] font-black shrink-0 uppercase">
                      {(c as any).profiles?.full_name?.charAt(0) || '?'}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <span className="text-[10px] font-black text-slate-900 uppercase">
                          {(c as any).profiles?.full_name || 'Unknown'}
                        </span>
                        <span className="text-[8px] font-bold text-slate-400">
                          {new Date(c.created_at).toLocaleDateString()}
                        </span>
                      </div>
                      <p className="text-xs font-bold text-slate-600 mt-0.5">{c.comment}</p>
                    </div>
                  </div>
                ))
              ) : (
                <p className="text-[9px] font-bold text-slate-400 text-center py-6">No comments yet</p>
              )}
            </div>

            <form onSubmit={handleAddComment} className="flex gap-3">
              <input
                value={comment}
                onChange={(e) => setComment(e.target.value)}
                placeholder="Add a comment..."
                className="flex-1 px-4 py-2.5 rounded-xl border border-slate-200 text-sm font-bold text-slate-900 outline-none focus:ring-2 focus:ring-slate-900/20 transition-all"
              />
              <button
                type="submit"
                disabled={!comment.trim() || submitting}
                className="px-4 py-2.5 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all disabled:opacity-50 flex items-center gap-2"
              >
                {submitting ? <Loader2 size={14} className="animate-spin" /> : <Send size={14} />}
                Send
              </button>
            </form>
          </div>
        </div>

        {/* Sidebar */}
        <div className="space-y-6">
          {/* Status Timeline */}
          <div className="bg-white border border-slate-200 rounded-2xl p-6">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Timeline</h3>
            <div className="space-y-4">
              <TimelineItem
                icon={User}
                label="Reported"
                value={currentReport.profiles?.full_name || 'Unknown'}
                date={currentReport.created_at}
                active
              />
              {currentReport.reviewed_by && (
                <TimelineItem
                  icon={currentReport.status === 'approved' ? Check : X}
                  label={currentReport.status === 'approved' ? 'Approved' : 'Reviewed'}
                  value={`by ${currentReport.reviewed_by}`}
                  date={currentReport.reviewed_at || ''}
                  active
                />
              )}
            </div>
          </div>

          {/* Quick Stats */}
          <div className="bg-white border border-slate-200 rounded-2xl p-6">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Quick Info</h3>
            <div className="space-y-3">
              <StatRow label="Damage Value" value={currentReport.mrp ? `₹${(currentReport.mrp * currentReport.quantity).toLocaleString()}` : '—'} />
              <StatRow label="Status" value={style.label} valueClass={style.text} />
              <StatRow label="Quantity" value={currentReport.quantity.toString()} />
              <StatRow label="Type" value={currentReport.damage_type} />
            </div>
          </div>
        </div>
      </div>

      {/* Image Fullscreen Modal */}
      {selectedImage && (
        <div
          className="fixed inset-0 z-50 bg-black/90 flex items-center justify-center p-4"
          onClick={() => setSelectedImage(null)}
        >
          <button
            onClick={() => setSelectedImage(null)}
            className="absolute top-6 right-6 p-2 bg-white/10 rounded-full text-white hover:bg-white/20 transition-colors"
          >
            <X size={24} />
          </button>
          <img
            src={selectedImage}
            alt="Full size"
            className="max-w-full max-h-[90vh] object-contain rounded-2xl"
            onClick={(e) => e.stopPropagation()}
          />
        </div>
      )}
    </div>
  )
}

function DetailItem({ icon: Icon, label, value }: { icon: any; label: string; value: string }) {
  return (
    <div className="space-y-1">
      <div className="flex items-center gap-1.5 text-[9px] font-bold text-slate-400 uppercase tracking-wider">
        <Icon size={11} />
        {label}
      </div>
      <p className="text-sm font-black text-slate-900">{value}</p>
    </div>
  )
}

function TimelineItem({ icon: Icon, label, value, date, active }: { icon: any; label: string; value: string; date: string; active?: boolean }) {
  return (
    <div className="flex gap-3">
      <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${active ? 'bg-slate-900 text-white' : 'bg-slate-100 text-slate-400'}`}>
        <Icon size={13} />
      </div>
      <div>
        <p className="text-[11px] font-black text-slate-900 uppercase">{label}</p>
        <p className="text-[9px] font-bold text-slate-500">{value}</p>
        <p className="text-[8px] text-slate-400">{new Date(date).toLocaleDateString()}</p>
      </div>
    </div>
  )
}

function StatRow({ label, value, valueClass }: { label: string; value: string; valueClass?: string }) {
  return (
    <div className="flex items-center justify-between">
      <span className="text-[9px] font-bold text-slate-400 uppercase tracking-wider">{label}</span>
      <span className={`text-xs font-black ${valueClass || 'text-slate-900'}`}>{value}</span>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { createClient } from '@/lib/supabase/client'
import { Search, Filter, Plus, X, Loader2, ImageIcon } from 'lucide-react'
import { DAMAGE_TYPES, DAMAGE_REPORT_STATUSES } from '@/lib/store-ops/constants'
import type { DamageReportWithRelations } from '@/lib/store-ops/types'
import DamageReportCard from './DamageReportCard'

interface DamageReportListProps {
  initialData: DamageReportWithRelations[]
  total: number
  page: number
  totalPages: number
  basePath: string
  canCreate: boolean
}

const statusStyles: Record<string, { bg: string; text: string }> = {
  pending: { bg: 'bg-amber-50', text: 'text-amber-600' },
  approved: { bg: 'bg-emerald-50', text: 'text-emerald-600' },
  rejected: { bg: 'bg-rose-50', text: 'text-rose-600' },
  archived: { bg: 'bg-slate-100', text: 'text-slate-500' },
}

export default function DamageReportList({
  initialData, total, page: initialPage, totalPages: initialTotalPages, basePath, canCreate
}: DamageReportListProps) {
  const router = useRouter()
  const supabase = createClient()

  const [data, setData] = useState(initialData)
  const [totalCount, setTotalCount] = useState(total)
  const [currentPage, setCurrentPage] = useState(initialPage)
  const [totalPages, setTotalPages] = useState(initialTotalPages)
  const [loading, setLoading] = useState(false)

  const [search, setSearch] = useState('')
  const [statusFilter, setStatusFilter] = useState('')
  const [typeFilter, setTypeFilter] = useState('')
  const [showFilters, setShowFilters] = useState(false)

  const fetchData = useCallback(async (pageNum: number) => {
    setLoading(true)
    let query = supabase
      .from('damage_reports')
      .select(`
        *,
        profiles:reported_by(full_name, email),
        damage_images(*),
        damage_comments(*, profiles:created_by(full_name))
      `, { count: 'exact' })

    if (search) {
      query = query.or(`product_name.ilike.%${search}%,barcode.ilike.%${search}%`)
    }
    if (statusFilter) query = query.eq('status', statusFilter)
    if (typeFilter) query = query.eq('damage_type', typeFilter)

    const limit = 20
    const offset = (pageNum - 1) * limit
    query = query.order('created_at', { ascending: false }).range(offset, offset + limit - 1)

    const { data: results, count } = await query
    if (results) setData(results as unknown as DamageReportWithRelations[])
    if (count !== null) {
      setTotalCount(count)
      setTotalPages(Math.ceil(count / limit))
    }
    setLoading(false)
  }, [search, statusFilter, typeFilter, supabase])

  useEffect(() => {
    fetchData(currentPage)
  }, [currentPage, fetchData])

  useEffect(() => {
    const channel = supabase.channel('damage_reports_realtime')
      .on('postgres_changes',
        { event: '*', schema: 'public', table: 'damage_reports' },
        () => { fetchData(currentPage) }
      )
      .on('postgres_changes',
        { event: '*', schema: 'public', table: 'damage_images' },
        () => { fetchData(currentPage) }
      )
      .on('postgres_changes',
        { event: '*', schema: 'public', table: 'damage_comments' },
        () => { fetchData(currentPage) }
      )
      .subscribe()

    return () => { supabase.removeChannel(channel) }
  }, [currentPage, fetchData, supabase])

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault()
    setCurrentPage(1)
    fetchData(1)
  }

  const clearFilters = () => {
    setSearch('')
    setStatusFilter('')
    setTypeFilter('')
    setCurrentPage(1)
  }

  const hasFilters = search || statusFilter || typeFilter

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-black text-slate-900 uppercase tracking-tight">Damage Reports</h1>
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
            {totalCount} report{totalCount !== 1 ? 's' : ''}
          </p>
        </div>
        {canCreate && (
          <button
            onClick={() => router.push(`${basePath}/new`)}
            className="flex items-center gap-2 px-5 py-3 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all"
          >
            <Plus size={14} />
            New Report
          </button>
        )}
      </div>

      {/* Search & Filters */}
      <div className="flex items-center gap-3">
        <form onSubmit={handleSearch} className="flex-1 relative">
          <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
          <input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search by product name or barcode..."
            className="w-full pl-11 pr-4 py-3 rounded-xl border border-slate-200 bg-white text-sm font-bold text-slate-900 outline-none focus:ring-2 focus:ring-slate-900/20 transition-all"
          />
        </form>
        <button
          onClick={() => setShowFilters(!showFilters)}
          className={`p-3 rounded-xl border transition-all ${showFilters || hasFilters ? 'bg-slate-900 text-white border-slate-900' : 'bg-white text-slate-400 border-slate-200 hover:border-slate-300'}`}
        >
          <Filter size={18} />
        </button>
      </div>

      {/* Filter Panel */}
      {showFilters && (
        <div className="bg-slate-900 p-5 rounded-2xl space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Filters</h3>
            {hasFilters && (
              <button onClick={clearFilters} className="flex items-center gap-1 text-[9px] font-bold text-slate-400 hover:text-white transition-colors">
                <X size={12} /> Clear
              </button>
            )}
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            <div className="space-y-1">
              <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest ml-1">Status</label>
              <select
                value={statusFilter}
                onChange={(e) => { setStatusFilter(e.target.value); setCurrentPage(1) }}
                className="w-full bg-slate-800 border-none rounded-xl px-3 py-2.5 text-[11px] font-bold text-white outline-none"
              >
                <option value="">All Statuses</option>
                {DAMAGE_REPORT_STATUSES.map(s => (
                  <option key={s} value={s}>{s.charAt(0).toUpperCase() + s.slice(1)}</option>
                ))}
              </select>
            </div>
            <div className="space-y-1">
              <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest ml-1">Damage Type</label>
              <select
                value={typeFilter}
                onChange={(e) => { setTypeFilter(e.target.value); setCurrentPage(1) }}
                className="w-full bg-slate-800 border-none rounded-xl px-3 py-2.5 text-[11px] font-bold text-white outline-none"
              >
                <option value="">All Types</option>
                {DAMAGE_TYPES.map(t => (
                  <option key={t} value={t}>{t}</option>
                ))}
              </select>
            </div>
          </div>
        </div>
      )}

      {/* Desktop Table */}
      <div className="hidden md:block bg-white border border-slate-200 rounded-2xl overflow-hidden">
        <table className="w-full">
          <thead>
            <tr className="border-b border-slate-100">
              <th className="text-left px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Product</th>
              <th className="text-left px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Barcode</th>
              <th className="text-left px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Damage</th>
              <th className="text-left px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Status</th>
              <th className="text-left px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Reported</th>
              <th className="text-right px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Qty</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr>
                <td colSpan={6} className="py-20 text-center">
                  <Loader2 size={20} className="animate-spin mx-auto text-slate-300" />
                </td>
              </tr>
            ) : data.length === 0 ? (
              <tr>
                <td colSpan={6} className="py-20 text-center">
                  <div className="flex flex-col items-center gap-2">
                    <ImageIcon size={32} className="text-slate-200" />
                    <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">No damage reports found</p>
                  </div>
                </td>
              </tr>
            ) : (
              data.map(item => {
                const st = statusStyles[item.status] || statusStyles.pending
                return (
                  <tr
                    key={item.id}
                    onClick={() => router.push(`${basePath}/${item.id}`)}
                    className="border-b border-slate-50 hover:bg-slate-50 cursor-pointer transition-colors"
                  >
                    <td className="px-5 py-4">
                      <div className="flex items-center gap-3">
                        {item.damage_images?.[0] ? (
                          <div className="w-10 h-10 rounded-lg overflow-hidden bg-slate-100 shrink-0">
                            <img src={item.damage_images[0].url} alt="" className="w-full h-full object-cover" />
                          </div>
                        ) : (
                          <div className="w-10 h-10 rounded-lg bg-slate-100 flex items-center justify-center shrink-0">
                            <ImageIcon size={16} className="text-slate-300" />
                          </div>
                        )}
                        <div>
                          <p className="text-xs font-black text-slate-900 uppercase">{item.product_name}</p>
                          {item.brand && <p className="text-[9px] font-bold text-slate-400">{item.brand}</p>}
                        </div>
                      </div>
                    </td>
                    <td className="px-5 py-4 text-[11px] font-bold text-slate-500">#{item.barcode}</td>
                    <td className="px-5 py-4">
                      <span className="text-[10px] font-bold text-slate-500">{item.damage_type}</span>
                    </td>
                    <td className="px-5 py-4">
                      <span className={`px-2 py-0.5 rounded-full text-[8px] font-black uppercase tracking-wider ${st.bg} ${st.text}`}>
                        {item.status}
                      </span>
                    </td>
                    <td className="px-5 py-4">
                      <p className="text-[10px] font-bold text-slate-500">{item.profiles?.full_name || 'Unknown'}</p>
                      <p className="text-[8px] text-slate-400">{new Date(item.created_at).toLocaleDateString()}</p>
                    </td>
                    <td className="px-5 py-4 text-right text-sm font-black text-slate-900">{item.quantity}</td>
                  </tr>
                )
              })
            )}
          </tbody>
        </table>
      </div>

      {/* Mobile Cards */}
      <div className="md:hidden space-y-3">
        {loading ? (
          <div className="py-20 flex justify-center">
            <Loader2 size={24} className="animate-spin text-slate-300" />
          </div>
        ) : data.length === 0 ? (
          <div className="py-20 text-center">
            <div className="flex flex-col items-center gap-2">
              <ImageIcon size={40} className="text-slate-200" />
              <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">No damage reports found</p>
            </div>
          </div>
        ) : (
          data.map(item => (
            <DamageReportCard
              key={item.id}
              id={item.id}
              barcode={item.barcode}
              product_name={item.product_name}
              brand={item.brand}
              quantity={item.quantity}
              damage_type={item.damage_type}
              status={item.status}
              created_at={item.created_at}
              reporter_name={item.profiles?.full_name ?? null}
              images={item.damage_images || []}
              basePath={basePath}
            />
          ))
        )}
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-center gap-2">
          <button
            onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
            disabled={currentPage === 1}
            className="px-4 py-2 rounded-xl bg-white border border-slate-200 text-[10px] font-black uppercase tracking-widest text-slate-500 hover:bg-slate-50 disabled:opacity-30 transition-all"
          >
            Prev
          </button>
          {Array.from({ length: totalPages }, (_, i) => i + 1)
            .filter(p => p === 1 || p === totalPages || Math.abs(p - currentPage) <= 1)
            .map((p, idx, arr) => (
              <span key={p} className="flex items-center gap-1">
                {idx > 0 && arr[idx - 1] !== p - 1 && (
                  <span className="text-slate-300 text-[10px] font-bold px-1">...</span>
                )}
                <button
                  onClick={() => setCurrentPage(p)}
                  className={`w-9 h-9 rounded-xl text-[10px] font-black transition-all ${
                    currentPage === p
                      ? 'bg-slate-900 text-white'
                      : 'bg-white border border-slate-200 text-slate-500 hover:bg-slate-50'
                  }`}
                >
                  {p}
                </button>
              </span>
            ))}
          <button
            onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
            disabled={currentPage === totalPages}
            className="px-4 py-2 rounded-xl bg-white border border-slate-200 text-[10px] font-black uppercase tracking-widest text-slate-500 hover:bg-slate-50 disabled:opacity-30 transition-all"
          >
            Next
          </button>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { createClient } from '@/lib/supabase/client'
import { toast } from 'sonner'
import {
  ArrowLeft, Check, X, Trash2, Send, UserCircle,
  ImageIcon, Loader2, Calendar, Tag, Flag, UserCheck, MessageSquare
} from 'lucide-react'
import {
  updateIncidentStatus, deleteIncident, addIncidentComment,
  deleteIncidentImage, assignIncident
} from '@/app/actions/store-ops/incidents'
import type { IncidentWithRelations } from '@/lib/store-ops/types'
import { canManageApprovals, canDelete } from '@/lib/store-ops/permissions'
import { INCIDENT_STATUSES } from '@/lib/store-ops/constants'

interface IncidentDetailProps {
  incident: IncidentWithRelations
  userRole: string | null
  basePath: string
}

const statusStyles: Record<string, { bg: string; text: string; label: string }> = {
  open: { bg: 'bg-blue-50 border-blue-100', text: 'text-blue-600', label: 'Open' },
  in_progress: { bg: 'bg-amber-50 border-amber-100', text: 'text-amber-600', label: 'In Progress' },
  resolved: { bg: 'bg-emerald-50 border-emerald-100', text: 'text-emerald-600', label: 'Resolved' },
  closed: { bg: 'bg-slate-50 border-slate-200', text: 'text-slate-500', label: 'Closed' },
}

const typeLabels: Record<string, string> = {
  customer_complaint: 'Customer Complaint',
  power_failure: 'Power Failure',
  internet_down: 'Internet Down',
  theft: 'Theft',
  broken_fixture: 'Broken Fixture',
  emergency: 'Emergency',
  medical: 'Medical',
  other: 'Other',
}

export default function IncidentDetail({ incident, userRole, basePath }: IncidentDetailProps) {
  const router = useRouter()
  const supabase = createClient()

  const [currentIncident, setCurrentIncident] = useState(incident)
  const [comment, setComment] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [selectedImage, setSelectedImage] = useState<string | null>(null)
  const [assigneeEmail, setAssigneeEmail] = useState('')

  const style = statusStyles[currentIncident.status] || statusStyles.open
  const isManager = canManageApprovals(userRole as 'admin' | 'manager' | 'employee' | null)
  const isAdmin = canDelete(userRole as 'admin' | 'manager' | 'employee' | null)

  useEffect(() => {
    const channel = supabase.channel(`incident_${incident.id}`)
      .on('postgres_changes',
        { event: '*', schema: 'public', table: 'incidents', filter: `id=eq.${incident.id}` },
        (payload) => {
          if (payload.new) setCurrentIncident(prev => ({ ...prev, ...payload.new as Record<string, unknown> }))
        }
      )
      .on('postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'incident_comments', filter: `incident_id=eq.${incident.id}` },
        async () => {
          const { data } = await supabase
            .from('incident_comments')
            .select('*, profiles:created_by(full_name)')
            .eq('incident_id', incident.id)
            .order('created_at', { ascending: true })
          if (data) {
            setCurrentIncident(prev => ({ ...prev, incident_comments: data }))
          }
        }
      )
      .subscribe()

    return () => { supabase.removeChannel(channel) }
  }, [incident.id, supabase])

  const handleStatusChange = async (status: string) => {
    const result = await updateIncidentStatus(currentIncident.id, status)
    if (result.error) toast.error(result.error)
    else {
      toast.success(`Incident marked as ${status.replace('_', ' ')}`)
      setCurrentIncident(prev => ({ ...prev, status }))
    }
  }

  const handleDelete = async () => {
    if (!confirm('Delete this incident permanently?')) return
    const result = await deleteIncident(currentIncident.id)
    if (result.error) toast.error(result.error)
    else {
      toast.success('Incident deleted')
      router.push(basePath)
    }
  }

  const handleAddComment = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!comment.trim()) return
    setSubmitting(true)
    const result = await addIncidentComment(currentIncident.id, comment.trim())
    if (result.error) {
      toast.error(result.error)
    } else {
      setComment('')
    }
    setSubmitting(false)
  }

  const handleAssign = async () => {
    if (!assigneeEmail.trim()) return
    const { data: assignee } = await supabase
      .from('profiles')
      .select('id')
      .eq('email', assigneeEmail.trim())
      .single()

    if (!assignee) {
      toast.error('User not found')
      return
    }

    const result = await assignIncident(currentIncident.id, assignee.id)
    if (result.error) toast.error(result.error)
    else {
      toast.success('Incident assigned')
      setAssigneeEmail('')
      setCurrentIncident(prev => ({
        ...prev,
        assigned_to: assignee.id,
        assigned_to_profile: { full_name: assigneeEmail.trim() },
      }))
    }
  }

  const statusActions = INCIDENT_STATUSES.filter(s => s !== currentIncident.status)

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button
            onClick={() => router.back()}
            className="p-2 rounded-xl bg-slate-100 text-slate-500 hover:bg-slate-200 transition-colors"
          >
            <ArrowLeft size={18} />
          </button>
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-black text-slate-900 uppercase tracking-tight">
                {currentIncident.title}
              </h1>
              <span className={`px-2.5 py-1 rounded-full text-[8px] font-black uppercase tracking-wider border ${style.bg} ${style.text}`}>
                {style.label}
              </span>
            </div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
              {typeLabels[currentIncident.incident_type] || currentIncident.incident_type}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {isManager && statusActions.length > 0 && (
            <div className="flex items-center gap-1">
              {statusActions.map(s => (
                <button
                  key={s}
                  onClick={() => handleStatusChange(s)}
                  className={`flex items-center gap-1.5 px-3 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${
                    s === 'resolved' ? 'bg-emerald-600 text-white hover:bg-emerald-700' :
                    s === 'closed' ? 'bg-slate-700 text-white hover:bg-slate-800' :
                    'bg-amber-500 text-white hover:bg-amber-600'
                  }`}
                >
                  {s === 'resolved' ? <Check size={13} /> :
                   s === 'closed' ? <X size={13} /> :
                   <Flag size={13} />}
                  {s.replace('_', ' ')}
                </button>
              ))}
            </div>
          )}
          {isAdmin && (
            <button onClick={handleDelete} className="flex items-center gap-1.5 px-4 py-2.5 bg-white border border-rose-200 text-rose-500 rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-rose-50 transition-all">
              <Trash2 size={13} /> Delete
            </button>
          )}
        </div>
      </div>

      {/* Content Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Details */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white border border-slate-200 rounded-2xl p-6 space-y-5">
            <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Incident Details</h2>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
              <DetailItem icon={Tag} label="Type" value={typeLabels[currentIncident.incident_type] || currentIncident.incident_type} />
              <DetailItem icon={Flag} label="Priority" value={currentIncident.priority.charAt(0).toUpperCase() + currentIncident.priority.slice(1)} />
              <DetailItem icon={UserCircle} label="Reported By" value={currentIncident.profiles?.full_name || 'Unknown'} />
              <DetailItem icon={Calendar} label="Date" value={new Date(currentIncident.created_at).toLocaleDateString()} />
              <DetailItem icon={UserCheck} label="Assigned To" value={currentIncident.assigned_to_profile?.full_name || 'Unassigned'} />
              <DetailItem icon={MessageSquare} label="Comments" value={currentIncident.incident_comments?.length.toString() || '0'} />
            </div>
            {currentIncident.description && (
              <div className="pt-4 border-t border-slate-100">
                <h3 className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2">Description</h3>
                <p className="text-sm font-bold text-slate-700 leading-relaxed">{currentIncident.description}</p>
              </div>
            )}
          </div>

          {/* Assign */}
          {isManager && (
            <div className="bg-white border border-slate-200 rounded-2xl p-6">
              <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Assign Incident</h2>
              <div className="flex gap-3">
                <input
                  value={assigneeEmail}
                  onChange={(e) => setAssigneeEmail(e.target.value)}
                  placeholder="Enter employee email..."
                  className="flex-1 px-4 py-2.5 rounded-xl border border-slate-200 text-sm font-bold text-slate-900 outline-none focus:ring-2 focus:ring-slate-900/20 transition-all"
                />
                <button
                  onClick={handleAssign}
                  disabled={!assigneeEmail.trim()}
                  className="px-4 py-2.5 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all disabled:opacity-50 flex items-center gap-2"
                >
                  <UserCheck size={14} />
                  Assign
                </button>
              </div>
            </div>
          )}

          {/* Image Gallery */}
          <div className="bg-white border border-slate-200 rounded-2xl p-6">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                Photos ({currentIncident.incident_images?.length || 0})
              </h2>
            </div>
            {currentIncident.incident_images && currentIncident.incident_images.length > 0 ? (
              <div className="grid grid-cols-3 md:grid-cols-4 gap-3">
                {currentIncident.incident_images.map((img) => (
                  <div key={img.id} className="relative group">
                    <button
                      onClick={() => setSelectedImage(img.url)}
                      className="aspect-square rounded-xl overflow-hidden bg-slate-100 w-full"
                    >
                      <img src={img.url} alt="" className="w-full h-full object-cover hover:scale-105 transition-transform" />
                    </button>
                    {isAdmin && (
                      <button
                        onClick={async () => {
                          await deleteIncidentImage(img.id)
                          toast.success('Image removed')
                        }}
                        className="absolute top-1 right-1 p-1 bg-black/50 rounded-full text-white opacity-0 group-hover:opacity-100 transition-opacity"
                      >
                        <Trash2 size={10} />
                      </button>
                    )}
                  </div>
                ))}
              </div>
            ) : (
              <div className="py-10 text-center border-2 border-dashed border-slate-100 rounded-xl">
                <ImageIcon size={28} className="mx-auto text-slate-200" />
                <p className="text-[9px] font-black text-slate-300 uppercase tracking-widest mt-2">No photos</p>
              </div>
            )}
          </div>

          {/* Comments */}
          <div className="bg-white border border-slate-200 rounded-2xl p-6">
            <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">
              Comments ({currentIncident.incident_comments?.length || 0})
            </h2>

            <div className="space-y-4 mb-6 max-h-[400px] overflow-y-auto">
              {currentIncident.incident_comments && currentIncident.incident_comments.length > 0 ? (
                currentIncident.incident_comments.map((c) => (
                  <div key={c.id} className="flex gap-3 p-3 bg-slate-50 rounded-xl">
                    <div className="w-8 h-8 rounded-full bg-slate-900 text-white flex items-center justify-center text-[8px] font-black shrink-0 uppercase">
                      {(c as any).profiles?.full_name?.charAt(0) || '?'}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <span className="text-[10px] font-black text-slate-900 uppercase">
                          {(c as any).profiles?.full_name || 'Unknown'}
                        </span>
                        <span className="text-[8px] font-bold text-slate-400">
                          {new Date(c.created_at).toLocaleDateString()}
                        </span>
                      </div>
                      <p className="text-xs font-bold text-slate-600 mt-0.5">{c.comment}</p>
                    </div>
                  </div>
                ))
              ) : (
                <p className="text-[9px] font-bold text-slate-400 text-center py-6">No comments yet</p>
              )}
            </div>

            <form onSubmit={handleAddComment} className="flex gap-3">
              <input
                value={comment}
                onChange={(e) => setComment(e.target.value)}
                placeholder="Add a comment..."
                className="flex-1 px-4 py-2.5 rounded-xl border border-slate-200 text-sm font-bold text-slate-900 outline-none focus:ring-2 focus:ring-slate-900/20 transition-all"
              />
              <button
                type="submit"
                disabled={!comment.trim() || submitting}
                className="px-4 py-2.5 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all disabled:opacity-50 flex items-center gap-2"
              >
                {submitting ? <Loader2 size={14} className="animate-spin" /> : <Send size={14} />}
                Send
              </button>
            </form>
          </div>
        </div>

        {/* Sidebar */}
        <div className="space-y-6">
          {/* Status Timeline */}
          <div className="bg-white border border-slate-200 rounded-2xl p-6">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Timeline</h3>
            <div className="space-y-4">
              <TimelineItem
                icon={UserCircle}
                label="Reported"
                value={currentIncident.profiles?.full_name || 'Unknown'}
                date={currentIncident.created_at}
                active
              />
              {currentIncident.assigned_to && (
                <TimelineItem
                  icon={UserCheck}
                  label="Assigned"
                  value={currentIncident.assigned_to_profile?.full_name || 'Unknown'}
                  date={currentIncident.updated_at}
                  active
                />
              )}
            </div>
          </div>

          {/* Quick Stats */}
          <div className="bg-white border border-slate-200 rounded-2xl p-6">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Quick Info</h3>
            <div className="space-y-3">
              <StatRow label="Status" value={style.label} valueClass={style.text} />
              <StatRow label="Priority" value={currentIncident.priority.charAt(0).toUpperCase() + currentIncident.priority.slice(1)} />
              <StatRow label="Type" value={typeLabels[currentIncident.incident_type] || currentIncident.incident_type} />
              <StatRow label="Assignments" value={currentIncident.assigned_to ? 'Yes' : 'No'} />
            </div>
          </div>
        </div>
      </div>

      {/* Image Fullscreen Modal */}
      {selectedImage && (
        <div
          className="fixed inset-0 z-50 bg-black/90 flex items-center justify-center p-4"
          onClick={() => setSelectedImage(null)}
        >
          <button
            onClick={() => setSelectedImage(null)}
            className="absolute top-6 right-6 p-2 bg-white/10 rounded-full text-white hover:bg-white/20 transition-colors"
          >
            <X size={24} />
          </button>
          <img
            src={selectedImage}
            alt="Full size"
            className="max-w-full max-h-[90vh] object-contain rounded-2xl"
            onClick={(e) => e.stopPropagation()}
          />
        </div>
      )}
    </div>
  )
}

function DetailItem({ icon: Icon, label, value }: { icon: any; label: string; value: string }) {
  return (
    <div className="space-y-1">
      <div className="flex items-center gap-1.5 text-[9px] font-bold text-slate-400 uppercase tracking-wider">
        <Icon size={11} />
        {label}
      </div>
      <p className="text-sm font-black text-slate-900">{value}</p>
    </div>
  )
}

function TimelineItem({ icon: Icon, label, value, date, active }: { icon: any; label: string; value: string; date: string; active?: boolean }) {
  return (
    <div className="flex gap-3">
      <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${active ? 'bg-slate-900 text-white' : 'bg-slate-100 text-slate-400'}`}>
        <Icon size={13} />
      </div>
      <div>
        <p className="text-[11px] font-black text-slate-900 uppercase">{label}</p>
        <p className="text-[9px] font-bold text-slate-500">{value}</p>
        <p className="text-[8px] text-slate-400">{new Date(date).toLocaleDateString()}</p>
      </div>
    </div>
  )
}

function StatRow({ label, value, valueClass }: { label: string; value: string; valueClass?: string }) {
  return (
    <div className="flex items-center justify-between">
      <span className="text-[9px] font-bold text-slate-400 uppercase tracking-wider">{label}</span>
      <span className={`text-xs font-black ${valueClass || 'text-slate-900'}`}>{value}</span>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { createClient } from '@/lib/supabase/client'
import { Search, Filter, Plus, X, Loader2, ImageIcon } from 'lucide-react'
import { INCIDENT_TYPES, INCIDENT_PRIORITIES, INCIDENT_STATUSES } from '@/lib/store-ops/constants'
import type { IncidentWithRelations } from '@/lib/store-ops/types'
import IncidentCard from './IncidentCard'

interface IncidentListProps {
  initialData: IncidentWithRelations[]
  total: number
  page: number
  totalPages: number
  basePath: string
  canCreate: boolean
}

const statusStyles: Record<string, { bg: string; text: string }> = {
  open: { bg: 'bg-blue-50', text: 'text-blue-600' },
  in_progress: { bg: 'bg-amber-50', text: 'text-amber-600' },
  resolved: { bg: 'bg-emerald-50', text: 'text-emerald-600' },
  closed: { bg: 'bg-slate-100', text: 'text-slate-500' },
}

const typeLabels: Record<string, string> = {
  customer_complaint: 'Customer Complaint',
  power_failure: 'Power Failure',
  internet_down: 'Internet Down',
  theft: 'Theft',
  broken_fixture: 'Broken Fixture',
  emergency: 'Emergency',
  medical: 'Medical',
  other: 'Other',
}

export default function IncidentList({
  initialData, total, page: initialPage, totalPages: initialTotalPages, basePath, canCreate
}: IncidentListProps) {
  const router = useRouter()
  const supabase = createClient()

  const [data, setData] = useState(initialData)
  const [totalCount, setTotalCount] = useState(total)
  const [currentPage, setCurrentPage] = useState(initialPage)
  const [totalPages, setTotalPages] = useState(initialTotalPages)
  const [loading, setLoading] = useState(false)

  const [search, setSearch] = useState('')
  const [statusFilter, setStatusFilter] = useState('')
  const [typeFilter, setTypeFilter] = useState('')
  const [priorityFilter, setPriorityFilter] = useState('')
  const [showFilters, setShowFilters] = useState(false)

  const fetchData = useCallback(async (pageNum: number) => {
    setLoading(true)
    let query = supabase
      .from('incidents')
      .select(`
        *,
        profiles:created_by(full_name, email),
        assigned_to_profile:assigned_to(full_name),
        incident_images(*),
        incident_comments(*, profiles:created_by(full_name))
      `, { count: 'exact' })

    if (search) {
      query = query.or(`title.ilike.%${search}%,description.ilike.%${search}%`)
    }
    if (statusFilter) query = query.eq('status', statusFilter)
    if (typeFilter) query = query.eq('incident_type', typeFilter)
    if (priorityFilter) query = query.eq('priority', priorityFilter)

    const limit = 20
    const offset = (pageNum - 1) * limit
    query = query.order('created_at', { ascending: false }).range(offset, offset + limit - 1)

    const { data: results, count } = await query
    if (results) setData(results as unknown as IncidentWithRelations[])
    if (count !== null) {
      setTotalCount(count)
      setTotalPages(Math.ceil(count / limit))
    }
    setLoading(false)
  }, [search, statusFilter, typeFilter, priorityFilter, supabase])

  useEffect(() => {
    fetchData(currentPage)
  }, [currentPage, fetchData])

  useEffect(() => {
    const channel = supabase.channel('incidents_realtime')
      .on('postgres_changes',
        { event: '*', schema: 'public', table: 'incidents' },
        () => { fetchData(currentPage) }
      )
      .on('postgres_changes',
        { event: '*', schema: 'public', table: 'incident_images' },
        () => { fetchData(currentPage) }
      )
      .on('postgres_changes',
        { event: '*', schema: 'public', table: 'incident_comments' },
        () => { fetchData(currentPage) }
      )
      .subscribe()

    return () => { supabase.removeChannel(channel) }
  }, [currentPage, fetchData, supabase])

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault()
    setCurrentPage(1)
    fetchData(1)
  }

  const clearFilters = () => {
    setSearch('')
    setStatusFilter('')
    setTypeFilter('')
    setPriorityFilter('')
    setCurrentPage(1)
  }

  const hasFilters = search || statusFilter || typeFilter || priorityFilter

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-black text-slate-900 uppercase tracking-tight">Incidents</h1>
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
            {totalCount} incident{totalCount !== 1 ? 's' : ''}
          </p>
        </div>
        {canCreate && (
          <button
            onClick={() => router.push(`${basePath}/new`)}
            className="flex items-center gap-2 px-5 py-3 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all"
          >
            <Plus size={14} />
            New Incident
          </button>
        )}
      </div>

      {/* Search & Filters */}
      <div className="flex items-center gap-3">
        <form onSubmit={handleSearch} className="flex-1 relative">
          <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
          <input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search incidents..."
            className="w-full pl-11 pr-4 py-3 rounded-xl border border-slate-200 bg-white text-sm font-bold text-slate-900 outline-none focus:ring-2 focus:ring-slate-900/20 transition-all"
          />
        </form>
        <button
          onClick={() => setShowFilters(!showFilters)}
          className={`p-3 rounded-xl border transition-all ${showFilters || hasFilters ? 'bg-slate-900 text-white border-slate-900' : 'bg-white text-slate-400 border-slate-200 hover:border-slate-300'}`}
        >
          <Filter size={18} />
        </button>
      </div>

      {/* Filter Panel */}
      {showFilters && (
        <div className="bg-slate-900 p-5 rounded-2xl space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Filters</h3>
            {hasFilters && (
              <button onClick={clearFilters} className="flex items-center gap-1 text-[9px] font-bold text-slate-400 hover:text-white transition-colors">
                <X size={12} /> Clear
              </button>
            )}
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
            <div className="space-y-1">
              <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest ml-1">Status</label>
              <select
                value={statusFilter}
                onChange={(e) => { setStatusFilter(e.target.value); setCurrentPage(1) }}
                className="w-full bg-slate-800 border-none rounded-xl px-3 py-2.5 text-[11px] font-bold text-white outline-none"
              >
                <option value="">All Statuses</option>
                {INCIDENT_STATUSES.map(s => (
                  <option key={s} value={s}>{s.replace('_', ' ').replace(/\b\w/g, c => c.toUpperCase())}</option>
                ))}
              </select>
            </div>
            <div className="space-y-1">
              <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest ml-1">Type</label>
              <select
                value={typeFilter}
                onChange={(e) => { setTypeFilter(e.target.value); setCurrentPage(1) }}
                className="w-full bg-slate-800 border-none rounded-xl px-3 py-2.5 text-[11px] font-bold text-white outline-none"
              >
                <option value="">All Types</option>
                {INCIDENT_TYPES.map(t => (
                  <option key={t} value={t}>{typeLabels[t] || t}</option>
                ))}
              </select>
            </div>
            <div className="space-y-1">
              <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest ml-1">Priority</label>
              <select
                value={priorityFilter}
                onChange={(e) => { setPriorityFilter(e.target.value); setCurrentPage(1) }}
                className="w-full bg-slate-800 border-none rounded-xl px-3 py-2.5 text-[11px] font-bold text-white outline-none"
              >
                <option value="">All Priorities</option>
                {INCIDENT_PRIORITIES.map(p => (
                  <option key={p} value={p}>{p.charAt(0).toUpperCase() + p.slice(1)}</option>
                ))}
              </select>
            </div>
          </div>
        </div>
      )}

      {/* Desktop Table */}
      <div className="hidden md:block bg-white border border-slate-200 rounded-2xl overflow-hidden">
        <table className="w-full">
          <thead>
            <tr className="border-b border-slate-100">
              <th className="text-left px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Title</th>
              <th className="text-left px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Type</th>
              <th className="text-left px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Priority</th>
              <th className="text-left px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Status</th>
              <th className="text-left px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Reported</th>
              <th className="text-right px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Date</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr>
                <td colSpan={6} className="py-20 text-center">
                  <Loader2 size={20} className="animate-spin mx-auto text-slate-300" />
                </td>
              </tr>
            ) : data.length === 0 ? (
              <tr>
                <td colSpan={6} className="py-20 text-center">
                  <div className="flex flex-col items-center gap-2">
                    <ImageIcon size={32} className="text-slate-200" />
                    <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">No incidents found</p>
                  </div>
                </td>
              </tr>
            ) : (
              data.map(item => {
                const st = statusStyles[item.status] || statusStyles.open
                return (
                  <tr
                    key={item.id}
                    onClick={() => router.push(`${basePath}/${item.id}`)}
                    className="border-b border-slate-50 hover:bg-slate-50 cursor-pointer transition-colors"
                  >
                    <td className="px-5 py-4">
                      <div className="flex items-center gap-3">
                        {item.incident_images?.[0] ? (
                          <div className="w-10 h-10 rounded-lg overflow-hidden bg-slate-100 shrink-0">
                            <img src={item.incident_images[0].url} alt="" className="w-full h-full object-cover" />
                          </div>
                        ) : (
                          <div className="w-10 h-10 rounded-lg bg-slate-100 flex items-center justify-center shrink-0">
                            <ImageIcon size={16} className="text-slate-300" />
                          </div>
                        )}
                        <div>
                          <p className="text-xs font-black text-slate-900 uppercase">{item.title}</p>
                          {item.assigned_to_profile?.full_name && (
                            <p className="text-[9px] font-bold text-slate-400">Assigned to {item.assigned_to_profile.full_name}</p>
                          )}
                        </div>
                      </div>
                    </td>
                    <td className="px-5 py-4">
                      <span className="text-[10px] font-bold text-slate-500">{typeLabels[item.incident_type] || item.incident_type}</span>
                    </td>
                    <td className="px-5 py-4">
                      <span className={`text-[10px] font-black uppercase ${
                        item.priority === 'urgent' ? 'text-rose-600' :
                        item.priority === 'high' ? 'text-rose-500' :
                        item.priority === 'medium' ? 'text-amber-500' :
                        'text-slate-400'
                      }`}>
                        {item.priority}
                      </span>
                    </td>
                    <td className="px-5 py-4">
                      <span className={`px-2 py-0.5 rounded-full text-[8px] font-black uppercase tracking-wider ${st.bg} ${st.text}`}>
                        {item.status.replace('_', ' ')}
                      </span>
                    </td>
                    <td className="px-5 py-4">
                      <p className="text-[10px] font-bold text-slate-500">{item.profiles?.full_name || 'Unknown'}</p>
                    </td>
                    <td className="px-5 py-4 text-right text-[10px] font-bold text-slate-500">
                      {new Date(item.created_at).toLocaleDateString()}
                    </td>
                  </tr>
                )
              })
            )}
          </tbody>
        </table>
      </div>

      {/* Mobile Cards */}
      <div className="md:hidden space-y-3">
        {loading ? (
          <div className="py-20 flex justify-center">
            <Loader2 size={24} className="animate-spin text-slate-300" />
          </div>
        ) : data.length === 0 ? (
          <div className="py-20 text-center">
            <div className="flex flex-col items-center gap-2">
              <ImageIcon size={40} className="text-slate-200" />
              <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">No incidents found</p>
            </div>
          </div>
        ) : (
          data.map(item => (
            <IncidentCard
              key={item.id}
              id={item.id}
              title={item.title}
              incident_type={item.incident_type}
              priority={item.priority}
              status={item.status}
              created_at={item.created_at}
              reporter_name={item.profiles?.full_name ?? null}
              images={item.incident_images || []}
              basePath={basePath}
            />
          ))
        )}
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-center gap-2">
          <button
            onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
            disabled={currentPage === 1}
            className="px-4 py-2 rounded-xl bg-white border border-slate-200 text-[10px] font-black uppercase tracking-widest text-slate-500 hover:bg-slate-50 disabled:opacity-30 transition-all"
          >
            Prev
          </button>
          {Array.from({ length: totalPages }, (_, i) => i + 1)
            .filter(p => p === 1 || p === totalPages || Math.abs(p - currentPage) <= 1)
            .map((p, idx, arr) => (
              <span key={p} className="flex items-center gap-1">
                {idx > 0 && arr[idx - 1] !== p - 1 && (
                  <span className="text-slate-300 text-[10px] font-bold px-1">...</span>
                )}
                <button
                  onClick={() => setCurrentPage(p)}
                  className={`w-9 h-9 rounded-xl text-[10px] font-black transition-all ${
                    currentPage === p
                      ? 'bg-slate-900 text-white'
                      : 'bg-white border border-slate-200 text-slate-500 hover:bg-slate-50'
                  }`}
                >
                  {p}
                </button>
              </span>
            ))}
          <button
            onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
            disabled={currentPage === totalPages}
            className="px-4 py-2 rounded-xl bg-white border border-slate-200 text-[10px] font-black uppercase tracking-widest text-slate-500 hover:bg-slate-50 disabled:opacity-30 transition-all"
          >
            Next
          </button>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { createClient } from '@/lib/supabase/client'
import { toast } from 'sonner'
import {
  ArrowLeft, Check, X, Trash2, Package,
  Loader2, User, Calendar, Hash, FileText
} from 'lucide-react'
import {
  approveRestockRequest, rejectRestockRequest,
  completeRestockRequest, deleteRestockRequest
} from '@/app/actions/store-ops/restocking'
import type { RestockRequestWithRelations } from '@/lib/store-ops/types'
import { canManageApprovals, canDelete } from '@/lib/store-ops/permissions'

interface RestockDetailProps {
  request: RestockRequestWithRelations
  userRole: string | null
  basePath: string
}

const statusStyles: Record<string, { bg: string; text: string; label: string }> = {
  pending: { bg: 'bg-amber-50 border-amber-100', text: 'text-amber-600', label: 'Pending Review' },
  approved: { bg: 'bg-emerald-50 border-emerald-100', text: 'text-emerald-600', label: 'Approved' },
  rejected: { bg: 'bg-rose-50 border-rose-100', text: 'text-rose-600', label: 'Rejected' },
  completed: { bg: 'bg-blue-50 border-blue-100', text: 'text-blue-600', label: 'Completed' },
}

export default function RestockDetail({ request, userRole, basePath }: RestockDetailProps) {
  const router = useRouter()
  const supabase = createClient()

  const [currentRequest, setCurrentRequest] = useState(request)
  const [submitting, setSubmitting] = useState(false)

  const style = statusStyles[currentRequest.status] || statusStyles.pending
  const isManager = canManageApprovals(userRole as any)
  const isAdmin = canDelete(userRole as any)

  useEffect(() => {
    const channel = supabase.channel(`restock_request_${request.id}`)
      .on('postgres_changes',
        { event: '*', schema: 'public', table: 'restock_requests', filter: `id=eq.${request.id}` },
        (payload) => {
          if (payload.new) setCurrentRequest(prev => ({ ...prev, ...payload.new as any }))
        }
      )
      .subscribe()

    return () => { supabase.removeChannel(channel) }
  }, [request.id, supabase])

  const handleApprove = async () => {
    setSubmitting(true)
    const result = await approveRestockRequest(currentRequest.id)
    if (result.error) toast.error(result.error)
    else {
      toast.success('Restock request approved')
      setCurrentRequest(prev => ({ ...prev, status: 'approved' }))
    }
    setSubmitting(false)
  }

  const handleReject = async () => {
    setSubmitting(true)
    const result = await rejectRestockRequest(currentRequest.id)
    if (result.error) toast.error(result.error)
    else {
      toast.success('Restock request rejected')
      setCurrentRequest(prev => ({ ...prev, status: 'rejected' }))
    }
    setSubmitting(false)
  }

  const handleComplete = async () => {
    setSubmitting(true)
    const result = await completeRestockRequest(currentRequest.id)
    if (result.error) toast.error(result.error)
    else {
      toast.success('Restock completed')
      setCurrentRequest(prev => ({ ...prev, status: 'completed' }))
    }
    setSubmitting(false)
  }

  const handleDelete = async () => {
    if (!confirm('Delete this restock request permanently?')) return
    const result = await deleteRestockRequest(currentRequest.id)
    if (result.error) toast.error(result.error)
    else {
      toast.success('Restock request deleted')
      router.push(basePath)
    }
  }

  const items = currentRequest.restock_items || []

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button
            onClick={() => router.back()}
            className="p-2 rounded-xl bg-slate-100 text-slate-500 hover:bg-slate-200 transition-colors"
          >
            <ArrowLeft size={18} />
          </button>
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-black text-slate-900 uppercase tracking-tight">
                {currentRequest.notes || 'Restock Request'}
              </h1>
              <span className={`px-2.5 py-1 rounded-full text-[8px] font-black uppercase tracking-wider border ${style.bg} ${style.text}`}>
                {style.label}
              </span>
            </div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
              {items.length} item{items.length !== 1 ? 's' : ''}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {currentRequest.status === 'pending' && isManager && (
            <>
              <button onClick={handleApprove} disabled={submitting} className="flex items-center gap-1.5 px-4 py-2.5 bg-emerald-600 text-white rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-emerald-700 transition-all disabled:opacity-50">
                <Check size={13} /> Approve
              </button>
              <button onClick={handleReject} disabled={submitting} className="flex items-center gap-1.5 px-4 py-2.5 bg-rose-500 text-white rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-rose-600 transition-all disabled:opacity-50">
                <X size={13} /> Reject
              </button>
            </>
          )}
          {currentRequest.status === 'approved' && isManager && (
            <button onClick={handleComplete} disabled={submitting} className="flex items-center gap-1.5 px-4 py-2.5 bg-blue-600 text-white rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-blue-700 transition-all disabled:opacity-50">
              <Check size={13} /> Complete
            </button>
          )}
          {isAdmin && (
            <button onClick={handleDelete} className="flex items-center gap-1.5 px-4 py-2.5 bg-white border border-rose-200 text-rose-500 rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-rose-50 transition-all">
              <Trash2 size={13} /> Delete
            </button>
          )}
        </div>
      </div>

      {/* Content Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Main */}
        <div className="lg:col-span-2 space-y-6">
          {/* Items Table */}
          <div className="bg-white border border-slate-200 rounded-2xl overflow-hidden">
            <div className="px-6 py-4 border-b border-slate-100">
              <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Items</h2>
            </div>
            <table className="w-full">
              <thead>
                <tr className="border-b border-slate-50">
                  <th className="text-left px-6 py-3 text-[8px] font-black text-slate-400 uppercase tracking-widest">Product</th>
                  <th className="text-left px-6 py-3 text-[8px] font-black text-slate-400 uppercase tracking-widest">Barcode</th>
                  <th className="text-left px-6 py-3 text-[8px] font-black text-slate-400 uppercase tracking-widest">Brand</th>
                  <th className="text-right px-6 py-3 text-[8px] font-black text-slate-400 uppercase tracking-widest">Qty Needed</th>
                </tr>
              </thead>
              <tbody>
                {items.length === 0 ? (
                  <tr>
                    <td colSpan={4} className="py-12 text-center">
                      <Package size={24} className="mx-auto text-slate-200" />
                      <p className="text-[9px] font-black text-slate-300 uppercase tracking-widest mt-2">No items</p>
                    </td>
                  </tr>
                ) : (
                  items.map(item => (
                    <tr key={item.id} className="border-b border-slate-50 last:border-none">
                      <td className="px-6 py-4">
                        <p className="text-xs font-black text-slate-900 uppercase">{item.product_name}</p>
                      </td>
                      <td className="px-6 py-4 text-[11px] font-bold text-slate-500">#{item.barcode}</td>
                      <td className="px-6 py-4 text-[11px] font-bold text-slate-500">{item.brand || '—'}</td>
                      <td className="px-6 py-4 text-right text-sm font-black text-slate-900">{item.quantity_needed}</td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>

          {/* Notes */}
          {currentRequest.notes && (
            <div className="bg-white border border-slate-200 rounded-2xl p-6">
              <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Notes</h2>
              <p className="text-sm font-bold text-slate-700 leading-relaxed">{currentRequest.notes}</p>
            </div>
          )}
        </div>

        {/* Sidebar */}
        <div className="space-y-6">
          {/* Status Timeline */}
          <div className="bg-white border border-slate-200 rounded-2xl p-6">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Timeline</h3>
            <div className="space-y-4">
              <TimelineItem
                icon={User}
                label="Requested by"
                value={currentRequest.profiles?.full_name || 'Unknown'}
                date={currentRequest.created_at}
                active
              />
              {currentRequest.approved_by && (
                <TimelineItem
                  icon={Check}
                  label="Approved"
                  value={`by ${currentRequest.approved_by}`}
                  date={currentRequest.approved_at || ''}
                  active
                />
              )}
              {currentRequest.status === 'completed' && (
                <TimelineItem
                  icon={Package}
                  label="Completed"
                  value="Restock finished"
                  date={currentRequest.updated_at}
                  active
                />
              )}
            </div>
          </div>

          {/* Quick Info */}
          <div className="bg-white border border-slate-200 rounded-2xl p-6">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Quick Info</h3>
            <div className="space-y-3">
              <StatRow label="Status" value={style.label} valueClass={style.text} />
              <StatRow label="Items" value={items.length.toString()} />
              <StatRow label="Date" value={new Date(currentRequest.created_at).toLocaleDateString()} />
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

function DetailItem({ icon: Icon, label, value }: { icon: any; label: string; value: string }) {
  return (
    <div className="space-y-1">
      <div className="flex items-center gap-1.5 text-[9px] font-bold text-slate-400 uppercase tracking-wider">
        <Icon size={11} />
        {label}
      </div>
      <p className="text-sm font-black text-slate-900">{value}</p>
    </div>
  )
}

function TimelineItem({ icon: Icon, label, value, date, active }: { icon: any; label: string; value: string; date: string; active?: boolean }) {
  return (
    <div className="flex gap-3">
      <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${active ? 'bg-slate-900 text-white' : 'bg-slate-100 text-slate-400'}`}>
        <Icon size={13} />
      </div>
      <div>
        <p className="text-[11px] font-black text-slate-900 uppercase">{label}</p>
        <p className="text-[9px] font-bold text-slate-500">{value}</p>
        <p className="text-[8px] text-slate-400">{new Date(date).toLocaleDateString()}</p>
      </div>
    </div>
  )
}

function StatRow({ label, value, valueClass }: { label: string; value: string; valueClass?: string }) {
  return (
    <div className="flex items-center justify-between">
      <span className="text-[9px] font-bold text-slate-400 uppercase tracking-wider">{label}</span>
      <span className={`text-xs font-black ${valueClass || 'text-slate-900'}`}>{value}</span>
    </div>
  )
}

'use client'

import Link from 'next/link'
import { ImageIcon } from 'lucide-react'
import { INSPECTION_STATUSES } from '@/lib/store-ops/constants'

interface ShelfInspectionCardProps {
  id: string
  section_name: string | null
  status: string
  notes: string | null
  created_at: string
  employee_name: string | null
  images: { url: string }[]
  basePath: string
}

const statusStyles: Record<string, { bg: string; text: string; label: string }> = {
  good: { bg: 'bg-emerald-50 border-emerald-100', text: 'text-emerald-600', label: 'Good' },
  needs_restock: { bg: 'bg-amber-50 border-amber-100', text: 'text-amber-600', label: 'Needs Restock' },
  dirty: { bg: 'bg-slate-50 border-slate-200', text: 'text-slate-600', label: 'Dirty' },
  wrong_display: { bg: 'bg-orange-50 border-orange-100', text: 'text-orange-600', label: 'Wrong Display' },
  missing_tester: { bg: 'bg-purple-50 border-purple-100', text: 'text-purple-600', label: 'Missing Tester' },
  missing_price_tag: { bg: 'bg-rose-50 border-rose-100', text: 'text-rose-600', label: 'Missing Price Tag' },
  damaged_display: { bg: 'bg-red-50 border-red-100', text: 'text-red-600', label: 'Damaged Display' },
}

export default function ShelfInspectionCard({
  id, section_name, status, notes, created_at, employee_name, images, basePath
}: ShelfInspectionCardProps) {
  const style = statusStyles[status] || { bg: 'bg-slate-50 border-slate-200', text: 'text-slate-600', label: status }

