    <Link
      href={`${basePath}/${id}`}
      className="block p-5 bg-white border border-slate-100 rounded-2xl hover:border-slate-300 hover:shadow-sm transition-all active:scale-[0.98]"
    >
      <div className="flex items-start justify-between gap-4">
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            <span className={`px-2 py-0.5 rounded-full text-[8px] font-black uppercase tracking-wider ${style.bg} ${style.text} border`}>
              {style.label}
            </span>
          </div>
          <h3 className="text-sm font-black text-slate-900 uppercase truncate">{section_name || 'Unknown Section'}</h3>
          {notes && (
            <p className="text-[10px] font-bold text-slate-500 mt-1 line-clamp-2">{notes}</p>
          )}
          <div className="flex items-center gap-3 mt-2 text-[9px] font-bold text-slate-400">
            <span>{new Date(created_at).toLocaleDateString()}</span>
            {employee_name && <span>by {employee_name}</span>}
          </div>
        </div>
        {images.length > 0 && (
          <div className="shrink-0">
            {images[0] ? (
              <div className="w-16 h-16 rounded-xl overflow-hidden bg-slate-100">
                <img src={images[0].url} alt="" className="w-full h-full object-cover" />
              </div>
            ) : (
              <div className="w-16 h-16 rounded-xl bg-slate-100 flex items-center justify-center">
                <ImageIcon size={20} className="text-slate-300" />
              </div>
            )}
          </div>
        )}
      </div>
    </Link>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { createClient } from '@/lib/supabase/client'
import { toast } from 'sonner'
import {
  ArrowLeft, Check, Trash2, Send, X,
  ImageIcon, Loader2, User, Calendar, MessageSquare
} from 'lucide-react'
import {
  approveShelfInspection, deleteShelfInspection,
  addInspectionComment
} from '@/app/actions/store-ops/shelf-inspection'
import type { ShelfInspectionWithRelations } from '@/lib/store-ops/types'
import { canManageApprovals, canDelete } from '@/lib/store-ops/permissions'
import { INSPECTION_STATUSES } from '@/lib/store-ops/constants'

interface ShelfInspectionDetailProps {
  inspection: ShelfInspectionWithRelations
  userRole: string | null
  basePath: string
}

const statusStyles: Record<string, { bg: string; text: string; label: string }> = {
  good: { bg: 'bg-emerald-50 border-emerald-100', text: 'text-emerald-600', label: 'Good' },
  needs_restock: { bg: 'bg-amber-50 border-amber-100', text: 'text-amber-600', label: 'Needs Restock' },
  dirty: { bg: 'bg-slate-50 border-slate-200', text: 'text-slate-600', label: 'Dirty' },
  wrong_display: { bg: 'bg-orange-50 border-orange-100', text: 'text-orange-600', label: 'Wrong Display' },
  missing_tester: { bg: 'bg-purple-50 border-purple-100', text: 'text-purple-600', label: 'Missing Tester' },
  missing_price_tag: { bg: 'bg-rose-50 border-rose-100', text: 'text-rose-600', label: 'Missing Price Tag' },
  damaged_display: { bg: 'bg-red-50 border-red-100', text: 'text-red-600', label: 'Damaged Display' },
}

export default function ShelfInspectionDetail({ inspection, userRole, basePath }: ShelfInspectionDetailProps) {
  const router = useRouter()
  const supabase = createClient()

  const [currentInspection, setCurrentInspection] = useState(inspection)
  const [comment, setComment] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [selectedImage, setSelectedImage] = useState<string | null>(null)

  const style = statusStyles[currentInspection.status] || statusStyles.good
  const isManager = canManageApprovals(userRole as 'admin' | 'manager' | 'employee' | null)
  const isAdmin = canDelete(userRole as 'admin' | 'manager' | 'employee' | null)
  const isReviewed = !!currentInspection.reviewed_by

  useEffect(() => {
    const channel = supabase.channel(`shelf_inspection_${inspection.id}`)
      .on('postgres_changes',
        { event: '*', schema: 'public', table: 'shelf_inspections', filter: `id=eq.${inspection.id}` },
        (payload) => {
          if (payload.new) setCurrentInspection(prev => ({ ...prev, ...payload.new as any }))
        }
      )
      .on('postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'inspection_comments', filter: `inspection_id=eq.${inspection.id}` },
        async () => {
          const { data } = await supabase
            .from('inspection_comments')
            .select('*, profiles:created_by(full_name)')
            .eq('inspection_id', inspection.id)
            .order('created_at', { ascending: true })
          if (data) {
            setCurrentInspection(prev => ({ ...prev, inspection_comments: data as any }))
          }
        }
      )
      .subscribe()

    return () => { supabase.removeChannel(channel) }
  }, [inspection.id, supabase])

  const handleApprove = async () => {
    const result = await approveShelfInspection(currentInspection.id)
    if (result.error) toast.error(result.error)
    else {
      toast.success('Inspection approved')
      setCurrentInspection(prev => ({ ...prev, reviewed_by: 'approved', reviewed_at: new Date().toISOString() }))
    }
  }

  const handleDelete = async () => {
    if (!confirm('Delete this inspection permanently?')) return
    const result = await deleteShelfInspection(currentInspection.id)
    if (result.error) toast.error(result.error)
    else {
      toast.success('Inspection deleted')
      router.push(basePath)
    }
  }

  const handleAddComment = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!comment.trim()) return
    setSubmitting(true)
    const result = await addInspectionComment(currentInspection.id, comment.trim())
    if (result.error) {
      toast.error(result.error)
    } else {
      setComment('')
    }
    setSubmitting(false)
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button
            onClick={() => router.back()}
            className="p-2 rounded-xl bg-slate-100 text-slate-500 hover:bg-slate-200 transition-colors"
          >
            <ArrowLeft size={18} />
          </button>
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-black text-slate-900 uppercase tracking-tight">
                {currentInspection.store_sections?.name || 'Unknown Section'}
              </h1>
              <span className={`px-2.5 py-1 rounded-full text-[8px] font-black uppercase tracking-wider border ${style.bg} ${style.text}`}>
                {style.label}
              </span>
            </div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
              Shelf Inspection
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {!isReviewed && isManager && (
            <button onClick={handleApprove} className="flex items-center gap-1.5 px-4 py-2.5 bg-emerald-600 text-white rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-emerald-700 transition-all">
              <Check size={13} /> Approve
            </button>
          )}
          {isAdmin && (
            <button onClick={handleDelete} className="flex items-center gap-1.5 px-4 py-2.5 bg-white border border-rose-200 text-rose-500 rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-rose-50 transition-all">
              <Trash2 size={13} /> Delete
            </button>
          )}
        </div>
      </div>

      {/* Content Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Details */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white border border-slate-200 rounded-2xl p-6 space-y-5">
            <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Inspection Details</h2>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
              <DetailItem icon={MessageSquare} label="Section" value={currentInspection.store_sections?.name || '—'} />
              <DetailItem icon={User} label="Employee" value={currentInspection.profiles?.full_name || 'Unknown'} />
              <DetailItem icon={Calendar} label="Date" value={new Date(currentInspection.created_at).toLocaleDateString()} />
              <DetailItem icon={Check} label="Status" value={style.label} />
              <DetailItem icon={Check} label="Reviewed" value={isReviewed ? 'Yes' : 'No'} />
            </div>
            {currentInspection.notes && (
              <div className="pt-4 border-t border-slate-100">
                <h3 className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2">Notes</h3>
                <p className="text-sm font-bold text-slate-700 leading-relaxed">{currentInspection.notes}</p>
              </div>
            )}
          </div>

          {/* Image Gallery */}
          <div className="bg-white border border-slate-200 rounded-2xl p-6">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                Photos ({currentInspection.inspection_images?.length || 0})
              </h2>
            </div>
            {currentInspection.inspection_images && currentInspection.inspection_images.length > 0 ? (
              <div className="grid grid-cols-3 md:grid-cols-4 gap-3">
                {currentInspection.inspection_images.map((img) => (
                  <div key={img.id} className="relative group">
                    <button
                      onClick={() => setSelectedImage(img.url)}
                      className="aspect-square rounded-xl overflow-hidden bg-slate-100 w-full"
                    >
                      <img src={img.url} alt="" className="w-full h-full object-cover hover:scale-105 transition-transform" />
                    </button>
                  </div>
                ))}
              </div>
            ) : (
              <div className="py-10 text-center border-2 border-dashed border-slate-100 rounded-xl">
                <ImageIcon size={28} className="mx-auto text-slate-200" />
                <p className="text-[9px] font-black text-slate-300 uppercase tracking-widest mt-2">No photos</p>
              </div>
            )}
          </div>

          {/* Comments */}
          <div className="bg-white border border-slate-200 rounded-2xl p-6">
            <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">
              Comments ({currentInspection.inspection_comments?.length || 0})
            </h2>

            <div className="space-y-4 mb-6 max-h-[400px] overflow-y-auto">
              {currentInspection.inspection_comments && currentInspection.inspection_comments.length > 0 ? (
                currentInspection.inspection_comments.map((c) => (
                  <div key={c.id} className="flex gap-3 p-3 bg-slate-50 rounded-xl">
                    <div className="w-8 h-8 rounded-full bg-slate-900 text-white flex items-center justify-center text-[8px] font-black shrink-0 uppercase">
                      {(c as any).profiles?.full_name?.charAt(0) || '?'}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <span className="text-[10px] font-black text-slate-900 uppercase">
                          {(c as any).profiles?.full_name || 'Unknown'}
                        </span>
                        <span className="text-[8px] font-bold text-slate-400">
                          {new Date(c.created_at).toLocaleDateString()}
                        </span>
                      </div>
                      <p className="text-xs font-bold text-slate-600 mt-0.5">{c.comment}</p>
                    </div>
                  </div>
                ))
              ) : (
                <p className="text-[9px] font-bold text-slate-400 text-center py-6">No comments yet</p>
              )}
            </div>

            <form onSubmit={handleAddComment} className="flex gap-3">
              <input
                value={comment}
                onChange={(e) => setComment(e.target.value)}
                placeholder="Add a comment..."
                className="flex-1 px-4 py-2.5 rounded-xl border border-slate-200 text-sm font-bold text-slate-900 outline-none focus:ring-2 focus:ring-slate-900/20 transition-all"
              />
              <button
                type="submit"
                disabled={!comment.trim() || submitting}
                className="px-4 py-2.5 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all disabled:opacity-50 flex items-center gap-2"
              >
                {submitting ? <Loader2 size={14} className="animate-spin" /> : <Send size={14} />}
                Send
              </button>
            </form>
          </div>
        </div>

        {/* Sidebar */}
        <div className="space-y-6">
          {/* Status Timeline */}
          <div className="bg-white border border-slate-200 rounded-2xl p-6">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Timeline</h3>
            <div className="space-y-4">
              <TimelineItem
                icon={User}
                label="Inspected by"
                value={currentInspection.profiles?.full_name || 'Unknown'}
                date={currentInspection.created_at}
                active
              />
              {isReviewed && (
                <TimelineItem
                  icon={Check}
                  label="Reviewed"
                  value="Approved"
                  date={currentInspection.reviewed_at || ''}
                  active
                />
              )}
            </div>
          </div>

          {/* Quick Info */}
          <div className="bg-white border border-slate-200 rounded-2xl p-6">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Quick Info</h3>
            <div className="space-y-3">
              <StatRow label="Section" value={currentInspection.store_sections?.name || '—'} />
              <StatRow label="Status" value={style.label} valueClass={style.text} />
              <StatRow label="Reviewed" value={isReviewed ? 'Yes' : 'No'} />
            </div>
          </div>
        </div>
      </div>

      {/* Image Fullscreen Modal */}
      {selectedImage && (
        <div
          className="fixed inset-0 z-50 bg-black/90 flex items-center justify-center p-4"
          onClick={() => setSelectedImage(null)}
        >
          <button
            onClick={() => setSelectedImage(null)}
            className="absolute top-6 right-6 p-2 bg-white/10 rounded-full text-white hover:bg-white/20 transition-colors"
          >
            <X size={24} />
          </button>
          <img
            src={selectedImage}
            alt="Full size"
            className="max-w-full max-h-[90vh] object-contain rounded-2xl"
            onClick={(e) => e.stopPropagation()}
          />
        </div>
      )}
    </div>
  )
}

function DetailItem({ icon: Icon, label, value }: { icon: any; label: string; value: string }) {
  return (
    <div className="space-y-1">
      <div className="flex items-center gap-1.5 text-[9px] font-bold text-slate-400 uppercase tracking-wider">
        <Icon size={11} />
        {label}
      </div>
      <p className="text-sm font-black text-slate-900">{value}</p>
    </div>
  )
}

function TimelineItem({ icon: Icon, label, value, date, active }: { icon: any; label: string; value: string; date: string; active?: boolean }) {
  return (
    <div className="flex gap-3">
      <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${active ? 'bg-slate-900 text-white' : 'bg-slate-100 text-slate-400'}`}>
        <Icon size={13} />
      </div>
      <div>
        <p className="text-[11px] font-black text-slate-900 uppercase">{label}</p>
        <p className="text-[9px] font-bold text-slate-500">{value}</p>
        <p className="text-[8px] text-slate-400">{new Date(date).toLocaleDateString()}</p>
      </div>
    </div>
  )
}

function StatRow({ label, value, valueClass }: { label: string; value: string; valueClass?: string }) {
  return (
    <div className="flex items-center justify-between">
      <span className="text-[9px] font-bold text-slate-400 uppercase tracking-wider">{label}</span>
      <span className={`text-xs font-black ${valueClass || 'text-slate-900'}`}>{value}</span>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { createClient } from '@/lib/supabase/client'
import { Search, Filter, Plus, X, Loader2, ImageIcon } from 'lucide-react'
import { INSPECTION_STATUSES } from '@/lib/store-ops/constants'
import type { ShelfInspectionWithRelations } from '@/lib/store-ops/types'
import ShelfInspectionCard from './ShelfInspectionCard'

interface ShelfInspectionListProps {
  initialData: ShelfInspectionWithRelations[]
  total: number
  page: number
  totalPages: number
  basePath: string
  canCreate: boolean
  sections?: { id: string; name: string }[]
}

const statusStyles: Record<string, { bg: string; text: string }> = {
  good: { bg: 'bg-emerald-50', text: 'text-emerald-600' },
  needs_restock: { bg: 'bg-amber-50', text: 'text-amber-600' },
  dirty: { bg: 'bg-slate-100', text: 'text-slate-600' },
  wrong_display: { bg: 'bg-orange-50', text: 'text-orange-600' },
  missing_tester: { bg: 'bg-purple-50', text: 'text-purple-600' },
  missing_price_tag: { bg: 'bg-rose-50', text: 'text-rose-600' },
  damaged_display: { bg: 'bg-red-50', text: 'text-red-600' },
}

const statusLabels: Record<string, string> = {
  good: 'Good',
  needs_restock: 'Needs Restock',
  dirty: 'Dirty',
  wrong_display: 'Wrong Display',
  missing_tester: 'Missing Tester',
  missing_price_tag: 'Missing Price Tag',
  damaged_display: 'Damaged Display',
}

export default function ShelfInspectionList({
  initialData, total, page: initialPage, totalPages: initialTotalPages, basePath, canCreate, sections
}: ShelfInspectionListProps) {
  const router = useRouter()
  const supabase = createClient()

  const [data, setData] = useState(initialData)
  const [totalCount, setTotalCount] = useState(total)
  const [currentPage, setCurrentPage] = useState(initialPage)
  const [totalPages, setTotalPages] = useState(initialTotalPages)
  const [loading, setLoading] = useState(false)

  const [search, setSearch] = useState('')
  const [statusFilter, setStatusFilter] = useState('')
  const [sectionFilter, setSectionFilter] = useState('')
  const [showFilters, setShowFilters] = useState(false)

  const fetchData = useCallback(async (pageNum: number) => {
    setLoading(true)
    let query = supabase
      .from('shelf_inspections')
      .select(`
        *,
        store_sections(name, description),
        profiles:employee_id(full_name, email),
        inspection_images(*),
        inspection_comments(*, profiles:created_by(full_name))
      `, { count: 'exact' })

    if (search) {
      query = query.or(`notes.ilike.%${search}%,store_sections.name.ilike.%${search}%`)
    }
    if (statusFilter) query = query.eq('status', statusFilter)
    if (sectionFilter) query = query.eq('section_id', sectionFilter)

    const limit = 20
    const offset = (pageNum - 1) * limit
    query = query.order('created_at', { ascending: false }).range(offset, offset + limit - 1)

    const { data: results, count } = await query
    if (results) setData(results as unknown as ShelfInspectionWithRelations[])
    if (count !== null) {
      setTotalCount(count)
      setTotalPages(Math.ceil(count / limit))
    }
    setLoading(false)
  }, [search, statusFilter, sectionFilter, supabase])

  useEffect(() => {
    fetchData(currentPage)
  }, [currentPage, fetchData])

  useEffect(() => {
    const channel = supabase.channel('shelf_inspections_realtime')
      .on('postgres_changes',
        { event: '*', schema: 'public', table: 'shelf_inspections' },
        () => { fetchData(currentPage) }
      )
      .on('postgres_changes',
        { event: '*', schema: 'public', table: 'inspection_images' },
        () => { fetchData(currentPage) }
      )
      .on('postgres_changes',
        { event: '*', schema: 'public', table: 'inspection_comments' },
        () => { fetchData(currentPage) }
      )
      .subscribe()

    return () => { supabase.removeChannel(channel) }
  }, [currentPage, fetchData, supabase])

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault()
    setCurrentPage(1)
    fetchData(1)
  }

  const clearFilters = () => {
    setSearch('')
    setStatusFilter('')
    setSectionFilter('')
    setCurrentPage(1)
  }

  const hasFilters = search || statusFilter || sectionFilter

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-black text-slate-900 uppercase tracking-tight">Shelf Inspections</h1>
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
            {totalCount} inspection{totalCount !== 1 ? 's' : ''}
          </p>
        </div>
        {canCreate && (
          <button
            onClick={() => router.push(`${basePath}/new`)}
            className="flex items-center gap-2 px-5 py-3 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all"
          >
            <Plus size={14} />
            New Inspection
          </button>
        )}
      </div>

      {/* Search & Filters */}
      <div className="flex items-center gap-3">
        <form onSubmit={handleSearch} className="flex-1 relative">
          <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
          <input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search by notes or section..."
            className="w-full pl-11 pr-4 py-3 rounded-xl border border-slate-200 bg-white text-sm font-bold text-slate-900 outline-none focus:ring-2 focus:ring-slate-900/20 transition-all"
          />
        </form>
        <button
          onClick={() => setShowFilters(!showFilters)}
          className={`p-3 rounded-xl border transition-all ${showFilters || hasFilters ? 'bg-slate-900 text-white border-slate-900' : 'bg-white text-slate-400 border-slate-200 hover:border-slate-300'}`}
        >
          <Filter size={18} />
        </button>
      </div>

      {/* Filter Panel */}
      {showFilters && (
        <div className="bg-slate-900 p-5 rounded-2xl space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Filters</h3>
            {hasFilters && (
              <button onClick={clearFilters} className="flex items-center gap-1 text-[9px] font-bold text-slate-400 hover:text-white transition-colors">
                <X size={12} /> Clear
              </button>
            )}
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            <div className="space-y-1">
              <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest ml-1">Status</label>
              <select
                value={statusFilter}
                onChange={(e) => { setStatusFilter(e.target.value); setCurrentPage(1) }}
                className="w-full bg-slate-800 border-none rounded-xl px-3 py-2.5 text-[11px] font-bold text-white outline-none"
              >
                <option value="">All Statuses</option>
                {INSPECTION_STATUSES.map(s => (
                  <option key={s} value={s}>{statusLabels[s] || s}</option>
                ))}
              </select>
            </div>
            <div className="space-y-1">
              <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest ml-1">Section</label>
              <select
                value={sectionFilter}
                onChange={(e) => { setSectionFilter(e.target.value); setCurrentPage(1) }}
                className="w-full bg-slate-800 border-none rounded-xl px-3 py-2.5 text-[11px] font-bold text-white outline-none"
              >
                <option value="">All Sections</option>
                {sections?.map(s => (
                  <option key={s.id} value={s.id}>{s.name}</option>
                ))}
              </select>
            </div>
          </div>
        </div>
      )}

      {/* Desktop Table */}
      <div className="hidden md:block bg-white border border-slate-200 rounded-2xl overflow-hidden">
        <table className="w-full">
          <thead>
            <tr className="border-b border-slate-100">
              <th className="text-left px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Section</th>
              <th className="text-left px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Status</th>
              <th className="text-left px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Notes</th>
              <th className="text-left px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Employee</th>
              <th className="text-left px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Date</th>
              <th className="text-left px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Review</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr>
                <td colSpan={6} className="py-20 text-center">
                  <Loader2 size={20} className="animate-spin mx-auto text-slate-300" />
                </td>
              </tr>
            ) : data.length === 0 ? (
              <tr>
                <td colSpan={6} className="py-20 text-center">
                  <div className="flex flex-col items-center gap-2">
                    <ImageIcon size={32} className="text-slate-200" />
                    <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">No inspections found</p>
                  </div>
                </td>
              </tr>
            ) : (
              data.map(item => {
                const st = statusStyles[item.status] || statusStyles.good
                return (
                  <tr
                    key={item.id}
                    onClick={() => router.push(`${basePath}/${item.id}`)}
                    className="border-b border-slate-50 hover:bg-slate-50 cursor-pointer transition-colors"
                  >
                    <td className="px-5 py-4">
                      <div className="flex items-center gap-3">
                        {item.inspection_images?.[0] ? (
                          <div className="w-10 h-10 rounded-lg overflow-hidden bg-slate-100 shrink-0">
                            <img src={item.inspection_images[0].url} alt="" className="w-full h-full object-cover" />
                          </div>
                        ) : (
                          <div className="w-10 h-10 rounded-lg bg-slate-100 flex items-center justify-center shrink-0">
                            <ImageIcon size={16} className="text-slate-300" />
                          </div>
                        )}
                        <p className="text-xs font-black text-slate-900 uppercase">{item.store_sections?.name || 'Unknown'}</p>
                      </div>
                    </td>
                    <td className="px-5 py-4">
                      <span className={`px-2 py-0.5 rounded-full text-[8px] font-black uppercase tracking-wider ${st.bg} ${st.text}`}>
                        {statusLabels[item.status] || item.status}
                      </span>
                    </td>
                    <td className="px-5 py-4 text-[10px] font-bold text-slate-500 max-w-[200px] truncate">
                      {item.notes || '—'}
                    </td>
                    <td className="px-5 py-4 text-[10px] font-bold text-slate-500">
                      {item.profiles?.full_name || 'Unknown'}
                    </td>
                    <td className="px-5 py-4 text-[10px] font-bold text-slate-500">
                      {new Date(item.created_at).toLocaleDateString()}
                    </td>
                    <td className="px-5 py-4">
                      {item.reviewed_by ? (
                        <span className="text-[8px] font-black text-emerald-600 uppercase tracking-wider">Reviewed</span>
                      ) : (
                        <span className="text-[8px] font-black text-amber-600 uppercase tracking-wider">Pending</span>
                      )}
                    </td>
                  </tr>
                )
              })
            )}
          </tbody>
        </table>
      </div>

      {/* Mobile Cards */}
      <div className="md:hidden space-y-3">
        {loading ? (
          <div className="py-20 flex justify-center">
            <Loader2 size={24} className="animate-spin text-slate-300" />
          </div>
        ) : data.length === 0 ? (
          <div className="py-20 text-center">
            <div className="flex flex-col items-center gap-2">
              <ImageIcon size={40} className="text-slate-200" />
              <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">No inspections found</p>
            </div>
          </div>
        ) : (
          data.map(item => (
            <ShelfInspectionCard
              key={item.id}
              id={item.id}
              section_name={item.store_sections?.name || null}
              status={item.status}
              notes={item.notes}
              created_at={item.created_at}
              employee_name={item.profiles?.full_name ?? null}
              images={item.inspection_images || []}
              basePath={basePath}
            />
          ))
        )}
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-center gap-2">
          <button
            onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
            disabled={currentPage === 1}
            className="px-4 py-2 rounded-xl bg-white border border-slate-200 text-[10px] font-black uppercase tracking-widest text-slate-500 hover:bg-slate-50 disabled:opacity-30 transition-all"
          >
            Prev
          </button>
          {Array.from({ length: totalPages }, (_, i) => i + 1)
            .filter(p => p === 1 || p === totalPages || Math.abs(p - currentPage) <= 1)
            .map((p, idx, arr) => (
              <span key={p} className="flex items-center gap-1">
                {idx > 0 && arr[idx - 1] !== p - 1 && (
                  <span className="text-slate-300 text-[10px] font-bold px-1">...</span>
                )}
                <button
                  onClick={() => setCurrentPage(p)}
                  className={`w-9 h-9 rounded-xl text-[10px] font-black transition-all ${
                    currentPage === p
                      ? 'bg-slate-900 text-white'
                      : 'bg-white border border-slate-200 text-slate-500 hover:bg-slate-50'
                  }`}
                >
                  {p}
                </button>
              </span>
            ))}
          <button
            onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
            disabled={currentPage === totalPages}
            className="px-4 py-2 rounded-xl bg-white border border-slate-200 text-[10px] font-black uppercase tracking-widest text-slate-500 hover:bg-slate-50 disabled:opacity-30 transition-all"
          >
            Next
          </button>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect, useRef } from 'react'
import { useRouter } from 'next/navigation'
import { createClient } from '@/lib/supabase/client'
import { toast } from 'sonner'
import {
  ArrowLeft, Check, X, Trash2, Send, Upload,
  ImageIcon, Loader2, User, Calendar, Tag, Clock,
  RefreshCw, Paperclip, FileText
} from 'lucide-react'
import {
  completeTask, cancelTask, deleteTask,
  addTaskComment, uploadTaskAttachment, saveTaskAttachment, deleteTaskAttachment
} from '@/app/actions/store-ops/tasks'
import type { TaskWithRelations } from '@/lib/store-ops/types'
import { canManageApprovals, canDelete } from '@/lib/store-ops/permissions'

interface TaskDetailProps {
  task: TaskWithRelations
  userRole: string | null
  basePath: string
}

const priorityStyles: Record<string, { bg: string; text: string; label: string }> = {
  urgent: { bg: 'bg-rose-50 border-rose-200', text: 'text-rose-600', label: 'Urgent' },
  high: { bg: 'bg-amber-50 border-amber-100', text: 'text-amber-600', label: 'High' },
  medium: { bg: 'bg-blue-50 border-blue-100', text: 'text-blue-600', label: 'Medium' },
  low: { bg: 'bg-slate-100 border-slate-200', text: 'text-slate-500', label: 'Low' },
}

const statusStyles: Record<string, { bg: string; text: string; label: string }> = {
  pending: { bg: 'bg-slate-100 border-slate-200', text: 'text-slate-500', label: 'Pending' },
  in_progress: { bg: 'bg-blue-50 border-blue-100', text: 'text-blue-600', label: 'In Progress' },
  completed: { bg: 'bg-emerald-50 border-emerald-100', text: 'text-emerald-600', label: 'Completed' },
  cancelled: { bg: 'bg-rose-50 border-rose-100', text: 'text-rose-500', label: 'Cancelled' },
}

export default function TaskDetail({ task, userRole, basePath }: TaskDetailProps) {
  const router = useRouter()
  const supabase = createClient()
  const fileInputRef = useRef<HTMLInputElement>(null)

  const [currentTask, setCurrentTask] = useState(task)
  const [comment, setComment] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [uploading, setUploading] = useState(false)

  const ps = priorityStyles[currentTask.priority] || priorityStyles.medium
  const ss = statusStyles[currentTask.status] || statusStyles.pending
  const isManager = canManageApprovals(userRole as 'admin' | 'manager' | 'employee' | null)
  const isAdmin = canDelete(userRole as 'admin' | 'manager' | 'employee' | null)

  useEffect(() => {
    const channel = supabase.channel(`task_${task.id}`)
      .on('postgres_changes',
        { event: '*', schema: 'public', table: 'tasks', filter: `id=eq.${task.id}` },
        (payload) => {
          if (payload.new) setCurrentTask(prev => ({ ...prev, ...payload.new as any }))
        }
      )
      .on('postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'task_comments', filter: `task_id=eq.${task.id}` },
        async () => {
          const { data } = await supabase
            .from('task_comments')
            .select('*, profiles:created_by(full_name)')
            .eq('task_id', task.id)
            .order('created_at', { ascending: true })
          if (data) {
            setCurrentTask(prev => ({ ...prev, task_comments: data as any }))
          }
        }
      )
      .on('postgres_changes',
        { event: '*', schema: 'public', table: 'task_attachments', filter: `task_id=eq.${task.id}` },
        async () => {
          const { data } = await supabase
            .from('task_attachments')
            .select('*')
            .eq('task_id', task.id)
            .order('created_at', { ascending: true })
          if (data) {
            setCurrentTask(prev => ({ ...prev, task_attachments: data as any }))
          }
        }
      )
      .subscribe()

    return () => { supabase.removeChannel(channel) }
  }, [task.id, supabase])

  const handleToggleComplete = async () => {
    const result = await completeTask(currentTask.id)
    if (result.error) toast.error(result.error)
    else {
      toast.success(result.data?.status === 'completed' ? 'Task completed' : 'Task reopened')
    }
  }

  const handleCancel = async () => {
    const result = await cancelTask(currentTask.id)
    if (result.error) toast.error(result.error)
    else toast.success('Task cancelled')
  }

  const handleDelete = async () => {
    if (!confirm('Delete this task permanently?')) return
    const result = await deleteTask(currentTask.id)
    if (result.error) toast.error(result.error)
    else {
      toast.success('Task deleted')
      router.push(basePath)
    }
  }

  const handleAddComment = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!comment.trim()) return
    setSubmitting(true)
    const result = await addTaskComment(currentTask.id, comment.trim())
    if (result.error) {
      toast.error(result.error)
    } else {
      setComment('')
    }
    setSubmitting(false)
  }

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files
    if (!files || files.length === 0) return

    setUploading(true)
    try {
      for (const file of Array.from(files)) {
        const formData = new FormData()
        formData.append('file', file)

        const uploadResult = await uploadTaskAttachment(formData)
        if (uploadResult.success && uploadResult.url) {
          const saveResult = await saveTaskAttachment(currentTask.id, uploadResult.url)
          if (saveResult.error) {
            toast.error(saveResult.error)
          } else {
            const { data } = await supabase
              .from('task_attachments')
              .select('*')
              .eq('task_id', currentTask.id)
              .order('created_at', { ascending: true })
            if (data) {
              setCurrentTask(prev => ({ ...prev, task_attachments: data as any }))
            }
          }
        } else {
          toast.error(uploadResult.error || 'Upload failed')
        }
      }
    } finally {
      setUploading(false)
      if (fileInputRef.current) fileInputRef.current.value = ''
    }
  }

  const handleDeleteAttachment = async (attachmentId: string) => {
    const result = await deleteTaskAttachment(attachmentId)
    if (result.error) toast.error(result.error)
    else {
      toast.success('Attachment removed')
      setCurrentTask(prev => ({
        ...prev,
        task_attachments: prev.task_attachments.filter(a => a.id !== attachmentId)
      }))
    }
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button
            onClick={() => router.back()}
            className="p-2 rounded-xl bg-slate-100 text-slate-500 hover:bg-slate-200 transition-colors"
          >
            <ArrowLeft size={18} />
          </button>
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-black text-slate-900 uppercase tracking-tight">
                {currentTask.title}
              </h1>
              <span className={`px-2.5 py-1 rounded-full text-[8px] font-black uppercase tracking-wider border ${ps.bg} ${ps.text}`}>
                {ps.label}
              </span>
              <span className={`px-2.5 py-1 rounded-full text-[8px] font-black uppercase tracking-wider border ${ss.bg} ${ss.text}`}>
                {ss.label}
              </span>
            </div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
              {currentTask.category || 'General'}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {currentTask.status !== 'completed' && currentTask.status !== 'cancelled' && (
            <button onClick={handleToggleComplete} className="flex items-center gap-1.5 px-4 py-2.5 bg-emerald-600 text-white rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-emerald-700 transition-all">
              <Check size={13} /> Complete
            </button>
          )}
          {currentTask.status === 'completed' && (
            <button onClick={handleToggleComplete} className="flex items-center gap-1.5 px-4 py-2.5 bg-slate-600 text-white rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-slate-700 transition-all">
              <RefreshCw size={13} /> Reopen
            </button>
          )}
          {currentTask.status === 'pending' && isManager && (
            <button onClick={handleCancel} className="flex items-center gap-1.5 px-4 py-2.5 bg-white border border-slate-200 text-slate-500 rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-slate-50 transition-all">
              <X size={13} /> Cancel
            </button>
          )}
          {isAdmin && (
            <button onClick={handleDelete} className="flex items-center gap-1.5 px-4 py-2.5 bg-white border border-rose-200 text-rose-500 rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-rose-50 transition-all">
              <Trash2 size={13} /> Delete
            </button>
          )}
        </div>
      </div>

      {/* Content Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Details */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white border border-slate-200 rounded-2xl p-6 space-y-5">
            <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Task Details</h2>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
              <DetailItem icon={Tag} label="Priority" value={ps.label} />
              <DetailItem icon={Tag} label="Status" value={ss.label} />
              <DetailItem icon={Tag} label="Category" value={currentTask.category ? currentTask.category.charAt(0).toUpperCase() + currentTask.category.slice(1) : '—'} />
              <DetailItem icon={User} label="Assignee" value={currentTask.assigned_to_profile?.full_name || 'Unassigned'} />
              <DetailItem icon={User} label="Assigned By" value={currentTask.assigned_by_profile?.full_name || 'Unknown'} />
              <DetailItem icon={Calendar} label="Due Date" value={currentTask.due_date ? new Date(currentTask.due_date).toLocaleDateString() : '—'} />
              <DetailItem icon={RefreshCw} label="Recurring" value={currentTask.is_recurring ? 'Yes' : 'No'} />
              {currentTask.is_recurring && currentTask.recurrence_rule && (
                <DetailItem icon={Clock} label="Recurrence" value={currentTask.recurrence_rule} />
              )}
              <DetailItem icon={Calendar} label="Created" value={new Date(currentTask.created_at).toLocaleDateString()} />
            </div>
            {currentTask.description && (
              <div className="pt-4 border-t border-slate-100">
                <h3 className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2">Description</h3>
                <p className="text-sm font-bold text-slate-700 leading-relaxed whitespace-pre-wrap">{currentTask.description}</p>
              </div>
            )}
          </div>

          {/* Attachments */}
          <div className="bg-white border border-slate-200 rounded-2xl p-6">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                Attachments ({currentTask.task_attachments?.length || 0})
              </h2>
              <button
                type="button"
                onClick={() => fileInputRef.current?.click()}
                disabled={uploading}
                className="flex items-center gap-2 px-4 py-2 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all disabled:opacity-50"
              >
                {uploading ? <Loader2 size={14} className="animate-spin" /> : <Upload size={14} />}
                {uploading ? 'Uploading...' : 'Upload'}
              </button>
              <input
                ref={fileInputRef}
                type="file"
                accept="image/*,.pdf,.doc,.docx"
                multiple
                onChange={handleUpload}
                className="hidden"
              />
            </div>
            {currentTask.task_attachments && currentTask.task_attachments.length > 0 ? (
              <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                {currentTask.task_attachments.map((att) => {
                  const isImage = att.url.match(/\.(jpg|jpeg|png|gif|webp)$/i)
                  return (
                    <div key={att.id} className="relative group">
                      {isImage ? (
                        <a
                          href={att.url}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="aspect-square rounded-xl overflow-hidden bg-slate-100 block"
                        >
                          <img src={att.url} alt="" className="w-full h-full object-cover hover:scale-105 transition-transform" />
                        </a>
                      ) : (
                        <a
                          href={att.url}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="aspect-square rounded-xl bg-slate-100 flex items-center justify-center hover:bg-slate-200 transition-colors"
                        >
                          <FileText size={24} className="text-slate-400" />
                        </a>
                      )}
                      {isAdmin && (
                        <button
                          onClick={() => handleDeleteAttachment(att.id)}
                          className="absolute top-1 right-1 p-1 bg-black/50 rounded-full text-white opacity-0 group-hover:opacity-100 transition-opacity"
                        >
                          <Trash2 size={10} />
                        </button>
                      )}
                    </div>
                  )
                })}
              </div>
            ) : (
              <div className="py-10 text-center border-2 border-dashed border-slate-100 rounded-xl">
                <Paperclip size={28} className="mx-auto text-slate-200" />
                <p className="text-[9px] font-black text-slate-300 uppercase tracking-widest mt-2">No attachments</p>
              </div>
            )}
          </div>

          {/* Comments */}
          <div className="bg-white border border-slate-200 rounded-2xl p-6">
            <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">
              Comments ({currentTask.task_comments?.length || 0})
            </h2>

            <div className="space-y-4 mb-6 max-h-[400px] overflow-y-auto">
              {currentTask.task_comments && currentTask.task_comments.length > 0 ? (
                currentTask.task_comments.map((c) => (
                  <div key={c.id} className="flex gap-3 p-3 bg-slate-50 rounded-xl">
                    <div className="w-8 h-8 rounded-full bg-slate-900 text-white flex items-center justify-center text-[8px] font-black shrink-0 uppercase">
                      {(c as any).profiles?.full_name?.charAt(0) || '?'}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <span className="text-[10px] font-black text-slate-900 uppercase">
                          {(c as any).profiles?.full_name || 'Unknown'}
                        </span>
                        <span className="text-[8px] font-bold text-slate-400">
                          {new Date(c.created_at).toLocaleDateString()}
                        </span>
                      </div>
                      <p className="text-xs font-bold text-slate-600 mt-0.5">{c.comment}</p>
                    </div>
                  </div>
                ))
              ) : (
                <p className="text-[9px] font-bold text-slate-400 text-center py-6">No comments yet</p>
              )}
            </div>

            <form onSubmit={handleAddComment} className="flex gap-3">
              <input
                value={comment}
                onChange={(e) => setComment(e.target.value)}
                placeholder="Add a comment..."
                className="flex-1 px-4 py-2.5 rounded-xl border border-slate-200 text-sm font-bold text-slate-900 outline-none focus:ring-2 focus:ring-slate-900/20 transition-all"
              />
              <button
                type="submit"
                disabled={!comment.trim() || submitting}
                className="px-4 py-2.5 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all disabled:opacity-50 flex items-center gap-2"
              >
                {submitting ? <Loader2 size={14} className="animate-spin" /> : <Send size={14} />}
                Send
              </button>
            </form>
          </div>
        </div>

        {/* Sidebar */}
        <div className="space-y-6">
          {/* Timeline */}
          <div className="bg-white border border-slate-200 rounded-2xl p-6">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Timeline</h3>
            <div className="space-y-4">
              <TimelineItem
                icon={User}
                label="Created By"
                value={currentTask.assigned_by_profile?.full_name || 'Unknown'}
                date={currentTask.created_at}
                active
              />
              {currentTask.assigned_to && (
                <TimelineItem
                  icon={User}
                  label="Assigned To"
                  value={currentTask.assigned_to_profile?.full_name || 'Unknown'}
                  date={currentTask.created_at}
                  active
                />
              )}
              {currentTask.status === 'completed' && (
                <TimelineItem
                  icon={Check}
                  label="Completed"
                  value="Task finished"
                  date={currentTask.updated_at}
                  active
                />
              )}
            </div>
          </div>

          {/* Quick Info */}
          <div className="bg-white border border-slate-200 rounded-2xl p-6">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Quick Info</h3>
            <div className="space-y-3">
              <StatRow label="Priority" value={ps.label} valueClass={ps.text} />
              <StatRow label="Status" value={ss.label} valueClass={ss.text} />
              <StatRow label="Category" value={currentTask.category ? currentTask.category.charAt(0).toUpperCase() + currentTask.category.slice(1) : 'General'} />
              <StatRow label="Comments" value={(currentTask.task_comments?.length || 0).toString()} />
              <StatRow label="Attachments" value={(currentTask.task_attachments?.length || 0).toString()} />
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

function DetailItem({ icon: Icon, label, value }: { icon: any; label: string; value: string }) {
  return (
    <div className="space-y-1">
      <div className="flex items-center gap-1.5 text-[9px] font-bold text-slate-400 uppercase tracking-wider">
        <Icon size={11} />
        {label}
      </div>
      <p className="text-sm font-black text-slate-900">{value}</p>
    </div>
  )
}

function TimelineItem({ icon: Icon, label, value, date, active }: { icon: any; label: string; value: string; date: string; active?: boolean }) {
  return (
    <div className="flex gap-3">
      <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${active ? 'bg-slate-900 text-white' : 'bg-slate-100 text-slate-400'}`}>
        <Icon size={13} />
      </div>
      <div>
        <p className="text-[11px] font-black text-slate-900 uppercase">{label}</p>
        <p className="text-[9px] font-bold text-slate-500">{value}</p>
        <p className="text-[8px] text-slate-400">{new Date(date).toLocaleDateString()}</p>
      </div>
    </div>
  )
}

function StatRow({ label, value, valueClass }: { label: string; value: string; valueClass?: string }) {
  return (
    <div className="flex items-center justify-between">
      <span className="text-[9px] font-bold text-slate-400 uppercase tracking-wider">{label}</span>
      <span className={`text-xs font-black ${valueClass || 'text-slate-900'}`}>{value}</span>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { Save, ArrowLeft, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import { TASK_PRIORITIES, TASK_CATEGORIES } from '@/lib/store-ops/constants'
import { createTask, updateTask, getEmployees } from '@/app/actions/store-ops/tasks'

interface TaskFormProps {
  initialData?: {
    id: string
    title: string
    description: string | null
    assigned_to: string | null
    priority: string
    due_date: string | null
    category: string | null
    is_recurring: boolean
    recurrence_rule: string | null
  }
  basePath: string
}

export default function TaskForm({ initialData, basePath }: TaskFormProps) {
  const router = useRouter()
  const isEditing = !!initialData
  const [saving, setSaving] = useState(false)
  const [errors, setErrors] = useState<Record<string, string>>({})
  const [employees, setEmployees] = useState<{ id: string; full_name: string | null }[]>([])

  const [form, setForm] = useState({
    title: initialData?.title || '',
    description: initialData?.description || '',
    assigned_to: initialData?.assigned_to || '',
    priority: initialData?.priority || 'medium',
    due_date: initialData?.due_date ? initialData.due_date.split('T')[0] : '',
    category: initialData?.category || 'general',
    is_recurring: initialData?.is_recurring || false,
    recurrence_rule: initialData?.recurrence_rule || '',
  })

  useEffect(() => {
    getEmployees().then(setEmployees)
  }, [])

  const validate = () => {
    const errs: Record<string, string> = {}
    if (!form.title.trim()) errs.title = 'Title is required'
    if (!form.priority) errs.priority = 'Priority is required'
    setErrors(errs)
    return Object.keys(errs).length === 0
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!validate()) return

    setSaving(true)
    try {
      const payload = {
        title: form.title.trim(),
        description: form.description.trim() || undefined,
        assigned_to: form.assigned_to || undefined,
        priority: form.priority,
        due_date: form.due_date ? new Date(form.due_date).toISOString() : undefined,
        category: form.category || undefined,
        is_recurring: form.is_recurring,
        recurrence_rule: form.is_recurring ? form.recurrence_rule.trim() || undefined : undefined,
      }

      const result = isEditing
        ? await updateTask(initialData.id, payload)
        : await createTask(payload)

      if (result.error) {
        toast.error(result.error)
      } else {
        toast.success(isEditing ? 'Task updated' : 'Task created')
        router.push(basePath)
        router.refresh()
      }
    } finally {
      setSaving(false)
    }
  }

  const updateField = (field: string, value: any) => {
    setForm(prev => ({ ...prev, [field]: value }))
    if (errors[field]) setErrors(prev => ({ ...prev, [field]: '' }))
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-8">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button
            type="button"
            onClick={() => router.back()}
            className="p-2 rounded-xl bg-slate-100 text-slate-500 hover:bg-slate-200 transition-colors"
          >
            <ArrowLeft size={18} />
          </button>
          <div>
            <h1 className="text-2xl font-black text-slate-900 uppercase tracking-tight">
              {isEditing ? 'Edit Task' : 'New Task'}
            </h1>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
              {isEditing ? 'Update task details' : 'Assign a new task'}
            </p>
          </div>
        </div>
        <button
          type="submit"
          disabled={saving}
          className="flex items-center gap-2 px-6 py-3 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all disabled:opacity-50"
        >
          {saving ? <Loader2 size={14} className="animate-spin" /> : <Save size={14} />}
          {saving ? 'Saving...' : 'Save Task'}
        </button>
      </div>

      {/* Form */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="space-y-2 md:col-span-2">
          <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">
            Title <span className="text-rose-500">*</span>
          </label>
          <input
            value={form.title}
            onChange={(e) => updateField('title', e.target.value)}
            placeholder="Task title"
            className={`w-full px-4 py-3 rounded-xl border ${errors.title ? 'border-rose-300 bg-rose-50' : 'border-slate-200 bg-white'} text-sm font-bold text-slate-900 outline-none focus:ring-2 focus:ring-slate-900/20 transition-all`}
          />
          {errors.title && <p className="text-[9px] font-bold text-rose-500">{errors.title}</p>}
        </div>

        <div className="space-y-2 md:col-span-2">
          <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Description</label>
          <textarea
            value={form.description}
            onChange={(e) => updateField('description', e.target.value)}
            placeholder="Describe the task in detail..."
            rows={4}
            className="w-full px-4 py-3 rounded-xl border border-slate-200 bg-white text-sm font-bold text-slate-900 outline-none focus:ring-2 focus:ring-slate-900/20 transition-all resize-none"
          />
        </div>

        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Assignee</label>
          <select
            value={form.assigned_to}
            onChange={(e) => updateField('assigned_to', e.target.value)}
            className="w-full px-4 py-3 rounded-xl border border-slate-200 bg-white text-sm font-bold text-slate-900 outline-none focus:ring-2 focus:ring-slate-900/20 transition-all"
          >
            <option value="">Unassigned</option>
            {employees.map(emp => (
              <option key={emp.id} value={emp.id}>{emp.full_name || 'Unknown'}</option>
            ))}
          </select>
        </div>

        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">
            Priority <span className="text-rose-500">*</span>
          </label>
          <select
            value={form.priority}
            onChange={(e) => updateField('priority', e.target.value)}
            className={`w-full px-4 py-3 rounded-xl border ${errors.priority ? 'border-rose-300 bg-rose-50' : 'border-slate-200 bg-white'} text-sm font-bold text-slate-900 outline-none focus:ring-2 focus:ring-slate-900/20 transition-all`}
          >
            {TASK_PRIORITIES.map(p => (
              <option key={p} value={p}>{p.charAt(0).toUpperCase() + p.slice(1)}</option>
            ))}
          </select>
          {errors.priority && <p className="text-[9px] font-bold text-rose-500">{errors.priority}</p>}
        </div>

        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Category</label>
          <select
            value={form.category}
            onChange={(e) => updateField('category', e.target.value)}
            className="w-full px-4 py-3 rounded-xl border border-slate-200 bg-white text-sm font-bold text-slate-900 outline-none focus:ring-2 focus:ring-slate-900/20 transition-all"
          >
            {TASK_CATEGORIES.map(c => (
              <option key={c} value={c}>{c.charAt(0).toUpperCase() + c.slice(1)}</option>
            ))}
          </select>
        </div>

        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Due Date</label>
          <input
            type="date"
            value={form.due_date}
            onChange={(e) => updateField('due_date', e.target.value)}
            className="w-full px-4 py-3 rounded-xl border border-slate-200 bg-white text-sm font-bold text-slate-900 outline-none focus:ring-2 focus:ring-slate-900/20 transition-all"
          />
        </div>

        <div className="space-y-4 md:col-span-2">
          <div className="flex items-center gap-3">
            <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Recurring Task</label>
            <button
              type="button"
              onClick={() => updateField('is_recurring', !form.is_recurring)}
              className={`relative w-12 h-6 rounded-full transition-all ${form.is_recurring ? 'bg-slate-900' : 'bg-slate-200'}`}
            >
              <div className={`absolute top-0.5 w-5 h-5 rounded-full bg-white shadow-sm transition-all ${form.is_recurring ? 'left-6' : 'left-0.5'}`} />
            </button>
          </div>

          {form.is_recurring && (
            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Recurrence Rule</label>
              <input
                value={form.recurrence_rule}
                onChange={(e) => updateField('recurrence_rule', e.target.value)}
                placeholder="e.g. every day, every week on Monday"
                className="w-full px-4 py-3 rounded-xl border border-slate-200 bg-white text-sm font-bold text-slate-900 outline-none focus:ring-2 focus:ring-slate-900/20 transition-all"
              />
            </div>
          )}
        </div>
      </div>
    </form>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { createClient } from '@/lib/supabase/client'
import { toast } from 'sonner'
import {
  ArrowLeft, Trash2, Edit3,
  Calendar, User, Package, Loader2, Send, AlertTriangle
} from 'lucide-react'
import {
  deleteTester, logTesterAction, markNeedsReplacement
} from '@/app/actions/store-ops/testers'
import { canDelete, canManageApprovals } from '@/lib/store-ops/permissions'
import type { TesterWithRelations } from '@/lib/store-ops/types'

interface TesterDetailProps {
  tester: TesterWithRelations
  userRole: string | null
  basePath: string
  canEdit: boolean
}

const conditionStyles: Record<string, { bg: string; text: string; label: string }> = {
  good: { bg: 'bg-emerald-50 border-emerald-100', text: 'text-emerald-600', label: 'Good' },
  fair: { bg: 'bg-amber-50 border-amber-100', text: 'text-amber-600', label: 'Fair' },
  poor: { bg: 'bg-orange-50 border-orange-100', text: 'text-orange-600', label: 'Poor' },
  finished: { bg: 'bg-rose-50 border-rose-100', text: 'text-rose-600', label: 'Finished' },
}

export default function TesterDetail({ tester, userRole, basePath, canEdit }: TesterDetailProps) {
  const router = useRouter()
  const supabase = createClient()

  const [currentTester, setCurrentTester] = useState(tester)
  const [comment, setComment] = useState('')
  const [submitting, setSubmitting] = useState(false)

  const style = conditionStyles[currentTester.condition] || conditionStyles.good
  const isAdmin = canDelete(userRole as 'admin' | 'manager' | 'employee' | null)
  const isManager = canManageApprovals(userRole as 'admin' | 'manager' | 'employee' | null)

  const daysLeft = currentTester.expiry_date
    ? Math.ceil((new Date(currentTester.expiry_date).getTime() - Date.now()) / (1000 * 60 * 60 * 24))
    : null

  const expiryStatus = daysLeft !== null
    ? daysLeft < 0 ? { label: 'Expired', class: 'text-rose-600' }
      : daysLeft <= 30 ? { label: `${daysLeft} days left`, class: 'text-amber-600' }
      : { label: `${daysLeft} days left`, class: 'text-slate-400' }
    : null

  const barColor = currentTester.remaining_percentage > 50 ? 'bg-emerald-500'
    : currentTester.remaining_percentage > 20 ? 'bg-amber-500' : 'bg-rose-500'

  useEffect(() => {
    const channel = supabase.channel(`tester_${tester.id}`)
      .on('postgres_changes',
        { event: '*', schema: 'public', table: 'testers', filter: `id=eq.${tester.id}` },
        (payload) => {
          if (payload.new) setCurrentTester(prev => ({ ...prev, ...payload.new as any }))
        }
      )
      .on('postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'tester_logs', filter: `tester_id=eq.${tester.id}` },
        async () => {
          const { data } = await supabase
            .from('tester_logs')
            .select('*, profiles:created_by(full_name)')
            .eq('tester_id', tester.id)
            .order('created_at', { ascending: false })
          if (data) {
            setCurrentTester(prev => ({ ...prev, tester_logs: data as any }))
          }
        }
      )
      .subscribe()

    return () => { supabase.removeChannel(channel) }
  }, [tester.id, supabase])

  const handleDelete = async () => {
    if (!confirm('Delete this tester permanently?')) return
    const result = await deleteTester(currentTester.id)
    if (result.error) toast.error(result.error)
    else {
      toast.success('Tester deleted')
      router.push(basePath)
    }
  }

  const handleMarkReplace = async () => {
    const result = await markNeedsReplacement(currentTester.id)
    if (result.error) toast.error(result.error)
    else {
      toast.success('Marked for replacement')
      setCurrentTester(prev => ({ ...prev, needs_replacement: true }))
    }
  }

  const handleLogAction = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!comment.trim()) return
    setSubmitting(true)
    const result = await logTesterAction(currentTester.id, 'comment', comment.trim())
    if (result.error) {
      toast.error(result.error)
    } else {
      setComment('')
    }
    setSubmitting(false)
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button
            onClick={() => router.back()}
            className="p-2 rounded-xl bg-slate-100 text-slate-500 hover:bg-slate-200 transition-colors"
          >
            <ArrowLeft size={18} />
          </button>
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-black text-slate-900 uppercase tracking-tight">
                {currentTester.product_name}
              </h1>
              <span className={`px-2.5 py-1 rounded-full text-[8px] font-black uppercase tracking-wider border ${style.bg} ${style.text}`}>
                {style.label}
              </span>
              {currentTester.needs_replacement && (
                <span className="px-2.5 py-1 rounded-full text-[8px] font-black uppercase tracking-wider border bg-rose-50 border-rose-200 text-rose-600">
                  Replace
                </span>
              )}
            </div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
              {currentTester.brand && `${currentTester.brand} `}
              {currentTester.shade && `• ${currentTester.shade}`}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {canEdit && (
            <button
              onClick={() => router.push(`${basePath}/${currentTester.id}/edit`)}
              className="flex items-center gap-1.5 px-4 py-2.5 bg-white border border-slate-200 text-slate-500 rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-slate-50 transition-all"
            >
              <Edit3 size={13} /> Edit
            </button>
          )}
          {isManager && !currentTester.needs_replacement && (
            <button onClick={handleMarkReplace} className="flex items-center gap-1.5 px-4 py-2.5 bg-rose-500 text-white rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-rose-600 transition-all">
              <AlertTriangle size={13} /> Mark Replace
            </button>
          )}
          {isAdmin && (
            <button onClick={handleDelete} className="flex items-center gap-1.5 px-4 py-2.5 bg-white border border-rose-200 text-rose-500 rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-rose-50 transition-all">
              <Trash2 size={13} /> Delete
            </button>
          )}
        </div>
      </div>

      {/* Content Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Details */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white border border-slate-200 rounded-2xl p-6 space-y-5">
            <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Tester Details</h2>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
              <DetailItem icon={Package} label="Product" value={currentTester.product_name} />
              <DetailItem icon={Package} label="Brand" value={currentTester.brand || '—'} />
              <DetailItem icon={Package} label="Shade" value={currentTester.shade || '—'} />
              <DetailItem icon={Calendar} label="Opened" value={currentTester.opened_date ? new Date(currentTester.opened_date).toLocaleDateString() : '—'} />
              <DetailItem icon={Calendar} label="Expiry" value={currentTester.expiry_date ? new Date(currentTester.expiry_date).toLocaleDateString() : '—'} />
              <DetailItem icon={Calendar} label="Condition" value={style.label} />
              <DetailItem icon={User} label="Created By" value={currentTester.profiles?.full_name || 'Unknown'} />
              <DetailItem icon={Calendar} label="Created" value={new Date(currentTester.created_at).toLocaleDateString()} />
            </div>
          </div>

          {/* Remaining % Bar */}
          <div className="bg-white border border-slate-200 rounded-2xl p-6">
            <div className="flex items-center justify-between mb-3">
              <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Remaining Product</h2>
              <span className="text-2xl font-black text-slate-900">{currentTester.remaining_percentage}%</span>
            </div>
            <div className="h-4 bg-slate-100 rounded-full overflow-hidden">
              <div
                className={`h-full rounded-full transition-all ${barColor}`}
                style={{ width: `${currentTester.remaining_percentage}%` }}
              />
            </div>
            {expiryStatus && (
              <p className={`text-[10px] font-bold mt-2 ${expiryStatus.class}`}>
                {expiryStatus.label}
              </p>
            )}
          </div>

          {/* Activity Log */}
          <div className="bg-white border border-slate-200 rounded-2xl p-6">
            <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">
              Activity Log ({currentTester.tester_logs?.length || 0})
            </h2>

            <div className="space-y-4 mb-6 max-h-[400px] overflow-y-auto">
              {currentTester.tester_logs && currentTester.tester_logs.length > 0 ? (
                currentTester.tester_logs.map((log) => (
                  <div key={log.id} className="flex gap-3 p-3 bg-slate-50 rounded-xl">
                    <div className="w-8 h-8 rounded-full bg-slate-900 text-white flex items-center justify-center text-[8px] font-black shrink-0 uppercase">
                      {(log as any).profiles?.full_name?.charAt(0) || '?'}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <span className="text-[10px] font-black text-slate-900 uppercase">
                          {(log as any).profiles?.full_name || 'Unknown'}
                        </span>
                        <span className="text-[8px] font-bold text-slate-400">
                          {new Date(log.created_at).toLocaleDateString()}
                        </span>
                      </div>
                      <p className="text-[10px] font-bold text-slate-500 uppercase tracking-wider mt-0.5">{log.action}</p>
                      {log.notes && <p className="text-xs font-bold text-slate-600 mt-0.5">{log.notes}</p>}
                    </div>
                  </div>
                ))
              ) : (
                <p className="text-[9px] font-bold text-slate-400 text-center py-6">No activity recorded</p>
              )}
            </div>

            <form onSubmit={handleLogAction} className="flex gap-3">
              <input
                value={comment}
                onChange={(e) => setComment(e.target.value)}
                placeholder="Add a note..."
                className="flex-1 px-4 py-2.5 rounded-xl border border-slate-200 text-sm font-bold text-slate-900 outline-none focus:ring-2 focus:ring-slate-900/20 transition-all"
              />
              <button
                type="submit"
                disabled={!comment.trim() || submitting}
                className="px-4 py-2.5 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all disabled:opacity-50 flex items-center gap-2"
              >
                {submitting ? <Loader2 size={14} className="animate-spin" /> : <Send size={14} />}
                Log
              </button>
            </form>
          </div>
        </div>

        {/* Sidebar */}
        <div className="space-y-6">
          <div className="bg-white border border-slate-200 rounded-2xl p-6">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Quick Info</h3>
            <div className="space-y-3">
              <StatRow label="Condition" value={style.label} valueClass={style.text} />
              <StatRow label="Remaining" value={`${currentTester.remaining_percentage}%`} />
              <StatRow label="Needs Replacement" value={currentTester.needs_replacement ? 'Yes' : 'No'} valueClass={currentTester.needs_replacement ? 'text-rose-600' : 'text-slate-400'} />
              <StatRow label="Status" value={expiryStatus?.label || 'No expiry'} valueClass={expiryStatus?.class} />
            </div>
          </div>

          <div className="bg-white border border-slate-200 rounded-2xl p-6">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Expiry Timeline</h3>
            <div className="space-y-4">
              {currentTester.opened_date && (
                <TimelineItem
                  icon={Calendar}
                  label="Opened"
                  date={currentTester.opened_date}
                  active
                />
              )}
              {currentTester.expiry_date && (
                <TimelineItem
                  icon={AlertTriangle}
                  label={daysLeft !== null && daysLeft < 0 ? 'Expired' : 'Expires'}
                  date={currentTester.expiry_date}
                  active
                />
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

function DetailItem({ icon: Icon, label, value }: { icon: any; label: string; value: string }) {
  return (
    <div className="space-y-1">
      <div className="flex items-center gap-1.5 text-[9px] font-bold text-slate-400 uppercase tracking-wider">
        <Icon size={11} />
        {label}
      </div>
      <p className="text-sm font-black text-slate-900">{value}</p>
    </div>
  )
}

function TimelineItem({ icon: Icon, label, date, active }: { icon: any; label: string; date: string; active?: boolean }) {
  return (
    <div className="flex gap-3">
      <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${active ? 'bg-slate-900 text-white' : 'bg-slate-100 text-slate-400'}`}>
        <Icon size={13} />
      </div>
      <div>
        <p className="text-[11px] font-black text-slate-900 uppercase">{label}</p>
        <p className="text-[9px] font-bold text-slate-500">{new Date(date).toLocaleDateString()}</p>
      </div>
    </div>
  )
}

function StatRow({ label, value, valueClass }: { label: string; value: string; valueClass?: string }) {
  return (
    <div className="flex items-center justify-between">
      <span className="text-[9px] font-bold text-slate-400 uppercase tracking-wider">{label}</span>
      <span className={`text-xs font-black ${valueClass || 'text-slate-900'}`}>{value}</span>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { createClient } from '@/lib/supabase/client'
import { Search, Filter, Plus, X, Loader2, FlaskConical } from 'lucide-react'
import { TESTER_CONDITIONS } from '@/lib/store-ops/constants'
import type { TesterWithRelations } from '@/lib/store-ops/types'
import TesterCard from './TesterCard'

interface TesterListProps {
  initialData: TesterWithRelations[]
  total: number
  page: number
  totalPages: number
  basePath: string
  canCreate: boolean
}

export default function TesterList({
  initialData, total, page: initialPage, totalPages: initialTotalPages, basePath, canCreate
}: TesterListProps) {
  const router = useRouter()
  const supabase = createClient()

  const [data, setData] = useState(initialData)
  const [totalCount, setTotalCount] = useState(total)
  const [currentPage, setCurrentPage] = useState(initialPage)
  const [totalPages, setTotalPages] = useState(initialTotalPages)
  const [loading, setLoading] = useState(false)

  const [search, setSearch] = useState('')
  const [conditionFilter, setConditionFilter] = useState('')
  const [replacementFilter, setReplacementFilter] = useState('')
  const [sortBy, setSortBy] = useState<'expiry_date' | 'created_at' | 'product_name'>('expiry_date')
  const [showFilters, setShowFilters] = useState(false)

  const fetchData = useCallback(async (pageNum: number) => {
    setLoading(true)
    let query = supabase
      .from('testers')
      .select(`
        *,
        profiles:created_by(full_name),
        tester_logs(*, profiles:created_by(full_name))
      `, { count: 'exact' })

    if (search) {
      query = query.or(`product_name.ilike.%${search}%,brand.ilike.%${search}%`)
    }
    if (conditionFilter) query = query.eq('condition', conditionFilter)
    if (replacementFilter === 'yes') query = query.eq('needs_replacement', true)
    if (replacementFilter === 'no') query = query.eq('needs_replacement', false)

    query = query.order(sortBy, { ascending: sortBy === 'expiry_date' ? true : false })

    const limit = 20
    const offset = (pageNum - 1) * limit
    query = query.range(offset, offset + limit - 1)

    const { data: results, count } = await query
    if (results) setData(results as unknown as TesterWithRelations[])
    if (count !== null) {
      setTotalCount(count)
      setTotalPages(Math.ceil(count / limit))
    }
    setLoading(false)
  }, [search, conditionFilter, replacementFilter, sortBy, supabase])

  useEffect(() => {
    fetchData(currentPage)
  }, [currentPage, fetchData])

  useEffect(() => {
    const channel = supabase.channel('testers_realtime')
      .on('postgres_changes',
        { event: '*', schema: 'public', table: 'testers' },
        () => { fetchData(currentPage) }
      )
      .on('postgres_changes',
        { event: '*', schema: 'public', table: 'tester_logs' },
        () => { fetchData(currentPage) }
      )
      .subscribe()

    return () => { supabase.removeChannel(channel) }
  }, [currentPage, fetchData, supabase])

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault()
    setCurrentPage(1)
    fetchData(1)
  }

  const clearFilters = () => {
    setSearch('')
    setConditionFilter('')
    setReplacementFilter('')
    setCurrentPage(1)
  }

  const hasFilters = search || conditionFilter || replacementFilter

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-black text-slate-900 uppercase tracking-tight">Testers</h1>
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
            {totalCount} tester{totalCount !== 1 ? 's' : ''}
          </p>
        </div>
        {canCreate && (
          <button
            onClick={() => router.push(`${basePath}/new`)}
            className="flex items-center gap-2 px-5 py-3 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all"
          >
            <Plus size={14} />
            New Tester
          </button>
        )}
      </div>

      <div className="flex items-center gap-3">
        <form onSubmit={handleSearch} className="flex-1 relative">
          <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
          <input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search by product name or brand..."
            className="w-full pl-11 pr-4 py-3 rounded-xl border border-slate-200 bg-white text-sm font-bold text-slate-900 outline-none focus:ring-2 focus:ring-slate-900/20 transition-all"
          />
        </form>
        <button
          onClick={() => setShowFilters(!showFilters)}
          className={`p-3 rounded-xl border transition-all ${showFilters || hasFilters ? 'bg-slate-900 text-white border-slate-900' : 'bg-white text-slate-400 border-slate-200 hover:border-slate-300'}`}
        >
          <Filter size={18} />
        </button>
      </div>

      {showFilters && (
        <div className="bg-slate-900 p-5 rounded-2xl space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Filters</h3>
            {hasFilters && (
              <button onClick={clearFilters} className="flex items-center gap-1 text-[9px] font-bold text-slate-400 hover:text-white transition-colors">
                <X size={12} /> Clear
              </button>
            )}
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
            <div className="space-y-1">
              <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest ml-1">Condition</label>
              <select
                value={conditionFilter}
                onChange={(e) => { setConditionFilter(e.target.value); setCurrentPage(1) }}
                className="w-full bg-slate-800 border-none rounded-xl px-3 py-2.5 text-[11px] font-bold text-white outline-none"
              >
                <option value="">All Conditions</option>
                {TESTER_CONDITIONS.map(c => (
                  <option key={c} value={c}>{c.charAt(0).toUpperCase() + c.slice(1)}</option>
                ))}
              </select>
            </div>
            <div className="space-y-1">
              <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest ml-1">Needs Replacement</label>
              <select
                value={replacementFilter}
                onChange={(e) => { setReplacementFilter(e.target.value); setCurrentPage(1) }}
                className="w-full bg-slate-800 border-none rounded-xl px-3 py-2.5 text-[11px] font-bold text-white outline-none"
              >
                <option value="">All</option>
                <option value="yes">Yes</option>
                <option value="no">No</option>
              </select>
            </div>
            <div className="space-y-1">
              <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest ml-1">Sort By</label>
              <select
                value={sortBy}
                onChange={(e) => { setSortBy(e.target.value as any); setCurrentPage(1) }}
                className="w-full bg-slate-800 border-none rounded-xl px-3 py-2.5 text-[11px] font-bold text-white outline-none"
              >
                <option value="expiry_date">Expiry Date</option>
                <option value="created_at">Recently Added</option>
                <option value="product_name">Product Name</option>
              </select>
            </div>
          </div>
        </div>
      )}

      {/* Desktop Table */}
      <div className="hidden md:block bg-white border border-slate-200 rounded-2xl overflow-hidden">
        <table className="w-full">
          <thead>
            <tr className="border-b border-slate-100">
              <th className="text-left px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Product</th>
              <th className="text-left px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Condition</th>
              <th className="text-left px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Remaining</th>
              <th className="text-left px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Expiry</th>
              <th className="text-left px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Replace</th>
              <th className="text-right px-5 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Created</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr>
                <td colSpan={6} className="py-20 text-center">
                  <Loader2 size={20} className="animate-spin mx-auto text-slate-300" />
                </td>
              </tr>
            ) : data.length === 0 ? (
              <tr>
                <td colSpan={6} className="py-20 text-center">
                  <div className="flex flex-col items-center gap-2">
                    <FlaskConical size={32} className="text-slate-200" />
                    <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">No testers found</p>
                  </div>
                </td>
              </tr>
            ) : (
              data.map(item => {
                const condStyle = condStyles[item.condition] || condStyles.good
                const daysLeft = item.expiry_date
                  ? Math.ceil((new Date(item.expiry_date).getTime() - Date.now()) / (1000 * 60 * 60 * 24))
                  : null
                const barColor = item.remaining_percentage > 50 ? 'bg-emerald-500' : item.remaining_percentage > 20 ? 'bg-amber-500' : 'bg-rose-500'
                return (
                  <tr
                    key={item.id}
                    onClick={() => router.push(`${basePath}/${item.id}`)}
                    className="border-b border-slate-50 hover:bg-slate-50 cursor-pointer transition-colors"
                  >
                    <td className="px-5 py-4">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-xl bg-slate-100 flex items-center justify-center shrink-0">
                          <FlaskConical size={16} className="text-slate-400" />
                        </div>
                        <div>
                          <p className="text-xs font-black text-slate-900 uppercase">{item.product_name}</p>
                          {item.brand && <p className="text-[9px] font-bold text-slate-400">{item.brand}</p>}
                        </div>
                      </div>
                    </td>
                    <td className="px-5 py-4">
                      <span className={`px-2 py-0.5 rounded-full text-[8px] font-black uppercase tracking-wider ${condStyle.bg} ${condStyle.text}`}>
                        {item.condition}
                      </span>
                    </td>
                    <td className="px-5 py-4">
                      <div className="flex items-center gap-2">
                        <div className="w-16 h-1.5 bg-slate-100 rounded-full overflow-hidden">
                          <div className={`h-full rounded-full ${barColor}`} style={{ width: `${item.remaining_percentage}%` }} />
                        </div>
                        <span className="text-[10px] font-bold text-slate-500">{item.remaining_percentage}%</span>
                      </div>
                    </td>
                    <td className="px-5 py-4">
                      {daysLeft !== null ? (
                        <span className={`text-[10px] font-bold ${daysLeft < 0 ? 'text-rose-600' : daysLeft <= 30 ? 'text-amber-600' : 'text-slate-500'}`}>
                          {daysLeft < 0 ? 'Expired' : `${daysLeft}d left`}
                        </span>
                      ) : (
                        <span className="text-[10px] font-bold text-slate-300">—</span>
                      )}
                    </td>
                    <td className="px-5 py-4">
                      {item.needs_replacement ? (
                        <span className="px-2 py-0.5 rounded-full text-[8px] font-black uppercase tracking-wider bg-rose-50 text-rose-600">Yes</span>
                      ) : (
                        <span className="text-[10px] font-bold text-slate-300">No</span>
                      )}
                    </td>
                    <td className="px-5 py-4 text-right">
                      <p className="text-[9px] font-bold text-slate-400">{new Date(item.created_at).toLocaleDateString()}</p>
                    </td>
                  </tr>
                )
              })
            )}
          </tbody>
        </table>
      </div>

      {/* Mobile Cards */}
      <div className="md:hidden space-y-3">
        {loading ? (
          <div className="py-20 flex justify-center">
            <Loader2 size={24} className="animate-spin text-slate-300" />
          </div>
        ) : data.length === 0 ? (
          <div className="py-20 text-center">
            <div className="flex flex-col items-center gap-2">
              <FlaskConical size={40} className="text-slate-200" />
              <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">No testers found</p>
            </div>
          </div>
        ) : (
          data.map(item => (
            <TesterCard
              key={item.id}
              id={item.id}
              product_name={item.product_name}
              brand={item.brand}
              shade={item.shade}
              condition={item.condition}
              remaining_percentage={item.remaining_percentage}
              expiry_date={item.expiry_date}
              needs_replacement={item.needs_replacement}
              basePath={basePath}
            />
          ))
        )}
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-center gap-2">
          <button
            onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
            disabled={currentPage === 1}
            className="px-4 py-2 rounded-xl bg-white border border-slate-200 text-[10px] font-black uppercase tracking-widest text-slate-500 hover:bg-slate-50 disabled:opacity-30 transition-all"
          >
            Prev
          </button>
          {Array.from({ length: totalPages }, (_, i) => i + 1)
            .filter(p => p === 1 || p === totalPages || Math.abs(p - currentPage) <= 1)
            .map((p, idx, arr) => (
              <span key={p} className="flex items-center gap-1">
                {idx > 0 && arr[idx - 1] !== p - 1 && (
                  <span className="text-slate-300 text-[10px] font-bold px-1">...</span>
                )}
                <button
                  onClick={() => setCurrentPage(p)}
                  className={`w-9 h-9 rounded-xl text-[10px] font-black transition-all ${
                    currentPage === p
                      ? 'bg-slate-900 text-white'
                      : 'bg-white border border-slate-200 text-slate-500 hover:bg-slate-50'
                  }`}
                >
                  {p}
                </button>
              </span>
            ))}
          <button
            onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
            disabled={currentPage === totalPages}
            className="px-4 py-2 rounded-xl bg-white border border-slate-200 text-[10px] font-black uppercase tracking-widest text-slate-500 hover:bg-slate-50 disabled:opacity-30 transition-all"
          >
            Next
          </button>
        </div>
      )}
    </div>
  )
}

const condStyles: Record<string, { bg: string; text: string }> = {
  good: { bg: 'bg-emerald-50', text: 'text-emerald-600' },
  fair: { bg: 'bg-amber-50', text: 'text-amber-600' },
  poor: { bg: 'bg-orange-50', text: 'text-orange-600' },
  finished: { bg: 'bg-rose-50', text: 'text-rose-600' },
}

// lib/push.ts

import webpush from 'web-push';
import { createClient } from '@/lib/supabase/server';

const VAPID_PUBLIC_KEY = process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY;
const VAPID_PRIVATE_KEY = process.env.VAPID_PRIVATE_KEY;

export async function sendPushNotification(title: string, body: string, url: string = '/') {
    if (!VAPID_PUBLIC_KEY || !VAPID_PRIVATE_KEY) {
        console.warn('VAPID keys not set. Skipping push notification.');
        return;
    }

    try {
        // VAPID keys must not have padding (=) and must be trimmed
        webpush.setVapidDetails(
            'mailto:admin@themakeupstore.in',
            VAPID_PUBLIC_KEY.trim().replace(/=/g, ''),
            VAPID_PRIVATE_KEY.trim().replace(/=/g, '')
        );
    } catch (e) {
        console.error('Failed to initialize webpush:', e);
        return;
    }

    const supabase = await createClient();

    // 1. Fetch all admin profiles
    const { data: admins } = await supabase
        .from('profiles')
        .select('id')
        .eq('role', 'admin');

    if (!admins || admins.length === 0) return;

    const adminIds = admins.map(a => a.id);

    // 2. Fetch all push subscriptions for these admins
    const { data: subscriptions } = await supabase
        .from('push_subscriptions')
        .select('subscription_json')
        .in('user_id', adminIds);

    if (!subscriptions || subscriptions.length === 0) return;

    const payload = JSON.stringify({ title, body, url });

    // 3. Send notifications in parallel
    const sendPromises = subscriptions.map(async (subRecord: any) => {
        try {
            await webpush.sendNotification(subRecord.subscription_json, payload);
        } catch (error: any) {
            console.error('Push failed for subscription:', error.endpoint, error.statusCode);
            // Optional: If error.statusCode is 410 or 404, the subscription is expired/invalid
            if (error.statusCode === 410 || error.statusCode === 404) {
                // Delete invalid subscription
                await supabase
                    .from('push_subscriptions')
                    .delete()
                    .match({ 'subscription_json->endpoint': subRecord.subscription_json.endpoint });
            }
        }
    });

    await Promise.allSettled(sendPromises);
}
